import { TriangleAlert } from "lucide-react";
import * as React from "react";
import { Pill } from "@/components/ui/pill";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { cn } from "@/lib/utils";

/**
 * Breakdown content — what a "+N" chip or a total opens.
 *
 * The anatomy is the DS's own, copied from `InvoiceCard` (Figma "Invoice"
 * 27599:62303) — the only hover-card content pattern in the DS, and the one the
 * DS DataTable puts in its Amount column:
 *
 *   flex w-full flex-col gap-4
 *     h4  text-base font-semibold          ← title, foreground (not a muted label)
 *     border-t border-dashed border-border  ← rule under the title
 *     flex flex-col gap-1                   ← detail rows
 *       flex items-center justify-between text-sm text-muted-foreground
 *       …value spans carry tabular-nums
 *     border-t border-dashed border-border  ← rule before the total
 *     flex items-center justify-between text-base font-semibold  ← total
 *
 * The container keeps `HoverCardContent`'s default `p-4`; width is the only
 * override, which is the one the DS itself makes (`w-[380px]` for the Invoice
 * card). Rows with no `value` render as a plain list (the products case).
 */
export interface BreakdownRow {
  label: string;
  /** Omit for a label-only list. */
  value?: string;
  /**
   * A second line under the label — what the row carries (Pavan, 2026-10-14:
   * an asset's products under its name, its capacity as the value).
   */
  sub?: string;
}

/**
 * A GROUPED TABLE instead of rows (Pavan, 2026-10-14 — a ship-to's products,
 * each with its assets, their type and capacity). Same card: title, dashed
 * rule, the card's own type sizes; a header row, then a band per group.
 */
export interface BreakdownTable {
  columns: { label: string; align?: "left" | "right" }[];
  groups: { label: string; rows: string[][] }[];
}

export interface BreakdownCardProps {
  title: string;
  rows: BreakdownRow[];
  table?: BreakdownTable;
  /** Renders the dashed rule + bold total row. Omit to end after the rows. */
  total?: { label: string; value: string };
  /** WARNINGS, after the total (Pavan, 2026-10-20) — red, an alert mark each:
      what the figure means will go wrong. */
  warnings?: string[];
}

export function BreakdownCard({ title, rows, table, total, warnings }: BreakdownCardProps) {
  return (
    <div className="flex w-full flex-col gap-4">
      <h4 className="text-base font-semibold">{title}</h4>
      <div className="border-t border-dashed border-border" />

      {table && (
        <table className="w-full table-fixed text-sm">
          <thead>
            <tr className="text-xs text-muted-foreground">
              {table.columns.map((c) => (
                <th key={c.label} className={cn("pb-1.5 font-medium", c.align === "right" ? "" : "text-left")}>
                  {c.label}
                </th>
              ))}
            </tr>
          </thead>
          {table.groups.map((g) => (
            <tbody key={g.label}>
              {/* THE GROUP — its name on a quiet band across the table; an
                  unnamed group (a plain table) has no band. */}
              {g.label && <tr>
                <td colSpan={table.columns.length} className="pt-2">
                  <span className="block rounded-sm bg-fp-table-header px-2 py-1 text-xs font-semibold text-foreground">
                    {g.label}
                  </span>
                </td>
              </tr>}
              {g.rows.map((r, i) => (
                <tr key={i} className="text-muted-foreground">
                  {r.map((cell, j) => (
                    <td
                      key={j}
                      /* THE NAME TRUNCATES; the rest wrap, so a list of
                         products is read whole. */
                      className={cn(
                        "py-1 pr-2 align-top",
                        j === 0 ? "truncate pl-2 text-foreground" : "break-words",
                        table.columns[j]?.align === "right" && "text-right tabular-nums"
                      )}
                      title={cell}
                    >
                      {cell}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          ))}
        </table>
      )}

      <div className="flex flex-col gap-1">
        {rows.map((row, i) => (
          <div
            key={`${row.label}-${i}`}
            className={cn(
              "flex justify-between gap-6 text-sm text-muted-foreground",
              row.sub ? "items-baseline py-0.5" : "items-center"
            )}
          >
            {row.sub ? (
              <span className="flex min-w-0 flex-col">
                <span className="truncate text-foreground">{row.label}</span>
                <span className="text-xs">{row.sub}</span>
              </span>
            ) : (
              <span className="min-w-0 truncate">{row.label}</span>
            )}
            {row.value && (
              <span className="shrink-0 tabular-nums">{row.value}</span>
            )}
          </div>
        ))}
      </div>

      {total && (
        <>
          <div className="border-t border-dashed border-border" />
          <div className="flex items-center justify-between gap-6 text-base font-semibold">
            <span>{total.label}</span>
            <span className="tabular-nums">{total.value}</span>
          </div>
        </>
      )}

      {warnings && warnings.length > 0 && (
        <ul className="flex flex-col gap-1.5">
          {warnings.map((w) => (
            <li key={w} className="flex items-start gap-2 text-sm text-status-failed">
              <TriangleAlert aria-hidden className="mt-0.5 size-4 shrink-0" />
              <span>{w}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/*
  ONE WAY TO OPEN A BREAKDOWN, EVERYWHERE (Pavan, 2026-10-14). A "+N" chip —
  or, where the whole cell IS the figure (a quantity), the figure — opens the
  card ON CLICK, above the cell. Not hover: touch cannot hover, and a card
  that appears under a passing pointer is one nobody asked for. The press
  stays in the cell: a row that opens its record on click must not open it
  as well.
*/
export function BreakdownPopover({
  trigger,
  label,
  card,
  width = 280,
  align = "start",
  className,
}: {
  /** The pressable face — a chip, or the figure. */
  trigger: React.ReactNode;
  /** What the press does, for a screen reader. */
  label: string;
  card: BreakdownCardProps;
  width?: number;
  align?: "start" | "end";
  className?: string;
}) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={label}
          onClick={(e) => e.stopPropagation()}
          className={cn(
            "shrink-0 cursor-pointer rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring/50",
            className
          )}
        >
          {trigger}
        </button>
      </PopoverTrigger>
      <PopoverContent
        align={align}
        side="top"
        style={{ width }}
        className="max-h-96 overflow-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <BreakdownCard {...card} />
      </PopoverContent>
    </Popover>
  );
}

/** The "+N" chip that opens a breakdown. */
export function OverflowChip({
  count,
  label,
  card,
  width,
}: {
  count: number;
  label: string;
  card: BreakdownCardProps;
  width?: number;
}) {
  return (
    <BreakdownPopover
      label={label}
      card={card}
      width={width}
      trigger={<Pill className="cursor-pointer tabular-nums">+{count}</Pill>}
    />
  );
}

import { ChevronLeft, ChevronRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import { DateField } from "@/components/ui/date-picker";
import { formatFullDate, startOfDay } from "./data";

/**
 * Delivery-date filter — ‹ date › stepper with a calendar picker.
 *
 * Defaults to today and steps a day at a time in either direction, so past and
 * future dates are both reachable. The pill opens the shared date picker in
 * its one-date form — Today is its first preset.
 *
 * Sits in the toolbar rather than inside the Filters panel: it is the one filter
 * whose current value has to stay legible at a glance, since every row on screen
 * is scoped by it.
 */
export interface DateFilterProps {
  value: Date;
  onChange: (next: Date) => void;
}

export function DateFilter({ value, onChange }: DateFilterProps) {
  const step = (days: number) => {
    const next = new Date(value);
    next.setDate(next.getDate() + days);
    onChange(startOfDay(next));
  };

  return (
    <div className="flex items-center gap-1">
      <Button
        variant="outline"
        size="icon-sm"
        aria-label="Previous day"
        onClick={() => step(-1)}
      >
        <ChevronLeft />
      </Button>

      {/* THE SHARED PICKER, one date (DS ui §10p). */}
      <DateField value={value} onChange={(d) => d && onChange(startOfDay(d))} align="end">
        <Button
          variant="outline"
          size="sm"
          aria-label={`Delivery date: ${formatFullDate(value)}. Pick a date`}
        >
          {formatFullDate(value)}
        </Button>
      </DateField>

      <Button
        variant="outline"
        size="icon-sm"
        aria-label="Next day"
        onClick={() => step(1)}
      >
        <ChevronRight />
      </Button>
    </div>
  );
}

import * as React from "react";
import { ArrowDown, ArrowUp, ChevronRight, ChevronsUpDown } from "lucide-react";
import { cn } from "@/lib/utils";
import { useA11y } from "@/components/theme/a11y";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { OverflowChip, type BreakdownRow } from "./BreakdownCard";
import {
  GroupHeaderRow,
  TableColumnHeader,
  useTableColumns,
  type GroupNode,
} from "@/components/tables-layout";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

/**
 * Generic list table — the chrome only, with cells supplied by the caller.
 *
 * The chrome is the DS DataTable's (Figma 28165:3758) and is copied from
 * FuelOrdersTable rather than re-derived, so the three lists are identical
 * where they should be: outer stroke on `border`, sticky Surface-1a header with
 * a bottom hairline so rows scroll under it, 40px header row, 56px body rows,
 * px-3 cells, the asc → desc → unsorted sort glyph cycle, and a pinned trailing
 * actions column whose opaque fill re-applies the row's hover/selected tint as a
 * `before` overlay (otherwise the pinned cell hides it).
 *
 * FuelOrdersTable is deliberately NOT refactored onto this. Its Product and Tags
 * cells carry measured-width truncation with a ResizeObserver, which nothing
 * else needs; moving it would be churn without benefit. This exists so Asset
 * Orders and Customers do not each re-copy the chrome a third and fourth time.
 *
 * DS FOLLOW-UP: this shell, `TwoLineCell` and `OverflowBadge` are not
 * screen-specific. They belong beside `tables-layout/DataTable` once the DS
 * version can take a column set and a cell renderer as props.
 */

/** A value that reads as one thing — a record number or code (no spaces),
    or a date ("Oct 23, 2026"). */
const ONE_LINE = /^(\S+|[A-Z][a-z]{2} \d{1,2}, \d{4})$/;

export interface ListColumn<K extends string> {
  key: K;
  label: string;
  width: number;
  sortable?: boolean;
  /**
   * `right` for money and for counts that are compared down the column —
   * the digits line up and the eye reads magnitude without reading numbers.
   * `center` for a short count that is READ rather than compared, where a
   * right edge miles from the header looks like a mistake.
   */
  align?: "left" | "right" | "center";
}

export interface ListSort<K extends string> {
  key: K;
  dir: "asc" | "desc";
}

export interface ListTableProps<Row, K extends string> {
  /** A ROW ABOVE THE HEADER, inside the table's frame and outside its scroll —
   *  for the table's own tools (see `ListToolbarProps.tableToolsInto`). */
  topBar?: React.ReactNode;
  /** Every cell sits at the top of its row — for rows that grow tall with
   *  stacked lines, so the record's own cells read first. */
  alignTop?: boolean;
  rows: Row[];
  columns: ListColumn<K>[];
  hidden?: Set<K>;
  sort: ListSort<K> | null;
  onSort: (key: K) => void;
  /** Stable identity for the React key. */
  rowId: (row: Row) => string;
  /** Cell content per column. `actions` is supplied by this component. */
  renderCell: (row: Row, key: K) => React.ReactNode;
  /** Opens the row's side sheet, via the pinned chevron. */
  onOpenRow?: (row: Row) => void;
  /** Accessible label for that chevron, e.g. `Open order 4592866`. */
  openLabel: (row: Row) => string;
  /** Which column key holds the pinned chevron. */
  actionsKey: K;
  /**
   * SELECTION IS OPT-IN. A list with nothing to do to a selection should not
   * spend 44px on a checkbox column that leads nowhere, so the column exists
   * only when the handlers for it do — the same rule the bulk bar follows.
   */
  selectedIds?: ReadonlySet<string>;
  onToggleRow?: (id: string) => void;
  /** `next` is the state the header checkbox is moving TO, so the caller does
   *  not have to re-derive it from the current selection. */
  onToggleAll?: (next: boolean) => void;
  /**
   * Skeleton rows in place of content. Not a spinner: a list that collapses to
   * a spinner loses its own height, and the page jumps when the rows land.
   */
  loading?: boolean;
  skeletonRows?: number;
  /**
   * Column order, as keys. Supply with `onReorderColumns` to keep it in a saved
   * view; leave both off and the table remembers it for the session only. The
   * pinned chevron column never moves.
   */
  columnOrder?: string[];
  onReorderColumns?: (next: string[]) => void;
  /** Reader-set column widths in px, by key. Same dual-mode as the order. */
  columnWidths?: Record<string, number>;
  onResizeColumns?: (next: Record<string, number>) => void;
  /**
   * Grouped render list from `groupRows`. Omitted, the table renders `rows`
   * flat — which is what every ungrouped list does.
   */
  nodes?: GroupNode<Row>[];
  collapsedGroups?: ReadonlySet<string>;
  onToggleGroupCollapse?: (id: string) => void;
  /**
   * A BOX PER COLUMN, UNDER THE HEADERS.
   *
   * The question "where is the Halvorsen order" is asked OF a column, so it is
   * answered at the column. A single search box asks it of the whole row and
   * brings back everything that mentions the word anywhere; a popover that
   * searches one named column asks it properly but only once, so two
   * conditions meant two searches and remembering the first.
   *
   * The boxes are AND-ed, because that is what typing in two of them looks
   * like it should do. The row only exists while the reader has asked for it —
   * see `ListToolbarProps.onToggleColumnFilters` — because 40px of empty
   * inputs above every table is a permanent cost for an occasional question.
   */
  columnFilters?: Record<string, string>;
  onColumnFilterChange?: (key: K, value: string) => void;
  showColumnFilters?: boolean;
  /** What one record is called in a group header — "asset", "account". */
  groupNoun?: string;
  /** Unit for the summed measure the headers carry, e.g. `gal`. */
  groupUnit?: string;
  /**
   * A NESTED LAYER — the DS expandable row (`tables-layout/DataTable`,
   * Pavan, 2026-10-17). Given, the first column's cell leads with a small
   * chevron that turns down and opens this content in a full-width row
   * beneath: pinned to the visible width, WHITE (the content layer), and a
   * 2px GREEN rail that runs unbroken from the parent row's left edge into
   * it. The open parent keeps a tint and drops its bottom divider (DS ui
   * §10j).
   */
  renderExpanded?: (row: Row) => React.ReactNode;
  /** The chevron's label, e.g. `Show tanks for REQ-1115`. */
  expandLabel?: (row: Row, open: boolean) => string;
}

export function ListTable<Row, K extends string>({
  rows,
  columns,
  hidden,
  sort,
  onSort,
  rowId,
  renderCell,
  onOpenRow,
  openLabel,
  actionsKey,
  selectedIds,
  onToggleRow,
  onToggleAll,
  loading = false,
  skeletonRows = 10,
  nodes,
  collapsedGroups,
  onToggleGroupCollapse,
  groupNoun = "record",
  groupUnit = "",
  columnOrder,
  onReorderColumns,
  columnWidths,
  onResizeColumns,
  columnFilters,
  onColumnFilterChange,
  showColumnFilters = false,
  renderExpanded,
  expandLabel,
  alignTop = false,
  topBar,
}: ListTableProps<Row, K>) {
  const expandable = Boolean(renderExpanded);
  const [expanded, setExpanded] = React.useState<ReadonlySet<string>>(() => new Set());
  const toggleExpand = (id: string) =>
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  /* THE FRAME'S WIDTH — what the columns fill, and what a nested layer
     spans (the visible width, not the scrolled one). */
  const frame = React.useRef<HTMLDivElement>(null);
  const [frameWidth, setFrameWidth] = React.useState<number | undefined>();
  React.useEffect(() => {
    if (!frame.current) return;
    const el = frame.current;
    const ro = new ResizeObserver(() => setFrameWidth(el.clientWidth));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  /* THE PINNED CHEVRON IS THE FRAME, not a column: it is how a row is opened
     and it is stuck to the right edge so it survives a sideways scroll. It
     does not move, and nothing can be dropped past it. */
  /* Columns move and resize because the DS header does it — see
     `useTableColumns`. Nothing here but which column is structure. */
  const cols = useTableColumns({
    keys: React.useMemo(() => columns.map((c) => c.key), [columns]),
    fixed: React.useMemo(() => [actionsKey], [actionsKey]),
    order: columnOrder,
    onOrderChange: onReorderColumns,
    widths: columnWidths,
    onWidthsChange: onResizeColumns,
  });
  /* NO CHEVRON COLUMN (Pavan, 2026-10-19): the row itself opens the
     record — a click anywhere on it, or Enter on a focused row — so the
     pinned chevron cell at the end is gone from every list. `actionsKey`
     names that column so it is dropped here. */
  const visible = cols.arrange(columns.filter((c) => !hidden?.has(c.key) && c.key !== actionsKey));

  /* THE CHECKBOX COLUMN IS NOT A COLUMN. It cannot be hidden, reordered,
     resized or sorted, so it sits outside `cols` entirely and is drawn as a
     fixed 44px cell at the head of every row — the mirror of the pinned
     chevron at the tail. */
  const selectable = Boolean(selectedIds && onToggleRow);
  const ids = rows.map(rowId);
  const allSelected = selectable && ids.length > 0 && ids.every((id) => selectedIds!.has(id));
  const someSelected = selectable && ids.some((id) => selectedIds!.has(id));
  const span = visible.length + (selectable ? 1 : 0);
  /* NO EMPTY SPACE ON THE RIGHT, EVER (Pavan, 2026-10-22). Each column starts
     at the width its longest value needs (DS ui §10p); when the table is
     narrower than its frame, the spare width goes to the columns that hold
     the most — a column gets a share in proportion to how far it is wider
     than 120px, so an icon, a count or a short code stays as it is and a
     name, an address or a contact takes the room. Wider than the frame, the
     table scrolls. */
  /* RECORD NUMBERS AND DATES STAY ON ONE LINE (Pavan, 2026-10-23). At a
     bigger Text size the other cells wrap inside their column, but a value
     like "D-105370" or "Oct 23, 2026" broken in two stops reading as one, so
     its column widens by exactly what the value lacks. Measured after paint;
     it only ever grows while the text size holds, so it can't see-saw. */
  const textSize = useA11y().text;
  const [oneLine, setOneLine] = React.useState<{ at: number; need: Record<string, number> }>({ at: 0, need: {} });
  const need = oneLine.at === textSize ? oneLine.need : {};
  React.useLayoutEffect(() => {
    const root = frame.current;
    if (!root || textSize === 0) return;
    const lead = selectedIds && onToggleRow ? 1 : 0;
    const next: Record<string, number> = { ...need };
    let grew = false;
    root.querySelectorAll<HTMLTableRowElement>("tbody tr").forEach((tr) => {
      if (tr.children.length !== visible.length + lead) return;
      visible.forEach((c, i) => {
        const td = tr.children[i + lead] as HTMLElement;
        td.querySelectorAll<HTMLElement>(".truncate").forEach((el) => {
          if (!ONE_LINE.test(el.textContent?.trim() ?? "")) return;
          el.dataset.oneLine = "";
          const short = el.scrollWidth - el.clientWidth;
          if (short <= 1) return;
          const want = Math.ceil(td.offsetWidth + short);
          if (want > (next[c.key] ?? 0)) {
            next[c.key] = want;
            grew = true;
          }
        });
      });
    });
    if (grew || oneLine.at !== textSize) setOneLine({ at: textSize, need: next });
    /* Re-measured when the text size, the rows or the columns change. */
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [textSize, rows, frameWidth, visible.map((c) => c.key).join(), oneLine]);
  const base = visible.map((c) => Math.max(cols.widthOf(c), need[c.key] ?? 0));
  const widths = (() => {
    const lead = selectable ? 44 : 0;
    const spare = (frameWidth ?? 0) - lead - base.reduce((a, b) => a + b, 0);
    if (spare <= 0) return base;
    const weight = base.map((w) => Math.max(0, w - 120));
    const total = weight.reduce((a, b) => a + b, 0) || base.reduce((a, b) => a + b, 0);
    const share = total === 0 ? base.map(() => 0) : (weight.some((w) => w > 0) ? weight : base).map((w) => w / total);
    const out = base.map((w, i) => Math.floor(w + spare * share[i]));
    /* What rounding left goes on the widest column, so the edge lands exactly. */
    const left = (frameWidth ?? 0) - lead - out.reduce((a, b) => a + b, 0);
    const widest = out.indexOf(Math.max(...out));
    if (widest >= 0) out[widest] += Math.max(0, left);
    return out;
  })();

  const body = (
    <div
      ref={frame}
      className={cn(
        "overflow-auto [&_[data-slot=table-container]]:overflow-visible",
        topBar ? "min-h-0 flex-1" : "h-full rounded-md border border-border"
      )}
    >
      <Table style={{ tableLayout: "fixed", width: widths.reduce((a, b) => a + b, selectable ? 44 : 0) }}>
        <colgroup>
          {selectable && <col style={{ width: "44px" }} />}
          {visible.map((c, i) => (
            <col key={c.key} style={{ width: `${widths[i]}px` }} />
          ))}
        </colgroup>
        <TableHeader className="sticky top-0 z-20">
          <TableRow className="h-10">
            {selectable && (
              <TableHead className="border-b border-fp-outline-1 bg-fp-table-header px-3">
                <Checkbox
                  checked={allSelected ? true : someSelected ? "indeterminate" : false}
                  onCheckedChange={() => onToggleAll?.(!allSelected)}
                  aria-label={allSelected ? "Clear selection" : "Select all rows on this page"}
                />
              </TableHead>
            )}
            {visible.map((col) => {
              const active = sort?.key === col.key;
              /* THE SORTED COLUMN (Pavan, 2026-10-21): a real arrow, not a
                 chevron, on a darker grey header; its cells a very light grey. */
              const SortIcon = !active
                ? ChevronsUpDown
                : sort.dir === "asc"
                  ? ArrowUp
                  : ArrowDown;
              return (
                <TableColumnHeader
                  key={col.key}
                  cols={cols}
                  col={col}
                  aria-sort={
                    active
                      ? sort.dir === "asc"
                        ? "ascending"
                        : "descending"
                      : undefined
                  }
                  className={cn(
                    "border-b border-fp-outline-1 bg-fp-table-header px-3 text-xs font-medium text-muted-foreground",
                    col.key === actionsKey && "sticky right-0 z-30"
                  )}
                >
                  {col.label && col.sortable ? (
                    <button
                      type="button"
                      onClick={() => onSort(col.key)}
                      aria-label={`Sort by ${col.label}`}
                      className={cn(
                        "inline-flex items-center gap-1 outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50",
                        active && "text-foreground"
                      )}
                    >
                      {col.label}
                      <SortIcon
                        className={cn(
                          "size-3.5",
                          active ? "opacity-100" : "opacity-50"
                        )}
                      />
                    </button>
                  ) : col.label ? (
                    <span>{col.label}</span>
                  ) : null}
                </TableColumnHeader>
              );
            })}
          </TableRow>
          {showColumnFilters && onColumnFilterChange && (
            /* THE SECOND HEADER ROW, not a first body row: it scrolls and
               sticks with the headers it belongs to, and the table's own
               `<thead>` is what tells a screen reader these are not records. */
            /* THE BAND IS QUIETER THAN THE HEADER IT SITS UNDER. At the same
               fill the two read as one 80px header, and the boxes looked like
               part of the column names rather than something you do to them.
               On the content layer's own surface the strip recedes and the
               inputs are the only thing in it with an edge — which is right,
               because they are the only thing in it you can touch. */
            <TableRow className="h-11 hover:bg-transparent">
              {selectable && (
                <TableHead className="border-b border-fp-outline-1 bg-fp-surface-1b px-3" />
              )}
              {visible.map((col) => (
                <TableHead
                  key={col.key}
                  className={cn(
                    "border-b border-fp-outline-1 bg-fp-surface-1b px-2",
                    col.key === actionsKey && "sticky right-0 z-30"
                  )}
                >
                  {col.label ? (
                    <Input
                      value={columnFilters?.[col.key] ?? ""}
                      onChange={(e) => onColumnFilterChange(col.key, e.target.value)}
                      /* THE PLACEHOLDER GOES WHERE IT WOULD BE CUT. A column
                         narrow enough to clip the word shows an empty box
                         instead — "Filte" reads as a bug, and the row of
                         identical boxes has already said what they are. */
                      placeholder={(columnWidths?.[col.key] ?? col.width) >= 96 ? "Filter…" : ""}
                      aria-label={`Filter by ${col.label}`}
                      /* `data-no-row-open` keeps a click in the box from being
                         read as a click on the row it sits above. */
                      data-no-row-open
                      /* `rounded-md` and no shadow — the DS's field shape.
                         A pill is the chip vocabulary, and a raised field in a
                         strip of fields lifts a row of boxes off a surface
                         they belong to. */
                      className="h-7 rounded-md px-2.5 text-xs shadow-none"
                    />
                  ) : null}
                </TableHead>
              ))}
            </TableRow>
          )}
        </TableHeader>
        <TableBody>
          {loading
            ? Array.from({ length: skeletonRows }, (_, i) => (
                <TableRow key={`sk-${i}`} className="h-14">
                  {selectable && (
                    <TableCell className="px-3">
                      <Skeleton className="size-4 rounded-[4px]" />
                    </TableCell>
                  )}
                  {visible.map((col) => (
                    <TableCell key={col.key} className="px-3">
                      {col.key === actionsKey ? null : (
                        <Skeleton
                          className="h-4"
                          /* Widths vary per column and per row so the block
                             reads as text arriving, not as a loading bar. */
                          style={{ width: `${45 + ((i * 17 + col.key.length * 11) % 45)}%` }}
                        />
                      )}
                    </TableCell>
                  ))}

                </TableRow>
              ))
            : (nodes ??
            rows.map((row) => ({
              kind: "row" as const,
              id: rowId(row),
              depth: 0,
              row,
            }))
          ).map((node) =>
            node.kind === "group" ? (
              <GroupHeaderRow
                key={node.id}
                colSpan={span}
                depth={node.depth}
                label={node.label}
                dimLabel={node.dimLabel}
                count={node.count}
                measure={node.measure}
                unit={groupUnit}
                noun={groupNoun}
                collapsed={Boolean(collapsedGroups?.has(node.id))}
                onToggle={() => onToggleGroupCollapse?.(node.id)}
              />
            ) : (
            /* THE WHOLE ROW OPENS THE RECORD.
               The chevron stays — it is where the eye goes to learn that a row
               CAN be opened, and it is the only part of a 1,400px row a
               keyboard can reach. But making it the only target means a reader
               who has just finished reading a row at the far left has to travel
               the width of the table to act on what they read, and clicking the
               row is what everybody tries first anyway.

               CLICKS THAT LAND ON SOMETHING ELSE ARE NOT ROW CLICKS. A
               checkbox, the chevron, a link inside a cell — each is its own
               act, and an ancestor handler that fired as well would make one
               press do two things. `closest` on the real target is how the row
               tells the difference; a text selection dragged across a cell is
               not a click either. */
            <React.Fragment key={node.id}>
            <TableRow
              className={cn(
                "group/row h-14",
                onOpenRow && "cursor-pointer outline-none focus-visible:bg-fp-row-hover focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50",
                /* The open parent keeps a tint and drops its divider, so the
                   rail runs on into its layer (DS). */
                expanded.has(node.id) && "border-b-0 bg-fp-row-hover hover:bg-fp-row-hover"
              )}
              data-state={selectedIds?.has(node.id) ? "selected" : undefined}
              data-expanded={expanded.has(node.id) ? "true" : undefined}
              /* THE ROW IS THE CONTROL — reachable by keyboard, Enter or
                 Space opens it, and it says what it opens. */
              tabIndex={onOpenRow ? 0 : undefined}
              aria-label={onOpenRow ? openLabel(node.row) : undefined}
              onKeyDown={(e) => {
                if (!onOpenRow || e.target !== e.currentTarget) return;
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  onOpenRow(node.row);
                }
              }}
              onClick={(e) => {
                if (!onOpenRow) return;
                const t = e.target as HTMLElement | null;
                if (t?.closest("button,a,input,label,[role='checkbox'],[data-no-row-open]"))
                  return;
                if (window.getSelection()?.toString()) return;
                onOpenRow(node.row);
              }}
            >
              {selectable && (
                <TableCell className={cn("px-3", expanded.has(node.id) && "relative before:pointer-events-none before:absolute before:inset-y-0 before:left-0 before:w-0.5 before:bg-status-success/70")}>
                  <Checkbox
                    checked={selectedIds!.has(node.id)}
                    onCheckedChange={() => onToggleRow!(node.id)}
                    aria-label={`Select ${openLabel(node.row).replace(/^Open /, "")}`}
                  />
                </TableCell>
              )}
              {visible.map((col, ci) => (
                <TableCell
                  key={col.key}
                  className={cn(
                    "px-3",
                    alignTop && "align-top py-3",
                    /* THE RAIL STARTS ON THE OPEN PARENT'S FIRST CELL. */
                    ci === 0 && !selectable && expanded.has(node.id) && "relative before:pointer-events-none before:absolute before:inset-y-0 before:left-0 before:w-0.5 before:bg-status-success/70",
                    sort?.key === col.key && "fp-sorted-cell",
                    col.key === actionsKey &&
                      /* THE PINNED CELL WEARS THE ROW'S STATE — hover, an open
                         nested layer, selection — so it never reads as a
                         white box at the end of a tinted row. */
                      "sticky right-0 z-10 bg-fp-surface-1b before:pointer-events-none before:absolute before:inset-0 group-hover/row:before:bg-fp-row-hover group-data-[expanded=true]/row:before:bg-fp-row-hover group-data-[state=selected]/row:before:bg-fp-row-selected"
                  )}
                >
                  <span className={cn(col.key === actionsKey && "relative")}>
                    {col.key === actionsKey ? (
                      <div className="flex justify-end">
                        <Button
                          variant="ghost"
                          size="icon-sm"
                          aria-label={openLabel(node.row)}
                          onClick={() => onOpenRow?.(node.row)}
                        >
                          <ChevronRight />
                        </Button>
                      </div>
                    ) : expandable && ci === 0 ? (
                      /* THE CHEVRON LEADS THE FIRST CELL (DS) — not a column. */
                      <span className="flex min-w-0 items-center gap-1.5">
                        <button
                          type="button"
                          onClick={() => toggleExpand(node.id)}
                          aria-expanded={expanded.has(node.id)}
                          aria-label={expandLabel?.(node.row, expanded.has(node.id)) ?? (expanded.has(node.id) ? "Collapse row" : "Expand row")}
                          className="-ml-1 shrink-0 rounded p-0.5 text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                        >
                          <ChevronRight className={cn("size-4 transition-transform", expanded.has(node.id) && "rotate-90")} />
                        </button>
                        <span className="min-w-0">{renderCell(node.row, col.key)}</span>
                      </span>
                    ) : (
                      renderCell(node.row, col.key)
                    )}
                  </span>
                </TableCell>
              ))}

            </TableRow>
            {expandable && expanded.has(node.id) && (
              <TableRow className="hover:bg-transparent data-[state=selected]:bg-transparent">
                {/* THE LAYER IS WHITE (the content layer), end to end, pinned to
                    the visible width so its columns stay put. Its rail is the
                    parent's — the same 2px strip at the same left edge, so the
                    two meet without a step (Pavan, 2026-10-17). */}
                <TableCell colSpan={span} className="bg-fp-surface-1b p-0">
                  <div className="sticky left-0 bg-fp-surface-1b before:pointer-events-none before:absolute before:inset-y-0 before:left-0 before:w-0.5 before:bg-status-success/70" style={{ width: frameWidth }}>
                    {renderExpanded!(node.row)}
                  </div>
                </TableCell>
              </TableRow>
            )}
            </React.Fragment>
              )
            )}
        </TableBody>
      </Table>
    </div>
  );
  if (!topBar) return body;
  return (
    <div className="flex h-full flex-col overflow-hidden rounded-md border border-border">
      <div className="shrink-0 border-b border-fp-outline-1 bg-fp-surface-1b">{topBar}</div>
      {body}
    </div>
  );
}

/** Primary over a muted secondary — the DS two-line cell. */
/**
 * THE PART OF THE CELL THAT ANSWERED THE FILTER, marked.
 *
 * Reordering the cell so the matched value comes first says WHICH value; this
 * says which part of it. On a column of near-identical names — Clear Diesel #2
 * beside Dyed Diesel — "dies" fetches both and the eye still has to work out
 * what it typed. A mark puts the answer where the question was asked.
 *
 * THE BRAND, AT A QUARTER. The DS binds no meaning to a colour until a usage
 * rule does, and this is the rule: brand is already "the thing you have
 * pointed at" — the active tab, the primary act — and a search match is the
 * same claim about a word. A quarter keeps it a tint under body text rather
 * than a block of fill with letters on top.
 */
export function Hit({
  text,
  q,
}: {
  text: string;
  /**
   * One needle or several. The list search and a column's own filter box are
   * both live at once and both narrowed this row, so both are marked: a reader
   * who typed in two places should see both answers, not whichever the cell
   * happened to be told about.
   */
  q?: string | (string | undefined)[];
}) {
  const needles = (Array.isArray(q) ? q : [q])
    .map((n) => n?.trim().toLowerCase())
    .filter((n): n is string => Boolean(n));
  if (needles.length === 0) return <>{text}</>;

  /* EVERY RUN ANY NEEDLE HITS, merged. Two needles that overlap — "diesel" in
     the search box and "dies" in the column — would otherwise mark the same
     letters twice and split the word into fragments. */
  const hay = text.toLowerCase();
  const spans: [number, number][] = [];
  for (const n of needles) {
    let at = hay.indexOf(n);
    while (at !== -1) {
      spans.push([at, at + n.length]);
      at = hay.indexOf(n, at + 1);
    }
  }
  if (spans.length === 0) return <>{text}</>;
  spans.sort((a, b) => a[0] - b[0]);
  const merged: [number, number][] = [];
  for (const [from, to] of spans) {
    const last = merged[merged.length - 1];
    if (last && from <= last[1]) last[1] = Math.max(last[1], to);
    else merged.push([from, to]);
  }

  const parts: React.ReactNode[] = [];
  let at = 0;
  for (const [from, to] of merged) {
    if (from > at) parts.push(text.slice(at, from));
    parts.push(
      <mark
        key={`${from}-${to}`}
        className="rounded-xs bg-brand/25 font-medium text-foreground"
      >
        {text.slice(from, to)}
      </mark>
    );
    at = to;
  }
  if (at < text.length) parts.push(text.slice(at));
  return <>{parts}</>;
}

export function TwoLineCell({
  title,
  description,
  q,
}: {
  title: string;
  description: string;
  /** Filter text for this column — the matched run is marked. */
  q?: string | (string | undefined)[];
}) {
  return (
    <div className="flex min-w-0 flex-col">
      <span className="truncate text-sm text-foreground">
        <Hit text={title} q={q} />
      </span>
      <span className="truncate text-xs text-muted-foreground">
        <Hit text={description} q={q} />
      </span>
    </div>
  );
}

/**
 * First value plus a `+N` chip for the rest. The chip opens the shared
 * breakdown card ON CLICK (Pavan, 2026-10-14 — one way everywhere; was a
 * hover list). The count is the information here; the first value is only
 * an anchor. Rows may carry a sub-line and a figure (`rows`).
 */
export function OverflowList({
  values,
  label,
  rows,
}: {
  values: string[];
  label: string;
  /** Richer rows for the card — default: one per value. */
  rows?: BreakdownRow[];
}) {
  if (values.length === 0) {
    return <span className="text-sm text-muted-foreground">—</span>;
  }
  const [first, ...rest] = values;
  return (
    <div className="flex min-w-0 items-center gap-1.5">
      <span className="truncate text-sm text-foreground">{first}</span>
      {rest.length > 0 && (
        <OverflowChip
          count={rest.length}
          label={`Show all ${values.length} ${label}`}
          /* WIDER WHEN ROWS CARRY DETAIL — a sub-line and a figure. */
          width={rows ? 360 : undefined}
          card={{
            title: `All ${label} (${values.length})`,
            rows: rows ?? values.map((v) => ({ label: v })),
          }}
        />
      )}
    </div>
  );
}

import * as React from "react";
import { createPortal } from "react-dom";
import {
  Map as MapIcon,
  Columns3,
  GripVertical,
  LayoutList,
  List,
  Search,
  Settings2,
  TextSearch,
  X,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  HoverCard,
  HoverCardContent,
  HoverCardTrigger,
} from "@/components/ui/hover-card";
import { Checkbox } from "@/components/ui/checkbox";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { Separator } from "@/components/ui/separator";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Combobox } from "@/components/ui/combobox";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  GroupByMenu,
  type GroupByDimension,
} from "@/components/tables-layout/GroupByMenu";
import { DateFilter } from "./DateFilter";

/**
 * The action bar, generic over the list it serves.
 *
 * Composition is the DS's CURRENT Data Action Control toolbar
 * (`data-action-control/DataActionControl.tsx`, the finalized Option 1) and is
 * unchanged from what Fuel Orders proved:
 *
 *   LEFT   320px search (leading glyph, trailing clear ×) · Filters · Group By
 *   RIGHT  [date scope] │ view switch │ search-by-column · show/hide columns
 *          (on the board that last pair is replaced by the card-fields menu)
 *
 * Both dividers, `gap-3` left / `gap-1` right, the 32px control height, the
 * ghost `icon-sm` tools with tooltips and the `bg-accent` active state on the
 * view switch are the DS's values.
 *
 * WHAT THIS PARAMETERISES, and why it exists: the facet panel, the column list
 * and the search-by-column fields were welded to one screen's data, so a second
 * list could not reuse the unit. They are props now. This is exactly the change
 * `docs/handoff-ds-adoption-2.md` asks the DS to make to `FilterPanel` and the
 * two column tools — done here first, across three screens, so the DS side has a
 * worked example rather than a description.
 *
 * `dateScope` is OPTIONAL and that is the point: a date stepper belongs on a list
 * whose every row sits on one date, and is meaningless on one that carries no
 * date at all. Fuel Orders and Asset Orders pass it; Customers does not.
 */

/**
 * `map` is opt-in: a list only offers it when its records have a PLACE, which
 * is true of vendors and of nothing else in the Directory. A view toggle that
 * shows a dead third option on every screen teaches people to ignore it.
 */
export type ListView = "table" | "board" | "map";

export interface ListSearchField {
  key: string;
  label: string;
}

export interface ListToolbarProps<K extends string> {
  searchValue: string;
  onSearchChange: (v: string) => void;
  searchPlaceholder: string;
  /** The screen's facet panel — a `Filters` trigger plus its popover. */
  filters: React.ReactNode;
  /**
   * QUICK FILTERS — a segmented control beside the facet panel.
   *
   * For the one or two splits a reader flips between constantly, where opening
   * a panel to tick a box and closing it again is the wrong amount of work.
   * It sits on the LEFT cluster with search and Filters because it narrows the
   * list, which is what everything on that side does; the right-hand side acts
   * on the view. See `docs/ds/ui/2-rules.md` §10.
   *
   * NOT A REPLACEMENT FOR THE PANEL. A split belongs here only when it is
   * exhaustive and short — All plus two or three — and when a reader changes
   * it several times a session. Everything else stays a facet.
   */
  quickFilters?: React.ReactNode;
  /** Right after the Filters button — e.g. Recommendations. */
  afterFilters?: React.ReactNode;
  /**
   * `group` makes an entry a CHILD of the entry with that key — one level, no
   * deeper. A board card is not a flat list of fields: "Customer Details" is a
   * heading with three lines under it, and a reader who wants the account but
   * not the street address had no way to say so while the unit was one switch.
   *
   * Turning a parent off takes its children with it, because the heading is
   * the only thing holding them together; turning the last child off leaves a
   * heading with nothing under it, so it takes the parent too.
   */
  columns: { key: K; label: string; group?: K }[];
  /**
   * THE SAME ORDER THE TABLE IS IN, EDITABLE HERE TOO.
   *
   * Dragging a header is the direct way to move a column and it is only
   * available to columns you can SEE — the one you want is usually the one
   * scrolled off the right edge, which is why you opened this menu. The list
   * is already every column in the table, in order; a grip makes it the place
   * you arrange them as well as the place you choose them.
   *
   * Supply both to turn it on. Left off, the list is still a list.
   */
  columnOrder?: string[];
  onReorderColumns?: (next: string[]) => void;
  hiddenColumns: Set<K>;
  onToggleColumn: (key: K) => void;
  onShowAllColumns: () => void;
  /** Columns the "Search by column" tool can be pointed at. */
  searchFields: ListSearchField[];
  colScope: string;
  onColScopeChange: (v: string) => void;
  colQuery: string;
  onColQueryChange: (v: string) => void;
  /**
   * A FILTER ROW IN THE TABLE, INSTEAD OF A POPOVER THAT SEARCHES ONE COLUMN.
   *
   * The popover asked you to name a column and then type in it — two controls
   * and a menu to do what a box under the header does by sitting there. It
   * also only ever held ONE column at a time, so "Halvorsen, in Fresno" was
   * two searches and the memory of the first. A row of boxes is the same
   * question asked of every column at once, and the answer is where the column
   * is.
   *
   * Supply this and the button becomes a toggle for that row. Leave it off and
   * the popover stays — a table that has not grown the row yet still needs a
   * way to search a column.
   */
  columnFiltersOpen?: boolean;
  onToggleColumnFilters?: () => void;
  /**
   * THE VIEW'S TOOLS IN A BAR ON THE VIEW (Pavan, 2026-10-22 — trial on 3PL
   * Delivery Orders): given, the table's and the board's own tools render
   * into this element — a row above the table header, or above the lanes —
   * with `viewStatement` on the left and the tools on the right ("Search by
   * column", 24px, the columns setting; or Card fields), instead of hanging
   * under the view icons.
   */
  viewToolsInto?: HTMLElement | null;
  /** What the bar says on its left — how many records, over what window. */
  viewStatement?: React.ReactNode;
  /** How many of the row's boxes have something in them. */
  columnFilterCount?: number;
  view: ListView;
  onViewChange: (v: ListView) => void;
  /** Offer the map view. Off unless the records are geographic. */
  mapView?: boolean;
  /**
   * WHETHER THIS LIST HAS A BOARD AT ALL. Default FALSE (2026-10-01) — most
   * lists here have no board, and the ones that do say so.
   *
   * The same call `mapView` makes, and for the same reason: a view switch that
   * offers a board to a list with no board is a dead control, and the rule
   * three lines down — the one that hides the column tools off the table —
   * exists precisely because a control with nothing behind it is worse than no
   * control. A list of standing arrangements has no lanes to put them in.
   */
  boardView?: boolean;
  /** Omit entirely on lists that are not date-scoped. */
  dateScope?: { date: Date; onDateChange: (d: Date) => void };
  /**
   * A DIFFERENT date control, in the same slot. 3PL scopes by a RANGE because a
   * broker's delivery windows run over weekends and a one-day view of those is
   * a lane that keeps looking empty — but that is 3PL's answer, not every
   * list's, so it is supplied rather than switched on. Wins over `dateScope`.
   */
  dateControl?: React.ReactNode;
  /**
   * Grouping. `dimensions` are a property of the list's DATA, so each screen
   * supplies its own; the menu is ordered and capped at two levels.
   */
  groupBy?: {
    dimensions: GroupByDimension[];
    value: string[];
    onChange: (next: string[]) => void;
  };
  /**
   * OFF WHERE THE VIEW IS ALREADY GROUPED.
   *
   * Grouping cuts a flat list into headed sections. A board has no flat list to
   * cut: it is already sections, one per lane, and that grouping is the view
   * itself rather than a setting on it. A second dimension over the top would
   * have to nest — groups inside lanes, or lanes inside groups — and neither is
   * a board any more. The control stayed on screen doing nothing, which is
   * worse than not offering it.
   */
  showGroupBy?: boolean;
  /**
   * WHAT IS ON THE CARD — the board's own version of the column menu.
   *
   * A card is not a table row: the reader is not choosing columns, they are
   * choosing which UNITS of the record the card carries, and those units nest.
   * "Customer Details" is a heading with three lines under it, and somebody who
   * wants the account but not the street address has to be able to say so.
   *
   * It is a SEPARATE control rather than the column menu re-aimed, because one
   * icon that changes its subject with the view is one icon nobody can read
   * (`docs/ds/ui/2-rules.md` §10). This one is named for the card, carries its
   * own icon, and appears only on the board.
   *
   * NO ORDERING HERE. A card's units read top to bottom in the order the work
   * happens — who it is for, when, what, and who is taking it — which is the
   * card's design, not a preference.
   */
  cardFields?: {
    units: { key: string; label: string; group?: string }[];
    hidden: ReadonlySet<string>;
    onToggle: (key: string) => void;
    onShowAll: () => void;
    /**
     * WHICH LANE THE MENU IS SPEAKING FOR. `null` is every lane at once.
     *
     * A board card is not one design repeated down the page — what a card in
     * the first lane should say is not what one in the last should — so a
     * single field list could only ever be right for one lane. The scope is
     * the first thing in the menu because it changes what every tick under it
     * means.
     */
    scope?: string | null;
    scopes?: { key: string; label: string }[];
    onScopeChange?: (scope: string | null) => void;
  };
}

/* A VIEW-BAR TOOL IS ITS ICON; its name slides out on hover (Pavan,
   2026-10-22) — 12px, a darker grey, never black. NO FILL, ever: not on
   hover, not when on. WHILE IT IS ON — the column search row open
   (aria-pressed), a menu open (aria-expanded; the tooltip owns data-state)
   — the name stays out. */
const BAR_TOOL =
  "group/tool h-8 gap-0 px-2 text-xs font-normal text-muted-foreground transition-[gap] duration-200 hover:bg-transparent hover:gap-1.5 hover:text-muted-foreground focus-visible:gap-1.5 aria-pressed:gap-1.5 aria-expanded:gap-1.5 dark:hover:bg-transparent";
function Reveal({ children }: { children: React.ReactNode }) {
  return (
    <span className="max-w-0 overflow-hidden whitespace-nowrap opacity-0 transition-all duration-200 group-hover/tool:max-w-48 group-hover/tool:opacity-100 group-focus-visible/tool:max-w-48 group-focus-visible/tool:opacity-100 group-aria-pressed/tool:max-w-48 group-aria-pressed/tool:opacity-100 group-aria-expanded/tool:max-w-48 group-aria-expanded/tool:opacity-100">
      {children}
    </span>
  );
}

/** STACKED CARDS — the board's icon in the display switch (Pavan's reference). */
function CardsIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <rect x="4" y="3.5" width="16" height="7.5" rx="2.5" />
      <rect x="4" y="13" width="16" height="7.5" rx="2.5" />
    </svg>
  );
}

/** Icon button in the toolbar, wrapped in a tooltip. The DS's `IconTool`. */
export function IconTool({
  label,
  view,
  active,
  onClick,
  children,
}: {
  label: string;
  /** Which display it switches to — where the routing line starts. */
  view?: string;
  active?: boolean;
  onClick?: () => void;
  children: React.ReactNode;
}) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          variant="ghost"
          size="icon-sm"
          aria-label={label}
          data-view={view}
          onClick={onClick}
          // Same fill as the chips: `--chip`, not `--accent`. At #cad1db the
          // control-emphasis token sits far too heavy on white inside a 32px
          // button. Dark is unchanged — `--chip` is #2a2f37 there.
          className={cn(active && "bg-chip text-foreground")}
        >
          {children}
        </Button>
      </TooltipTrigger>
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  );
}

export function ListToolbar<K extends string>({
  searchValue,
  onSearchChange,
  searchPlaceholder,
  filters,
  quickFilters,
  afterFilters,
  columns,
  hiddenColumns,
  onToggleColumn,
  onShowAllColumns,
  searchFields,
  colScope,
  onColScopeChange,
  colQuery,
  onColQueryChange,
  columnFiltersOpen,
  onToggleColumnFilters,
  viewToolsInto,
  viewStatement,
  columnFilterCount = 0,
  columnOrder,
  onReorderColumns,
  view,
  onViewChange,
  mapView = false,
  boardView = false,
  dateScope,
  dateControl,
  groupBy,
  showGroupBy = true,
  cardFields,
}: ListToolbarProps<K>) {
  const multiView = boardView || mapView;
  const colLabel =
    searchFields.find((f) => f.key === colScope)?.label ?? "column";
  const shown = columns.filter((c) => !hiddenColumns.has(c.key)).length;
  const cardShown = cardFields
    ? cardFields.units.filter((u) => !cardFields.hidden.has(u.key)).length
    : 0;

  /* THE LIST FOLLOWS THE TABLE. Reading them in a different sequence from the
     columns they stand for would make the menu a second opinion about the
     order rather than a view of it. Keys the order has not heard of keep their
     declared place, which is how a saved view survives a new column. */
  const reorderable = Boolean(columnOrder && onReorderColumns);
  const ordered = React.useMemo(() => {
    if (!columnOrder) return columns;
    const rank = new Map(columnOrder.map((k, i) => [k, i]));
    return [...columns].sort((a, b) => {
      const ai = rank.get(a.key) ?? columns.findIndex((c) => c.key === a.key);
      const bi = rank.get(b.key) ?? columns.findIndex((c) => c.key === b.key);
      return ai - bi;
    });
  }, [columns, columnOrder]);

  const [dragKey, setDragKey] = React.useState<string | null>(null);
  const [overKey, setOverKey] = React.useState<string | null>(null);
  /** Puts `key` where `target` sits. */
  const moveColumn = (key: string, target: string) => {
    if (!onReorderColumns || key === target) return;
    const keys = ordered.map((c) => c.key as string);
    const next = keys.filter((k) => k !== key);
    next.splice(next.indexOf(target), 0, key);
    onReorderColumns(next);
  };
  /** One step up or down — the keyboard's version of the same move. */
  const nudgeColumn = (key: string, delta: -1 | 1) => {
    const keys = ordered.map((c) => c.key as string);
    const at = keys.indexOf(key);
    const to = at + delta;
    if (at === -1 || to < 0 || to >= keys.length) return;
    onReorderColumns?.(
      (() => {
        const next = [...keys];
        next.splice(at, 1);
        next.splice(to, 0, key);
        return next;
      })()
    );
  };

  /* COLUMN TOOLS ARE A TABLE'S TOOLS, AND ONLY A TABLE'S.

            Search by column and Show/Hide columns both name a thing the reader
            can see: a header to type under, a column to take away. On a board
            or a map there are no columns on screen, so the controls were either
            doing nothing or — worse, on the board — quietly redefining
            themselves to mean the card's units, which is a second meaning for
            one button that nobody could guess from the icon.

            The board's units did not go away with the button: they have their
            own control below, named for the card and shown only on the board.

            THIS IS A LIST RULE, NOT A 3PL ONE: it lives here so every screen
            using this toolbar gets it. See `docs/ds/ui/2-rules.md` §10. */
  const inBar = Boolean(viewToolsInto);
  const tableTools = (
    <>
        {/* Search by column — the row, where the table has one. */}
        {onToggleColumnFilters ? (
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size={inBar ? "sm" : "icon-sm"}
                aria-label="Search by column"
                aria-pressed={columnFiltersOpen}
                onClick={onToggleColumnFilters}
                className={cn(
                  inBar
                    ? BAR_TOOL
                    : (columnFiltersOpen || columnFilterCount > 0) && "bg-accent text-foreground"
                )}
              >
                <TextSearch />
                {inBar && <Reveal>Search by column</Reveal>}
              </Button>
            </TooltipTrigger>
            <TooltipContent className={cn(inBar && "hidden")}>
              {columnFiltersOpen ? "Hide column search" : "Search by column"}
            </TooltipContent>
          </Tooltip>
        ) : (
        <Popover>
          <Tooltip>
            <TooltipTrigger asChild>
              <PopoverTrigger asChild>
                <Button
                  variant="ghost"
                  size={inBar ? "sm" : "icon-sm"}
                  aria-label="Search by column"
                  className={cn(inBar ? BAR_TOOL : colQuery.trim() && "text-foreground")}
                >
                  <TextSearch />
                  {inBar && <Reveal>Search by column</Reveal>}
                </Button>
              </PopoverTrigger>
            </TooltipTrigger>
            <TooltipContent className={cn(inBar && "hidden")}>Search by column</TooltipContent>
          </Tooltip>
          <PopoverContent align="end" className="w-64 space-y-2 p-3">
            <div className="flex items-center gap-1.5 text-xs font-medium text-muted-foreground">
              <TextSearch className="size-3.5" /> Search by column
            </div>
            <Combobox
              size="sm"
              className="w-full"
              value={colScope}
              onValueChange={onColScopeChange}
              options={searchFields.map((f) => ({
                value: f.key,
                label: f.label,
              }))}
              placeholder="Choose a column"
              searchPlaceholder="Search columns…"
              emptyText="No column found."
            />
            <div className="relative">
              <Search className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                value={colQuery}
                onChange={(e) => onColQueryChange(e.target.value)}
                placeholder={`Find in ${colLabel}…`}
                className={cn("h-8 pl-8", colQuery && "pr-8")}
              />
              {colQuery && (
                <button
                  type="button"
                  aria-label="Clear column search"
                  onClick={() => onColQueryChange("")}
                  className="absolute top-1/2 right-2 -translate-y-1/2 rounded-sm p-0.5 text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                >
                  <X className="size-3.5" />
                </button>
              )}
            </div>
          </PopoverContent>
        </Popover>
        )}

        {/* Show/Hide columns */}
        <Popover>
          <Tooltip>
            <TooltipTrigger asChild>
              <PopoverTrigger asChild>
                <Button
                  variant="ghost"
                  size={inBar ? "sm" : "icon-sm"}
                  aria-label="Show/Hide columns"
                  className={cn(inBar && BAR_TOOL)}
                >
                  {inBar ? <Settings2 /> : <Columns3 />}
                  {inBar && <Reveal>Show/hide columns</Reveal>}
                </Button>
              </PopoverTrigger>
            </TooltipTrigger>
            <TooltipContent className={cn(inBar && "hidden")}>Show/Hide columns</TooltipContent>
          </Tooltip>
          <PopoverContent align="end" className="w-56 p-1">
            <div className="flex items-center justify-between px-2 py-1.5">
              <span className="text-xs font-medium text-muted-foreground">
                Columns
              </span>
              <span className="rounded bg-fp-card-1 px-1.5 text-[11px] tabular-nums text-muted-foreground">
                {shown}/{columns.length}
              </span>
            </div>
            <div className="max-h-64 overflow-y-auto">
              {ordered.map((c) => {
                const draggable = reorderable && !c.group;
                return (
                  <div
                    key={c.key}
                    draggable={draggable}
                    onDragStart={
                      draggable
                        ? (e) => {
                            setDragKey(c.key);
                            e.dataTransfer.effectAllowed = "move";
                            /* Firefox starts no drag without payload. */
                            e.dataTransfer.setData("text/plain", c.key);
                          }
                        : undefined
                    }
                    onDragOver={
                      draggable
                        ? (e) => {
                            if (!dragKey || dragKey === c.key) return;
                            e.preventDefault();
                            setOverKey(c.key);
                          }
                        : undefined
                    }
                    onDrop={
                      draggable
                        ? (e) => {
                            e.preventDefault();
                            if (dragKey) moveColumn(dragKey, c.key);
                            setDragKey(null);
                            setOverKey(null);
                          }
                        : undefined
                    }
                    onDragEnd={() => {
                      setDragKey(null);
                      setOverKey(null);
                    }}
                    className={cn(
                      "flex items-center rounded-sm transition-colors hover:bg-accent has-[:focus-visible]:bg-accent",
                      dragKey === c.key && "opacity-40",
                      /* WHERE IT WILL LAND, on the row it will land on. A line
                         between rows would need to know which side of the gap
                         the pointer is on; tinting the target says the same
                         thing and cannot be off by one. */
                      overKey === c.key && dragKey && "bg-accent"
                    )}
                  >
                    {reorderable && (
                      <span
                        className={cn(
                          "flex w-5 shrink-0 items-center justify-center self-stretch",
                          draggable
                            ? "cursor-grab text-muted-foreground active:cursor-grabbing"
                            : "opacity-0"
                        )}
                        aria-hidden={!draggable}
                      >
                        {draggable && <GripVertical className="size-3.5" />}
                      </span>
                    )}
                    <label
                      className={cn(
                        "flex flex-1 cursor-pointer items-center gap-2 py-1.5 pr-2 text-sm",
                        /* THE INDENT IS THE ONLY THING SAYING "UNDER". A child
                           at the parent's left edge is a sibling with a smaller
                           label; the offset and the lighter weight say which
                           heading it belongs to without a line or a disclosure
                           arrow. */
                        c.group
                          ? "pl-5 text-[13px] text-muted-foreground"
                          : reorderable
                            ? "pl-0"
                            : "pl-2"
                      )}
                      /* THE KEYBOARD MOVES IT TOO. A grip nobody can reach
                         without a mouse is an ordering only some readers get
                         to change. */
                      onKeyDown={
                        draggable
                          ? (e) => {
                              if (e.key === "ArrowUp" || e.key === "ArrowDown") {
                                e.preventDefault();
                                nudgeColumn(c.key, e.key === "ArrowUp" ? -1 : 1);
                              }
                            }
                          : undefined
                      }
                    >
                      <Checkbox
                        checked={!hiddenColumns.has(c.key)}
                        onCheckedChange={() => onToggleColumn(c.key)}
                      />
                      <span className="flex-1 truncate">{c.label}</span>
                    </label>
                  </div>
                );
              })}
            </div>
            <Separator className="my-1" />
            {/* SHOW ALL, AND NOTHING FACING IT. Hide all emptied the table —
                a control whose only outcome is a screen with no data in it,
                sitting one slip of the hand from the one people actually use.
                Show all is a way BACK from a narrowing, which is the only one
                of the two anybody was reaching for; alone, it goes to the
                right, where the act in a footer belongs. */}
            <div className="flex justify-end">
              <Button
                variant="ghost"
                size="sm"
                disabled={hiddenColumns.size === 0}
                onClick={onShowAllColumns}
              >
                Show all
              </Button>
            </div>
          </PopoverContent>
        </Popover>
    </>
  );
  /* WHAT IS ON THE CARD — the board's own control, in the slot the
            column tools vacate. Same place, different subject, and the subject
            is written at the top of the menu and spoken by the icon, so the
            two can never be mistaken for one control that moved. */
  const boardTools = cardFields ? (
    <>
            <Popover>
              <Tooltip>
                <TooltipTrigger asChild>
                  <PopoverTrigger asChild>
                    <Button
                      variant="ghost"
                      size={inBar ? "sm" : "icon-sm"}
                      aria-label="Card fields"
                      className={cn(inBar && BAR_TOOL)}
                    >
                      <LayoutList />
                      {inBar && <Reveal>Card configuration</Reveal>}
                    </Button>
                  </PopoverTrigger>
                </TooltipTrigger>
                <TooltipContent className={cn(inBar && "hidden")}>Card fields</TooltipContent>
              </Tooltip>
              <PopoverContent align="end" className="w-60 p-1">
                <div className="flex items-center justify-between px-2 py-1.5">
                  <span className="text-xs font-medium text-muted-foreground">
                    Card fields
                  </span>
                  <span className="rounded bg-fp-card-1 px-1.5 text-[11px] tabular-nums text-muted-foreground">
                    {cardShown}/{cardFields.units.length}
                  </span>
                </div>
                {/* WHICH CARDS THIS IS ABOUT, above the ticks it governs. A
                    card in the first lane and one in the last are answering
                    different questions, so the field list has to be able to
                    differ between them — and the reader has to be told which
                    set they are editing BEFORE they edit it, not after. */}
                {cardFields.scopes && cardFields.onScopeChange && (
                  <div className="px-2 pb-2">
                    <Combobox
                      size="sm"
                      className="w-full"
                      value={cardFields.scope ?? ALL_LANES}
                      onValueChange={(v) =>
                        cardFields.onScopeChange?.(v === ALL_LANES ? null : v)
                      }
                      options={[
                        { value: ALL_LANES, label: "All lanes" },
                        ...cardFields.scopes.map((sc) => ({
                          value: sc.key,
                          label: sc.label,
                        })),
                      ]}
                      placeholder="All lanes"
                      searchPlaceholder="Search lanes…"
                      emptyText="No lane found."
                    />
                  </div>
                )}
                <div className="max-h-64 overflow-y-auto">
                  {/* A TOGGLE PER CATEGORY, a tick per field inside it (Pavan,
                      2026-09-23). The category — Customer, Asset & Fault — is
                      the decision somebody actually makes about a card, so it
                      is a switch: on or off, and it reads that way. Its fields
                      are the finer adjustment, shown only while the category
                      is on, because ticking a field inside a hidden block
                      changes nothing anybody can see. */}
                  {cardFields.units.map((u) => {
                    if (!u.group) {
                      const on = !cardFields.hidden.has(u.key);
                      return (
                        <label
                          key={u.key}
                          className="flex cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 text-sm transition-colors hover:bg-accent has-[:focus-visible]:bg-accent"
                        >
                          <span className="flex-1 truncate">{u.label}</span>
                          <Switch
                            size="sm"
                            checked={on}
                            onCheckedChange={() => cardFields.onToggle(u.key)}
                          />
                        </label>
                      );
                    }
                    if (cardFields.hidden.has(u.group)) return null;
                    return (
                      <label
                        key={u.key}
                        className="flex cursor-pointer items-center gap-2 rounded-sm py-1.5 pr-2 pl-5 text-[13px] text-muted-foreground transition-colors hover:bg-accent has-[:focus-visible]:bg-accent"
                      >
                        <Checkbox
                          checked={!cardFields.hidden.has(u.key)}
                          onCheckedChange={() => cardFields.onToggle(u.key)}
                        />
                        <span className="flex-1 truncate">{u.label}</span>
                      </label>
                    );
                  })}
                </div>
                <Separator className="my-1" />
                <div className="flex justify-end">
                  <Button
                    variant="ghost"
                    size="sm"
                    disabled={cardFields.hidden.size === 0}
                    onClick={cardFields.onShowAll}
                  >
                    Show all
                  </Button>
                </div>
              </PopoverContent>
            </Popover>
    </>
  ) : null;
  const activeTools = inBar ? null : view === "table" ? tableTools : view === "board" ? boardTools : null;

  /* WHERE THE ROUTING LINE DROPS FROM — the active icon's centre, measured. */
  const rightRef = React.useRef<HTMLDivElement>(null);
  const [routeX, setRouteX] = React.useState(0);
  React.useLayoutEffect(() => {
    const box = rightRef.current;
    if (!box) return;
    const place = () => {
      const icon = box.querySelector<HTMLElement>(`[data-view="${view}"]`);
      if (!icon) return;
      const a = box.getBoundingClientRect();
      const b = icon.getBoundingClientRect();
      setRouteX(Math.round(b.left - a.left + b.width / 2));
      /* THE CHIPS' RIGHT EDGE — they share the tools' row and stop short of
         the right cluster. Set on the parent: the chip row is a sibling. */
      box.parentElement?.parentElement?.style.setProperty("--fp-routed-w", `${Math.round(a.width) + 16}px`);
    };
    place();
    const ro = new ResizeObserver(place);
    ro.observe(box);
    return () => ro.disconnect();
  }, [view]);

  return (
    /* TOP-ALIGNED — the routed tools hang below the right cluster, and the
       search row stays level with the view icons. `data-routed` lets the
       filter chips that follow rise into the tools' row (index.css). */
    <div
      data-routed={multiView && activeTools ? "" : undefined}
      className="flex flex-wrap items-start justify-between gap-3"
    >
      {/* LEFT — quick filters · search · Filters · Group By

          THE QUICK FILTERS COME FIRST, before the search box, because they are
          the coarsest cut on the row: they decide WHICH SET you are searching
          and filtering inside. Reading left to right then matches the order
          somebody actually narrows — pick the book, then find the row. */}
      <div className="flex items-center gap-3">
        {quickFilters}
        {/* FIXED WIDTH — the list search box is the DS's 320px, the same on
            every list; it is not a row of fields. */}
        <div className="relative w-[320px]">
          <Search className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            type="search"
            value={searchValue}
            onChange={(e) => onSearchChange(e.target.value)}
            placeholder={searchPlaceholder}
            aria-label="Search all columns"
            className={cn("h-8 pl-8", searchValue && "pr-8")}
          />
          {searchValue && (
            <button
              type="button"
              aria-label="Clear search"
              onClick={() => onSearchChange("")}
              className="absolute top-1/2 right-2 -translate-y-1/2 rounded-sm p-0.5 text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
            >
              <X className="size-3.5" />
            </button>
          )}
        </div>
        {filters}
        {afterFilters}
        {/* WHY (Pavan, 2026-10-07). Group By only when the screen hands it real
           dimensions. With none, the menu fell back to the DS demo dims and
           grouped nothing — a dead control on every screen that forgot to
           switch it off (G8). */}
        {showGroupBy && groupBy && groupBy.dimensions.length > 0 && (
          <GroupByMenu
            dimensions={groupBy.dimensions}
            value={groupBy.value}
            onChange={groupBy.onChange}
          />
        )}
      </div>

      {/* RIGHT — [date]   view switch, and under the view you are on, its own
          tools, joined to it by a line (Pavan, 2026-10-22). */}
      <div ref={rightRef} className="flex flex-col items-start">
      <div className="flex items-center gap-1">
        {(dateControl ?? dateScope) && (
          <>
            {dateControl ?? (
              <DateFilter
                value={dateScope!.date}
                onChange={dateScope!.onDateChange}
              />
            )}
            {/* SPACE, NOT A RULE (Pavan, 2026-10-05): 12px plus the row's 4px
                gap each side — 20px between the date and the view switch. */}
            <div className="w-3 shrink-0" aria-hidden />
          </>
        )}

        {/* ONE VIEW, NO SWITCH (Pavan, 2026-10-01). A table-only list gets no
            Table-view icon — a switch with one position switches nothing.
            The column tools after it stay: they belong to the table. */}
        {/* THE DISPLAY SWITCH — ONE SEGMENTED CONTROL (Pavan, 2026-10-23,
            after his reference): a bordered pill of segments, the view you
            are on filled grey; icons that say the view — a list for the
            table, stacked cards for the board, a map. */}
        {multiView && (
          <div role="group" aria-label="Display" className="inline-flex h-8 shrink-0 overflow-hidden rounded-md border border-border bg-fp-surface-1b">
            {[
              { key: "table" as const, label: "Table view", icon: <List />, on: true },
              { key: "board" as const, label: "Board view", icon: <CardsIcon />, on: boardView },
              { key: "map" as const, label: "Map view", icon: <MapIcon />, on: mapView },
            ]
              .filter((v) => v.on)
              .map((v, i) => (
                <Tooltip key={v.key}>
                  <TooltipTrigger asChild>
                    <button
                      type="button"
                      aria-label={v.label}
                      aria-pressed={view === v.key}
                      data-view={v.key}
                      onClick={() => onViewChange(v.key)}
                      className={cn(
                        "inline-flex w-9 items-center justify-center text-muted-foreground outline-none transition-colors hover:bg-fp-row-hover hover:text-foreground focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50 [&_svg]:size-4",
                        i > 0 && "border-l border-border",
                        view === v.key && "bg-muted text-foreground hover:bg-muted"
                      )}
                    >
                      {v.icon}
                    </button>
                  </TooltipTrigger>
                  <TooltipContent>{v.label}</TooltipContent>
                </Tooltip>
              ))}
          </div>
        )}

        {/* A ONE-VIEW LIST KEEPS ITS TOOLS IN THE ROW — there is no switch
            for them to hang from. */}
        {!multiView && view === "table" && !inBar && tableTools}
      </div>
      {/* THE ACTIVE VIEW'S TOOLS, ROUTED FROM ITS ICON — a line drops from
          under the icon and turns into the tools, so they read as the
          table's (or the board's) and nothing else's. */}
      {multiView && activeTools && (
        <div className="flex items-start" style={{ paddingLeft: routeX }}>
          <span aria-hidden className="h-4 w-3 shrink-0 rounded-bl-md border-b border-l border-muted-foreground/40" />
          <span className="flex items-center gap-1">{activeTools}</span>
        </div>
      )}
      </div>
      {viewToolsInto &&
        (view === "table" || view === "board") &&
        createPortal(
          <div className="flex h-11 items-center justify-between gap-3 px-3">
            <span className="min-w-0 truncate text-sm text-muted-foreground">{viewStatement}</span>
            <span className="flex shrink-0 items-center gap-1">{view === "table" ? tableTools : boardTools}</span>
          </div>,
          viewToolsInto
        )}
    </div>
  );
}

/* The scope option standing for "every lane". A sentinel rather than "" —
   the combobox treats an empty value as nothing chosen. */
const ALL_LANES = "__all__";

/** The active column-search chip the DS unit renders under the toolbar. */
export function ColumnSearchChip({
  searchFields,
  colScope,
  colQuery,
  onClear,
  className = "mt-3",
}: {
  searchFields: ListSearchField[];
  colScope: string;
  colQuery: string;
  onClear: () => void;
  /** Overridable so the chip can join a shelf that already has its own top
   *  margin — see `FilterChips`, which is the other thing on that shelf. */
  className?: string;
}) {
  if (!colQuery.trim()) return null;
  const label = searchFields.find((f) => f.key === colScope)?.label ?? "column";
  return (
    <div className={cn("flex shrink-0 items-center gap-2", className)}>
      <span className="inline-flex h-7 items-center gap-1 rounded-full bg-muted pr-1 pl-3 text-xs text-foreground">
        <Search className="size-3 text-muted-foreground" />
        {label}: “{colQuery}”
        <button
          type="button"
          aria-label="Clear column search"
          onClick={onClear}
          className="flex size-5 items-center justify-center rounded-full text-muted-foreground outline-none hover:bg-foreground/10 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
        >
          <X className="size-3" />
        </button>
      </span>
    </div>
  );
}

/**
 * THE FILTERS THAT ARE ON, as one chip per facet under the toolbar.
 *
 * A COUNT IS NOT AN ANSWER. "Filters 7" says the list has been narrowed and
 * refuses to say how — the only way to find out was to open the panel, walk
 * six facets and read the checkboxes, which is the whole of what this shelf
 * does at a glance. And a narrowing you cannot see is one you forget you
 * applied: the short list that follows reads as "no customers" rather than "no
 * customers that match the seven things you asked for".
 *
 * ONE CHIP PER FACET, NOT PER VALUE. Per value, three cities were three chips
 * that said "City" three times to say one thing — and the row grew with the
 * TICKS rather than with the questions, so picking six cities buried the one
 * status filter that was also on. Grouped, the shelf is as long as the number
 * of QUESTIONS you have asked, which is a small number and a stable one, and
 * the shape of the narrowing is legible from across the room: Status, City,
 * Vendor.
 *
 * ONE VALUE SHOWS ITSELF; SEVERAL SHOW A COUNT. "City: Bakersfield" is shorter
 * than "City 1" and says more, so a lone value is never hidden behind a digit.
 * Past one there is no width to say them all and no honest way to pick which
 * one to print, so the chip says how many and the hover card says which —
 * WITH their own crosses, because the reason to look at this row is usually to
 * take ONE thing off, and a group that could only be removed whole would send
 * you back to the panel to do it.
 *
 * ONE LINE, ALWAYS — IT SCROLLS RATHER THAN WRAPS. This shelf sits between the
 * toolbar and the data and every pixel of it comes out of the data. Wrapped,
 * its height is a function of how many filters are on and how long their names
 * are. Grouping makes a second line unlikely; the scroller makes it
 * impossible, which is the only promise worth making about a strip in this
 * position.
 */
export function FilterChips({
  facets,
  selected,
  onChange,
  className,
  children,
}: {
  /** Key → label, in the order the panel lists them. */
  facets: { key: string; label: string }[];
  /** Applied ids, as `facetKey:option` — what `ListFilters` emits. */
  selected: ReadonlySet<string>;
  onChange: (next: ReadonlySet<string>) => void;
  className?: string;
  /** Anything else on the same shelf — the column-search chip, usually. */
  children?: React.ReactNode;
}) {
  const ids = [...selected];
  if (ids.length === 0) return children ? <>{children}</> : null;

  const drop = (gone: string[]) => {
    const next = new Set(selected);
    for (const id of gone) next.delete(id);
    onChange(next);
  };

  /* GROUPED IN THE PANEL'S OWN ORDER, so the shelf and the facet menu read the
     same way round. Ids whose facet is not declared keep their raw key and go
     last rather than disappearing. */
  const groups: { key: string; label: string; ids: string[] }[] = [];
  const bucket = (key: string, label: string) => {
    let g = groups.find((x) => x.key === key);
    if (!g) groups.push((g = { key, label, ids: [] }));
    return g;
  };
  for (const f of facets) {
    const mine = ids.filter((id) => id.startsWith(`${f.key}:`));
    if (mine.length) bucket(f.key, f.label).ids.push(...mine);
  }
  for (const id of ids) {
    /* SPLIT ON THE FIRST COLON ONLY — a ship-to option can hold one. */
    const key = id.slice(0, id.indexOf(":"));
    if (!facets.some((f) => f.key === key)) bucket(key, key).ids.push(id);
  }

  const valueOf = (id: string) => id.slice(id.indexOf(":") + 1);

  return (
    <div data-filter-chips className={cn("mt-3 flex shrink-0 items-center gap-2", className)}>
      {/* THE CHIPS TAKE ONLY THE WIDTH THEY NEED, so Clear all sits right
          after the last one (Pavan, 2026-10-09); past the row's width they
          still scroll rather than wrap. */}
      <div className="flex min-w-0 items-center gap-2 overflow-x-auto">
        {groups.map((g) => {
          const one = g.ids.length === 1;
          const chip = (
            <span
              className={cn(
                /* A REMOVABLE PILL (Pavan, 2026-10-09): the pill recipe with its ✕ inside. */
                "inline-flex h-7 max-w-[260px] shrink-0 items-center gap-1 rounded-full bg-muted pr-1 pl-3 text-xs text-foreground",
                !one && "cursor-default"
              )}
            >
              <span className="truncate">
                <span className="text-muted-foreground">
                  {g.label}
                  {one ? ": " : " "}
                </span>
                {one ? valueOf(g.ids[0]) : null}
              </span>
              {!one && (
                <span className="shrink-0 rounded-full bg-background px-1.5 tabular-nums">
                  {g.ids.length}
                </span>
              )}
              <button
                type="button"
                aria-label={
                  one
                    ? `Remove filter ${g.label}: ${valueOf(g.ids[0])}`
                    : `Remove all ${g.ids.length} ${g.label} filters`
                }
                onClick={() => drop(g.ids)}
                className="flex size-5 shrink-0 items-center justify-center rounded-full text-muted-foreground outline-none hover:bg-foreground/10 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
              >
                <X className="size-3" />
              </button>
            </span>
          );

          if (one) return <React.Fragment key={g.key}>{chip}</React.Fragment>;

          return (
            <HoverCard key={g.key} openDelay={120} closeDelay={120}>
              <HoverCardTrigger asChild>{chip}</HoverCardTrigger>
              <HoverCardContent
                align="start"
                className="w-auto max-w-[280px] min-w-[180px] p-1.5"
              >
                <p className="px-1.5 pb-1 text-[10px] font-semibold tracking-[0.12em] text-muted-foreground uppercase">
                  {g.label}
                </p>
                <ul className="flex flex-col">
                  {g.ids.map((id) => (
                    <li
                      key={id}
                      className="flex items-center gap-2 rounded-sm py-0.5 pr-0.5 pl-1.5 hover:bg-accent/60"
                    >
                      <span className="min-w-0 flex-1 truncate text-xs text-foreground">
                        {valueOf(id)}
                      </span>
                      <button
                        type="button"
                        aria-label={`Remove filter ${g.label}: ${valueOf(id)}`}
                        onClick={() => drop([id])}
                        className="flex size-5 shrink-0 items-center justify-center rounded-full text-muted-foreground outline-none hover:bg-foreground/10 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                      >
                        <X className="size-3" />
                      </button>
                    </li>
                  ))}
                </ul>
              </HoverCardContent>
            </HoverCard>
          );
        })}
        {children}
      </div>
      {/* PINNED OUTSIDE THE SCROLLER, because the way out of a narrowing must
          not itself be somewhere you have to scroll to. Clear All is in the
          panel too — this is where you are when you decide you want none of
          it. */}
      <button
        type="button"
        onClick={() => onChange(new Set())}
        className="shrink-0 rounded-sm text-sm text-muted-foreground underline-offset-2 outline-none hover:text-foreground hover:underline focus-visible:ring-2 focus-visible:ring-ring/50"
      >
        Clear all
      </button>
    </div>
  );
}

/*
  THE VIEW BAR (Pavan, 2026-10-22) — a row ON the view: above the table
  header (`ListTable topBar`), or above the lanes (`BoardWithBar`). Its left
  says what is shown; its right carries the view's own tools, which the
  toolbar renders into it (`ListToolbar viewToolsInto`). Every list with a
  table or a board has one.
*/
export function useViewBar() {
  const [into, setInto] = React.useState<HTMLDivElement | null>(null);
  return { into, ref: setInto, slot: <div ref={setInto} /> };
}

/** "62 orders · Thu, Oct 22, 2026" — the count leads, the rest follows. */
export function ViewStatement({
  count,
  one,
  many,
  rest,
}: {
  count: number;
  one: string;
  many: string;
  /** What follows the count — the lanes, the window. */
  rest?: string;
}) {
  return (
    <>
      <span className="font-medium text-foreground">
        {count.toLocaleString()} {count === 1 ? one : many}
      </span>
      {rest ? ` ${rest}` : ""}
    </>
  );
}

/** A board under its view bar — the bar a white strip, the lanes below. */
export function BoardWithBar({
  barRef,
  children,
}: {
  barRef: (el: HTMLDivElement | null) => void;
  children: React.ReactNode;
}) {
  return (
    <div className="flex h-full min-h-0 flex-col gap-3">
      <div ref={barRef} className="shrink-0 rounded-md border border-border bg-fp-surface-1b" />
      <div className="min-h-0 flex-1">{children}</div>
    </div>
  );
}

import * as React from "react";
import { CircleDot, Plus, UserRound, CalendarClock, Ban } from "lucide-react";
import { TERM_ICONS } from "@/components/ui/term-icons";
import { cn } from "@/lib/utils";
import { SheetSection } from "@/components/side-sheet/parts";
import { DATE_FMT } from "./data";

/**
 * THE CHANGE LOG, for modules that did not have one — Sales today (Pavan,
 * 2026-09-23). The same shape as a 3PL order's `audit` and a service order's:
 * one entry per save that changed something MEANINGFUL, each change in words
 * with the old value and the new.
 *
 * WHAT COUNTS IS THE MODULE'S DIFF, NOT THIS FILE. Each module passes the
 * function that decides which changes are events (the approved list); typing
 * that changes nothing on that list writes nothing.
 */
export interface ActivityEntry {
  at: string;
  by: string;
  changes: string[];
}

type Logged = { id: string; audit?: ActivityEntry[] };

/** Who is making the change. The prototype has one signed-in dispatcher. */
export const ACTOR = "Dana Whitfield";

/**
 * A row list whose setter writes the log. ONE WRAPPER ROUND THE ONLY SETTER,
 * so no path that edits a row — the sheet, a bulk edit, creation — can forget
 * to log: a new row starts with `createdText`, and a changed row gets an entry
 * listing whatever `diff` says changed.
 */
export function useLoggedRows<T extends Logged>(
  initial: T[],
  diff: (before: T, after: T) => string[],
  createdText = "Order created"
): [T[], (fn: (prev: T[]) => T[]) => void] {
  const [rows, setRaw] = React.useState<T[]>(initial);
  const setRows = React.useCallback(
    (fn: (prev: T[]) => T[]) =>
      setRaw((prev) => {
        const next = fn(prev);
        const at = new Date().toISOString();
        return next.map((r) => {
          const before = prev.find((x) => x.id === r.id);
          if (!before)
            return r.audit?.length
              ? r
              : { ...r, audit: [{ at, by: ACTOR, changes: [createdText] }] };
          if (before === r) return r;
          const changes = diff(before, r);
          return changes.length > 0
            ? { ...r, audit: [...(r.audit ?? []), { at, by: ACTOR, changes }] }
            : r;
        });
      }),
    [diff, createdText]
  );
  return [rows, setRows];
}

const STAMP_TIME = new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" });
/* IN A CHOSEN ZONE WHEN ONE IS GIVEN — Sales passes its Preferences time
   zone (2026-10-07); without one, the browser's. */
const stamp = (iso: string, timeZone?: string) => {
  const d = new Date(iso);
  if (!timeZone) return `${DATE_FMT.format(d)} · ${STAMP_TIME.format(d)}`;
  const date = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric", timeZone });
  const time = new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit", timeZone });
  return `${date.format(d)} · ${time.format(d)}`;
};

function mark(text: string): { icon: React.ReactNode; tone: string } {
  const quiet = "border-border bg-card text-muted-foreground";
  if (/created/i.test(text))
    return { icon: <Plus />, tone: "border-status-success/30 bg-status-success/10 text-status-success" };
  if (/cancel/i.test(text))
    return { icon: <Ban />, tone: "border-status-failed/30 bg-status-failed/10 text-status-failed" };
  if (/^(Driver|Status)/.test(text)) return { icon: <UserRound />, tone: quiet };
  if (/^(Planned|Delivery date)/.test(text)) return { icon: <CalendarClock />, tone: quiet };
  /* THE TERM'S OWN ICON (DS term-icons, Pavan, 2026-10-20). */
  if (/^Products/.test(text)) return { icon: <TERM_ICONS.products />, tone: quiet };
  return { icon: <CircleDot />, tone: quiet };
}

/**
 * The log as a timeline — 3PL's shape: a line down the marks, most recent
 * first, the change leading and who/when under it. Rendered as its own
 * section at the foot of a sheet that has no rail.
 */
export function ActivitySection({
  entries,
  timeZone,
}: {
  entries: ActivityEntry[] | undefined;
  timeZone?: string;
}) {
  const rows = [...(entries ?? [])]
    .reverse()
    .flatMap((e, i) => e.changes.map((c, j) => ({ e, c, key: `${e.at}-${i}-${j}` })));
  return (
    <SheetSection title="Activity">
      {rows.length === 0 ? (
        <p className="text-sm text-muted-foreground">Nothing has changed yet.</p>
      ) : (
        <ol className="flex flex-col">
          {rows.map(({ e, c, key }, idx) => {
            const m = mark(c);
            return (
              <li key={key} className="relative flex gap-3 pb-4 last:pb-0">
                {idx < rows.length - 1 && (
                  <span aria-hidden className="absolute top-7 bottom-0 left-[13px] w-px bg-border" />
                )}
                <span
                  className={cn(
                    "relative z-10 flex size-7 shrink-0 items-center justify-center rounded-full border [&_svg]:size-3.5",
                    m.tone
                  )}
                >
                  {m.icon}
                </span>
                <span className="flex min-w-0 flex-col gap-0.5 pt-0.5">
                  <span className="text-sm break-words text-foreground">{c}</span>
                  <span className="text-xs text-muted-foreground">
                    {stamp(e.at, timeZone)} · {e.by}
                  </span>
                </span>
              </li>
            );
          })}
        </ol>
      )}
    </SheetSection>
  );
}

import type {
  CoreFuelStage,
  FuelOrder,
  FuelOrderStatus,
  ProductQty,
} from "./types";

/** Sum of a row's product lines — the Qty (Gal) value. */
export function totalGal(products: ProductQty[]): number {
  return products.reduce((n, p) => n + p.gal, 0);
}

/* -------------------------------------------------------------- money ----- */

/**
 * MONEY, AND THERE IS ONLY ONE. Always two places — `$4.30`, and `$4.00`
 * rather than `$4`. A column where some figures carry cents and others do not
 * cannot be scanned down, and the same total read `$147` on one screen and
 * `$147.00` on another depending on which of eight local formatters the file
 * happened to define. Eight became this on 2026-09-22.
 *
 * Intl, not a template literal, so a negative is `-$4,183.50` and not
 * `$-4,183.50`.
 */
const MONEY_FMT = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

export const MONEY = (n: number): string => MONEY_FMT.format(n);

/**
 * A PER-UNIT RATE IS NOT A TOTAL. $0.245 a gallon is three real places, and
 * rounding it to $0.25 changes the arithmetic on the invoice — so rates get
 * their own helper rather than a `dp` argument on the money one, which is how
 * a total ends up rendered to four places by accident.
 */
export const RATE = (n: number, dp = 3): string =>
  new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: dp,
    maximumFractionDigits: dp,
  }).format(n);

/* -------------------------------------------------------------- dates ----- */

/**
 * A BILLING PERIOD IS A MONTH, not a day — "Sep 2026". Beside `DATE_FMT`
 * because a formatter defined inline in the one screen that needs it is the
 * ninth money helper waiting to happen.
 */
export const MONTH_FMT = new Intl.DateTimeFormat("en-US", {
  month: "short",
  year: "numeric",
  timeZone: "UTC",
});

export const DATE_FMT = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
});

const WEEKDAY_FMT = new Intl.DateTimeFormat("en-US", {
  weekday: "short",
  month: "short",
  day: "numeric",
  year: "numeric",
});

/** Local midnight — so date maths never crosses a day on a timezone offset. */
export function startOfDay(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

/** `YYYY-MM-DD` in local time. The key the date filter compares on. */
export function dateKeyOf(d: Date): string {
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${d.getFullYear()}-${m}-${day}`;
}

/** Full label for the toolbar's date control, e.g. "Mon, Aug 24, 2026". */
export function formatFullDate(d: Date): string {
  return WEEKDAY_FMT.format(d);
}

function addDays(d: Date, n: number): Date {
  const out = new Date(d);
  out.setDate(out.getDate() + n);
  return out;
}

/** "Today" / "Yesterday" / "Tomorrow", else the weekday name. */
export function relativeLabel(offset: number, d: Date): string {
  if (offset === 0) return "Today";
  if (offset === -1) return "Yesterday";
  if (offset === 1) return "Tomorrow";
  return new Intl.DateTimeFormat("en-US", { weekday: "long" }).format(d);
}

/**
 * Seed rows — the orders visible in the Sales Console screenshots, transcribed
 * rather than invented, then cycled to the source list's 115-order total.
 *
 * SAMPLE DATA, three places only:
 *  • Per-product gallons. The source list showed one total per row, never a
 *    split, so the lines below are apportioned to sum to the observed total.
 *  • Two rows are typed Extraction. The captured screens were all Delivery, but
 *    the Type column now carries two values, so both need to appear.
 *  • Tags. The source app's tag control was empty in every capture, so these
 *    labels are invented placeholders for the truncation behaviour.
 *  • Two rows lost their driver. As transcribed they carried a driver AND the
 *    status "Unassigned" (source orders 4592861 and 4592860), which cannot hold
 *    once status is derived from driver presence. They are driverless here so
 *    the data satisfies the derivation. See the note on `status` below.
 *
 * The planned TIME per row is the single time the source list actually showed;
 * the planned DATE is derived from the row's day offset.
 *
 * Dates are stored as an offset from today rather than the literal "Aug 24,
 * 2026" strings that were captured. The captured meaning was "today and
 * yesterday", and encoding that relatively keeps the Today/Yesterday labels
 * honest — and gives the toolbar's date filter something to find on either side
 * of today.
 */
interface Seed
  extends Omit<
    FuelOrder,
    "id" | "orderNo" | "qtyGal" | "date" | "dateKey" | "planned" | "status" | "urgent"
  > {
  /** Days from today. 0 = today, -1 = yesterday. */
  dayOffset: number;
  /** Planned time; the planned DATE is derived from `dayOffset`. `null` = none. */
  plannedTime: string | null;
}

