import * as React from "react";
import { Plus, X } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";

/** Small circular initial badge used as a token / item leading glyph. */
function InitialBadge({ label }: { label: string }) {
  return (
    <span className="flex size-4 items-center justify-center rounded-full bg-accent text-[9px] font-semibold uppercase">
      {label[0]}
    </span>
  );
}

/*
  Token multi-select / combobox — "Dropdown … Add Margins" (Figma 27593:15012).
  Empty state shows an add affordance; chosen options render as removable token
  chips (leading initial badge + label + ×). Re-opening the popover toggles
  membership.

  TWO MODES, so one component serves the showcase and a real form:

  • UNCONTROLLED (no `value`) — the original demo: its own state over its own
    six options. Every existing caller lands here unchanged.
  • CONTROLLED (`value` + `onChange`) — the caller owns the selection and
    supplies the options, because WHAT can be chosen is a property of the data,
    not of the control. Same split the Group By menu and the bulk bar make.

  The labels follow: `addLabel` and `searchPlaceholder` said "Margins" because
  the demo was about margins. A form picking POCs should not.
*/

const DEMO_OPTIONS = [
  "Text 1",
  "Text 2",
  "Text 3",
  "Margin A",
  "Margin B",
  "Margin C",
];

export interface MultiSelectProps {
  /** Uncontrolled starting selection. Ignored when `value` is supplied. */
  defaultSelected?: string[];
  /** Choosable options. Defaults to the showcase's own list. */
  options?: readonly string[];
  /** Supply with `onChange` to control the selection. */
  value?: string[];
  onChange?: (next: string[]) => void;
  /** The add affordance's label, shown when nothing is chosen. */
  addLabel?: string;
  searchPlaceholder?: string;
  emptyText?: string;
  /**
   * Merged into the trigger, so the same control can serve as a full-width
   * FIELD or as a section-heading ACTION. The base is the field: `w-full` and
   * a 44px box. A heading action passes `w-auto` and a lighter frame — one
   * control either way, because two would drift apart.
   */
  className?: string;
}

export function MultiSelect({
  defaultSelected = [],
  options = DEMO_OPTIONS,
  value,
  onChange,
  addLabel = "Add Margins",
  searchPlaceholder = "Search margins...",
  emptyText = "No options found.",
  className,
}: MultiSelectProps) {
  const [open, setOpen] = React.useState(false);
  const [own, setOwn] = React.useState<string[]>(defaultSelected);
  const controlled = value !== undefined;
  const selected = controlled ? value : own;
  const commit = (next: string[]) => {
    if (!controlled) setOwn(next);
    onChange?.(next);
  };

  const toggle = (opt: string) =>
    commit(
      selected.includes(opt) ? selected.filter((o) => o !== opt) : [...selected, opt]
    );

  const remove = (opt: string) => commit(selected.filter((o) => o !== opt));

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          type="button"
          data-slot="multiselect-trigger"
          className={cn(
            "flex min-h-11 w-full flex-wrap items-center gap-2 rounded-md border border-input bg-transparent px-2 py-2 text-left outline-none transition-colors",
            "hover:border-fp-outline-2 focus-visible:ring-2 focus-visible:ring-ring/50",
            "data-[state=open]:border-ring",
            selected.length === 0 && "justify-center",
            className
          )}
        >
          {selected.map((opt) => (
            <span
              key={opt}
              className="inline-flex items-center gap-1.5 rounded-md border border-border bg-fp-surface-1b py-1 pr-1 pl-1.5 text-sm"
            >
              <InitialBadge label={opt} />
              {opt}
              <span
                role="button"
                tabIndex={-1}
                aria-label={`Remove ${opt}`}
                onClick={(e) => {
                  e.stopPropagation();
                  remove(opt);
                }}
                className="flex size-4 items-center justify-center rounded-sm text-muted-foreground hover:text-foreground"
              >
                <X className="size-3.5" />
              </span>
            </span>
          ))}
          <span className="inline-flex items-center gap-1 text-sm text-muted-foreground">
            <Plus className="size-4" />
            {addLabel}
          </span>
        </button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-(--radix-popover-trigger-width) p-0"
      >
        <Command>
          <CommandInput placeholder={searchPlaceholder} />
          <CommandList>
            <CommandEmpty>{emptyText}</CommandEmpty>
            <CommandGroup>
              {options.map((opt) => (
                <CommandItem
                  key={opt}
                  value={opt}
                  icon={<InitialBadge label={opt} />}
                  selected={selected.includes(opt)}
                  // keep the menu open for multi-select; cmdk doesn't close it
                  onSelect={() => toggle(opt)}
                >
                  {opt}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

import * as React from "react";
import { Pencil, X } from "lucide-react";
import { cn } from "@/lib/utils";

/*
  "Signature" (Figma 27593:15012). Empty state: a dashed-free dark pad reading
  "Click or draw signature here". Drawn state: the captured strokes with a clear
  (×) control. Pointer-drawn on a <canvas>.
*/
export function SignaturePad() {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const drawing = React.useRef(false);
  const [hasInk, setHasInk] = React.useState(false);

  // Size the bitmap to the element (accounting for DPR) so strokes stay crisp.
  // A canvas takes no CSS tokens, so the ink colour is read off the element as a
  // computed custom property and re-read when the theme class flips (same pattern
  // as Dashboard's useThemeColors) — never a hardcoded hex, which would only
  // read on one of the two themes.
  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.scale(dpr, dpr);
    ctx.lineWidth = 2;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    const readInk = () => {
      const ink = getComputedStyle(canvas).getPropertyValue("--foreground").trim();
      ctx.strokeStyle = ink || "currentColor";
    };
    readInk();
    const obs = new MutationObserver(readInk);
    obs.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });
    return () => obs.disconnect();
  }, []);

  const pos = (e: React.PointerEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
  };

  const start = (e: React.PointerEvent) => {
    drawing.current = true;
    canvasRef.current?.setPointerCapture(e.pointerId);
    const ctx = canvasRef.current!.getContext("2d")!;
    const { x, y } = pos(e);
    ctx.beginPath();
    ctx.moveTo(x, y);
  };

  const move = (e: React.PointerEvent) => {
    if (!drawing.current) return;
    const ctx = canvasRef.current!.getContext("2d")!;
    const { x, y } = pos(e);
    ctx.lineTo(x, y);
    ctx.stroke();
    if (!hasInk) setHasInk(true);
  };

  const end = () => {
    drawing.current = false;
  };

  const clear = () => {
    const canvas = canvasRef.current!;
    const ctx = canvas.getContext("2d")!;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    setHasInk(false);
  };

  return (
    <div
      className={cn(
        "relative h-32 w-full overflow-hidden rounded-md border border-border bg-fp-surface-1a",
        !hasInk && "cursor-crosshair"
      )}
    >
      <canvas
        ref={canvasRef}
        onPointerDown={start}
        onPointerMove={move}
        onPointerUp={end}
        onPointerLeave={end}
        className="absolute inset-0 size-full touch-none"
      />
      {!hasInk && (
        <div className="pointer-events-none absolute inset-0 flex items-center justify-center gap-2 text-sm text-muted-foreground">
          <Pencil className="size-4" />
          Click or draw signature here
        </div>
      )}
      {hasInk && (
        <button
          type="button"
          onClick={clear}
          aria-label="Clear signature"
          className="absolute top-2 right-2 flex size-7 items-center justify-center rounded-sm text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
        >
          <X className="size-4" />
        </button>
      )}
    </div>
  );
}

import type * as React from "react";

import { Slider } from "@/components/ui/slider";
import { cn } from "@/lib/utils";

/*
  A delivery window, as a range on a day.

  WHY NOT A DROPDOWN. The list held six fixed windows, and a window is not a
  category — it is two times. A customer who can take a load between 7 and 11
  had to be filed under "6:00 AM – 10:00 AM" and the two hours of difference
  lived in somebody's head. Six options also cannot say "all day", which is a
  real answer, or "a two-hour slot", which is the one that matters when a site
  has a gate that opens twice.

  THE DAY IS THE SCALE, and it is drawn: midnight to midnight with the working
  hours marked, so a window reads as a POSITION rather than as a pair of
  numbers. That is the whole argument for a slider here — you are choosing
  where in the day something sits, and a list makes you translate.

  THIRTY-MINUTE STEPS. Fuel delivery is not scheduled to the minute, and a
  slider that can land on 8:07 offers a precision the business does not have.
*/

const STEP_MIN = 30;
const DAY_MIN = 24 * 60;

/** `8:00 AM`. Midnight prints as `12:00 AM`, and 24:00 as `12:00 AM` next day. */
export function formatMinutes(total: number): string {
  const m = ((total % DAY_MIN) + DAY_MIN) % DAY_MIN;
  const h24 = Math.floor(m / 60);
  const mm = m % 60;
  const suffix = h24 < 12 ? "AM" : "PM";
  const h12 = h24 % 12 === 0 ? 12 : h24 % 12;
  return `${h12}:${String(mm).padStart(2, "0")} ${suffix}`;
}

/** `8:00 AM` back to minutes. Tolerant of the `8:00 AM – 12:00 PM` halves. */
export function parseMinutes(label: string): number | null {
  const m = label.trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (!m) return null;
  let h = Number(m[1]) % 12;
  if (m[3].toUpperCase() === "PM") h += 12;
  return h * 60 + Number(m[2]);
}

/** `"8:00 AM – 12:00 PM"` → `[480, 720]`. Null when it does not parse. */
export function parseWindow(label: string): [number, number] | null {
  const [a, b] = label.split(/[–-]/);
  if (!a || !b) return null;
  const start = parseMinutes(a);
  const end = parseMinutes(b);
  return start === null || end === null ? null : [start, end];
}

export const formatWindow = (start: number, end: number) =>
  `${formatMinutes(start)} – ${formatMinutes(end)}`;

/** Hours worth labelling. Every sixth, so the scale reads without crowding. */
const TICKS = [0, 6, 12, 18, 24];

/** `4 hr window`, or `All day` when the pair covers midnight to midnight. */
export function formatSpan(start: number, end: number): string {
  const span = end - start;
  if (span >= DAY_MIN) return "All day";
  return `${(span / 60).toLocaleString(undefined, { maximumFractionDigits: 1 })} hr window`;
}

export interface TimeWindowSliderProps {
  /** Minutes from midnight. */
  start: number;
  end: number;
  onChange: (start: number, end: number) => void;
  /** Shortest window the slider will allow, in minutes. Default 60. */
  minSpan?: number;
  /**
   * The field's own label. Given here rather than by a wrapping `SheetField`
   * so the label and the value it produces share ONE line — see below.
   */
  label?: React.ReactNode;
  /** Marks the label with the destructive asterisk the DS forms already use. */
  required?: boolean;
  /** Read-only — a record past the point where its schedule can move. */
  disabled?: boolean;
  className?: string;
  "aria-label"?: string;
}

export function TimeWindowSlider({
  start,
  end,
  onChange,
  minSpan = 60,
  label,
  required,
  disabled,
  className,
  "aria-label": ariaLabel = "Delivery window",
}: TimeWindowSliderProps) {
  return (
    /*
      ONE FIELD, ONE HEIGHT. The label, the value and the track used to sit on
      three lines, which made this field taller than the date beside it and
      broke the row: two controls that are answered together should finish
      together. Label and value now share the label's line, and the track and
      its scale fill exactly the 36px a control occupies — so the field is the
      same height as any other, and the row's baselines line up.
    */
    <div className={cn("flex flex-col gap-1.5", className)}>
      {/* THE VALUE IS READ, not inferred from where the handles sit. A slider
          whose value can only be estimated is one people distrust for anything
          precise — so it is printed, next to the name of the thing it sets. */}
      {/* THE WINDOW NEVER TRUNCATES (2026-10-15 — sheets now fit their
          content, so a half-width field is ~280px). The span note is the one
          that gives way: it truncates first. */}
      <div className="flex min-w-0 items-baseline justify-between gap-3">
        <span className="flex shrink-0 items-baseline gap-2">
          {label && (
            <span className="text-sm font-medium whitespace-nowrap text-foreground">
              {label}
              {required && <span className="text-destructive"> *</span>}
            </span>
          )}
          <span className="text-sm whitespace-nowrap tabular-nums text-foreground">
            {formatWindow(start, end)}
          </span>
        </span>
        <span className="min-w-0 truncate text-xs text-muted-foreground">
          {formatSpan(start, end)}
        </span>
      </div>

      {/*
        THE CONTROL ZONE IS THE INPUT'S OWN 36px, and the two parts are placed
        inside it rather than stacked to fill it. The scale is pinned to the
        floor, so its baseline is the input's bottom edge.

        THE TRACK IS CENTRED BETWEEN THE TWO LINES OF TEXT, not in the box.
        Centring it in the box put 21px of air above it and 7px below, so the
        value on top read as belonging to nothing and the scale looked stuck to
        the track. It now sits halfway between the bottom of the value and the
        top of the scale — 12px of air either side — which is what makes the
        three lines read as one control.
      */}
      <div className="relative h-9">
        <Slider
          className="absolute inset-x-0 top-1.5"
          aria-label={ariaLabel}
          min={0}
          max={DAY_MIN}
          step={STEP_MIN}
          minStepsBetweenThumbs={minSpan / STEP_MIN}
          value={[start, end]}
          disabled={disabled}
          onValueChange={([a, b]) => onChange(a, b)}
        />

        {/* THE SCALE, so the handles have something to mean. Without it the
            track is a bare line and "where in the day is this" is unanswerable
            without reading the numbers above.

            THE END LABELS ARE NOT CENTRED. Midnight sits at 0% and at 100%, so
            centring hung half of each one outside the field — the left edge of
            the form stepped out and back for one label. They are pinned to the
            edges instead, which is also where the track starts and stops. */}
        <div
          aria-hidden
          className="absolute inset-x-0 bottom-0 h-3 leading-none select-none"
        >
          {TICKS.map((h, i) => {
            const first = i === 0;
            const last = i === TICKS.length - 1;
            return (
              <span
                key={h}
                className={cn(
                  "absolute bottom-0 text-[11px] leading-none tabular-nums text-muted-foreground",
                  first && "left-0",
                  last && "right-0",
                  !first && !last && "-translate-x-1/2"
                )}
                style={first || last ? undefined : { left: `${(h / 24) * 100}%` }}
              >
                {h === 0 || h === 24 ? "12a" : h === 12 ? "12p" : h < 12 ? `${h}a` : `${h - 12}p`}
              </span>
            );
          })}
        </div>
      </div>
    </div>
  );
}

export { FormLayout, type FormLayoutProps } from "./FormLayout";
export {
  TableCellSelect,
  TableCellCombobox,
  TableCellInput,
  TableCellMultiSelect,
  TableRequiredLabel,
  type TableCellSelectProps,
  type TableCellComboboxProps,
  type TableCellInputProps,
  type TableCellMultiSelectProps,
} from "./table-cells";
export {
  TimeWindowSlider,
  formatWindow,
  parseWindow,
  formatMinutes,
  parseMinutes,
  type TimeWindowSliderProps,
} from "./TimeWindowSlider";

import * as React from "react";
import { Check, ChevronDown, Trash2, X } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";

/*
  Editable table cells — Figma "Input / Dropdown Tables Layout"
  (27593:15012 / 27592:33634).

  THE RULE THESE ENCODE: a cell in an editable table has NO control chrome of
  its own. It fills the whole `td`, and its states are carried by the cell —
  hover lifts to `--accent`, focus washes to Surface-1a with an inset ring. A
  bordered input or select dropped inside a padded cell puts a box inside a box:
  the table already draws the grid, so the control redrawing it is the second
  border, and the cell's real edges stop being the thing you read.

  Extracted from `EditableTable`, which was the only place they existed, so a
  real form's table can follow the same idiom instead of nesting controls.

  The parent `td` must be `relative` and `p-0` — a table cell gives no definite
  height for `h-full` to resolve against, so `inset-0` is what makes the state
  surface span the cell.
*/

/** Required-column marker for a table header. */
export function TableRequiredLabel({
  children,
  required,
}: {
  children: React.ReactNode;
  required?: boolean;
}) {
  /* NEVER WRAPS. A column heading that breaks onto a second line stops sitting
     over the column it names, and the table reads as though its headers have
     slipped — which is exactly what it looks like. A heading too long for its
     column is a column that is too narrow, and that is fixed in the colgroup. */
  return (
    <span className="text-sm font-medium whitespace-nowrap text-foreground">
      {children}
      {required && <span className="text-destructive"> *</span>}
    </span>
  );
}

export interface TableCellSelectProps {
  value: string;
  options: string[];
  /**
   * Second line under the value. A NODE, not just a string: a cell's second
   * line is often a state — a chip saying this partner will never see the
   * invitation — and the alternative was floating that chip over the cell,
   * where a narrow column laid it on top of the name.
   */
  description?: React.ReactNode;
  placeholder?: string;
  disabled?: boolean;
  /** Option count at or above which the search field appears. Default: always. */
  searchThreshold?: number;
  onChange: (v: string) => void;
  /**
   * Take focus when the cell MOUNTS — pass it to the first editable cell of a
   * row the reader has just added, so the add is followed by the answer and
   * not by a hunt for the row (DS ui §10f, "Rows"). Mount-only: rows already
   * on the table are never re-focused.
   */
  autoFocus?: boolean;
  "aria-label"?: string;
  /**
   * PICK SEVERAL AT ONCE, AND APPLY THEM.
   *
   * A list of rows you fill one at a time asks for the same three gestures per
   * row — open, choose, open the next — when the thing being said is "these
   * five". With this the options carry checkboxes and the list keeps a footer
   * with Apply: one open, one Apply, and the caller decides what several
   * choices mean (here: fill this row and add a row per extra).
   *
   * Pass it only where a row can legitimately become many. Left off, the cell
   * writes one value and closes, which is what a cell replacing its own
   * contents should do.
   */
  multiple?: {
    /** Already chosen elsewhere in the list — shown ticked and read-only. */
    taken?: string[];
    onApply: (picked: string[]) => void;
  };
}

/**
 * A cell that opens a list and writes the choice back. No visible control.
 *
 * The list SEARCHES, like every other list in this system. Scrolling a cell's
 * popover for a name you already know is the slowest way to answer it, and a
 * cell that sometimes takes typing and sometimes does not is one you have to
 * open before you know which. `searchThreshold` can still suppress it.
 */
export function TableCellSelect({
  value,
  options,
  description,
  placeholder = "Select",
  disabled,
  searchThreshold = 1,
  onChange,
  "aria-label": ariaLabel,
  multiple,
  autoFocus,
}: TableCellSelectProps) {
  const [open, setOpen] = React.useState(false);
  const showSearch = options.length >= searchThreshold;
  /* THE TICKS ARE THE POPOVER'S, not the record's. Nothing is written until
     Apply, so closing the list without pressing it changes nothing — which is
     the difference between choosing and having chosen. */
  const [picked, setPicked] = React.useState<string[]>([]);
  React.useEffect(() => {
    if (!open) setPicked([]);
  }, [open]);
  const toggle = (opt: string) =>
    setPicked((prev) =>
      prev.includes(opt) ? prev.filter((x) => x !== opt) : [...prev, opt]
    );

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild disabled={disabled}>
        <button
          type="button"
          aria-label={ariaLabel}
          autoFocus={autoFocus}
          className={cn(
            "absolute inset-0 flex items-center justify-between gap-2 px-3 text-left transition-colors outline-none",
            "hover:bg-accent focus-visible:bg-fp-surface-1a focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50",
            disabled && "cursor-not-allowed opacity-50 hover:bg-transparent"
          )}
        >
          <span className="flex min-w-0 flex-col">
            <span
              className={cn(
                "truncate text-sm",
                value ? "text-foreground" : "text-muted-foreground"
              )}
            >
              {value || placeholder}
            </span>
            {description && (
              /* `items-start` so a chip on this line keeps its own width
                 instead of stretching to the cell. */
              <span className="flex items-start truncate text-xs text-muted-foreground">
                {description}
              </span>
            )}
          </span>
          <ChevronDown className="size-4 shrink-0 text-muted-foreground" />
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-64 p-0">
        <Command>
          {showSearch && <CommandInput placeholder="Search…" />}
          <CommandList>
            <CommandEmpty>No options.</CommandEmpty>
            <CommandGroup>
              {options.map((opt) => {
                const used = Boolean(multiple?.taken?.includes(opt)) && opt !== value;
                return (
                <CommandItem
                  key={opt}
                  value={opt}
                  disabled={used}
                  onSelect={() => {
                    if (used) return;
                    if (multiple) {
                      toggle(opt);
                      return;
                    }
                    onChange(opt);
                    setOpen(false);
                  }}
                >
                  {multiple && (
                    <Checkbox
                      checked={used || picked.includes(opt)}
                      /* The row is the control; the box reports it. */
                      tabIndex={-1}
                      aria-hidden
                      className="pointer-events-none"
                    />
                  )}
                  {opt}
                </CommandItem>
                );
              })}
            </CommandGroup>
          </CommandList>
          {multiple && (
            /* THE COUNT AND THE ACT, on one line. Apply is disabled with
               nothing ticked rather than hidden: a footer that appears and
               disappears makes the list jump as you choose. */
            <div className="flex items-center justify-between gap-2 border-t border-border p-1 pl-2.5">
              <span className="text-xs tabular-nums text-muted-foreground">
                {picked.length} selected
              </span>
              <Button
                size="sm"
                variant="ghost"
                disabled={picked.length === 0}
                onClick={() => {
                  multiple.onApply(picked);
                  setOpen(false);
                }}
              >
                Apply
              </Button>
            </div>
          )}
        </Command>
      </PopoverContent>
    </Popover>
  );
}

export interface TableCellInputProps {
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  /**
   * A SUGGESTED VALUE (Pavan, 2026-10-20) — shown as the placeholder while the
   * cell is empty; → (ArrowRight) in the empty cell takes it, as an inline
   * completion does. The suggested quantity for a tank, on an order.
   */
  suggestion?: string;
  disabled?: boolean;
  /** Right-align and tabular-align digits, for a quantity or amount column. */
  numeric?: boolean;
  /** Unit shown after the value, e.g. `gal`. Not part of the value. */
  suffix?: string;
  /**
   * Unit shown BEFORE the value, e.g. `$`. Not part of the value.
   *
   * It pins to the cell's left edge while the figure stays right-aligned,
   * which is how every ledger prints money: the symbol marks the column, the
   * digits line up for comparing. Stuck to the number it would move with the
   * number's length and stop marking anything.
   */
  prefix?: string;
  /**
   * Take focus when the cell MOUNTS — pass it to the first editable cell of a
   * row the reader has just added, so the add is followed by the answer and
   * not by a hunt for the row (DS ui §10f, "Rows"). Mount-only: rows already
   * on the table are never re-focused.
   */
  autoFocus?: boolean;
  "aria-label"?: string;
}

/** A free-text cell filling the whole td. Same states as the select. */
export function TableCellInput({
  value,
  onChange,
  placeholder,
  suggestion,
  disabled,
  numeric,
  suffix,
  prefix,
  "aria-label": ariaLabel,
  autoFocus,
}: TableCellInputProps) {
  /*
    WHAT WAS TYPED, UNTIL IT IS FINISHED BEING TYPED.

    These cells are controlled by a NUMBER upstream, and a number cannot hold a
    half-written one. Typing "1.4" sent "1." to the parent, which parsed it to
    1 and handed back "1" — so the decimal point was swallowed on every
    keystroke and no fractional rate could be entered at all. The same is true
    of a leading "0." or a trailing zero.

    While the cell has focus it shows the literal keystrokes and the parent
    still receives every one of them; on blur the buffer is dropped and the
    canonical value comes back, so "1.40" settles to "1.4" and "abc" to
    whatever the parent made of it. The parent stays the source of truth — this
    only stops it answering mid-word.
  */
  const [typed, setTyped] = React.useState<string | null>(null);
  const shown = typed ?? value;
  /*
    A CURRENCY MARK BELONGS TO ITS NUMBER, not to the cell.

    A numeric cell right-aligns its figure and the prefix was pinned to the left
    edge, so "$" and "3.57" sat at opposite ends of a 132px column with nothing
    between them — the mark read as a column header for the cell rather than as
    part of the amount. Right-align the pair instead and close the gap to 4px:
    the "$" travels with the first digit however long the number gets.

    `field-sizing-content` is what lets the input shrink to its own text so the
    prefix can sit against it; the LABEL is still the full-cell click target, so
    nothing is harder to hit. Only `numeric` cells with a prefix change — a text
    cell's input still fills the width, which is where typing should start.
  */
  const moneyish = Boolean(numeric && prefix);
  return (
    <label
      className={cn(
        "absolute inset-0 flex cursor-text items-center px-3 transition-colors",
        moneyish ? "gap-1" : "gap-1.5",
        "hover:bg-accent",
        "focus-within:bg-fp-surface-1a focus-within:ring-2 focus-within:ring-inset focus-within:ring-ring/50",
        disabled && "cursor-not-allowed opacity-50 hover:bg-transparent"
      )}
    >
      {prefix && (
        <span className="shrink-0 text-sm text-muted-foreground">{prefix}</span>
      )}
      <input
        type="text"
        value={shown}
        onChange={(e) => {
          setTyped(e.target.value);
          onChange(e.target.value);
        }}
        onBlur={() => setTyped(null)}
        onKeyDown={(e) => {
          if (suggestion && e.key === "ArrowRight" && shown === "") {
            e.preventDefault();
            setTyped(suggestion);
            onChange(suggestion);
          }
        }}
        placeholder={suggestion || placeholder}
        disabled={disabled}
        aria-label={ariaLabel}
        autoFocus={autoFocus}
        className={cn(
          "h-full min-w-0 bg-transparent text-sm text-foreground outline-none",
          "placeholder:text-muted-foreground disabled:cursor-not-allowed",
          numeric && "tabular-nums",
          moneyish ? "w-auto field-sizing-content" : "w-full"
        )}
      />
      {suffix && (
        <span className="shrink-0 text-xs text-muted-foreground">{suffix}</span>
      )}
    </label>
  );
}

export interface TableCellMultiSelectProps {
  values: string[];
  options: string[];
  placeholder?: string;
  disabled?: boolean;
  /**
   * Singular noun for the count summary — "product" prints "3 products". The
   * count is what a narrow cell can hold; the names are in the list one click
   * away, and on the `title` for a pointer that hovers.
   */
  unitLabel?: string;
  /** What the closed cell prints, when the caller shows the rest elsewhere (e.g. as sub-rows). */
  summary?: string;
  onChange: (next: string[]) => void;
  /**
   * Take focus when the cell MOUNTS — pass it to the first editable cell of a
   * row the reader has just added, so the add is followed by the answer and
   * not by a hunt for the row (DS ui §10f, "Rows"). Mount-only: rows already
   * on the table are never re-focused.
   */
  autoFocus?: boolean;
  "aria-label"?: string;
}

/**
 * A cell holding MORE THAN ONE choice — same borderless idiom as the others.
 *
 * It summarises rather than listing: one value prints itself, several print
 * their count. A cell that grew a chip per choice would change the table's row
 * height as it was filled, and a column whose rows are different heights stops
 * being scannable, which is the only reason to put this in a table at all.
 *
 * CHECKBOX ROWS AND AN APPLY (Pavan, 2026-09-24). A list with a trailing tick
 * reads as single-select — the reader picks one and stops (`MultiSelectList`
 * explains why). Ticks are a draft while the list is open; Apply commits them
 * in one go, and closing without it changes nothing.
 */
export function TableCellMultiSelect({
  values,
  options,
  placeholder = "Select",
  disabled,
  unitLabel = "selected",
  summary: summaryOverride,
  onChange,
  "aria-label": ariaLabel,
  autoFocus,
}: TableCellMultiSelectProps) {
  const [open, setOpen] = React.useState(false);
  /* THE DRAFT — what is ticked while the list is open. */
  const [draft, setDraft] = React.useState<string[]>(values);

  const summary =
    summaryOverride ??
    (values.length === 0
      ? placeholder
      : values.length === 1
        ? values[0]
        : `${values.length} ${unitLabel}${unitLabel.endsWith("s") ? "" : "s"}`);

  const toggle = (opt: string) =>
    setDraft((d) => (d.includes(opt) ? d.filter((v) => v !== opt) : [...d, opt]));

  return (
    <Popover
      open={open}
      onOpenChange={(o) => {
        if (o) setDraft(values);
        setOpen(o);
      }}
    >
      <PopoverTrigger asChild disabled={disabled}>
        <button
          type="button"
          aria-label={ariaLabel}
          autoFocus={autoFocus}
          title={values.join(", ") || undefined}
          className={cn(
            "absolute inset-0 flex items-center justify-between gap-2 px-3 text-left transition-colors outline-none",
            "hover:bg-accent focus-visible:bg-fp-surface-1a focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50",
            disabled && "cursor-not-allowed opacity-50 hover:bg-transparent"
          )}
        >
          <span
            className={cn(
              "truncate text-sm",
              values.length > 0 ? "text-foreground" : "text-muted-foreground"
            )}
          >
            {summary}
          </span>
          <ChevronDown className="size-4 shrink-0 text-muted-foreground" />
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-64 p-0">
        <Command>
          <CommandInput placeholder="Search…" />
          <CommandList>
            <CommandEmpty>No options.</CommandEmpty>
            <CommandGroup>
              {options.map((opt) => (
                <CommandItem
                  key={opt}
                  value={opt}
                  onSelect={() => toggle(opt)}
                  aria-checked={draft.includes(opt)}
                  icon={
                    <Checkbox
                      checked={draft.includes(opt)}
                      className="pointer-events-none"
                      tabIndex={-1}
                    />
                  }
                >
                  <span className="flex-1 truncate">{opt}</span>
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
        <div className="flex items-center justify-between gap-2 border-t border-border p-2">
          <span className="text-xs text-muted-foreground">
            {draft.length} selected
          </span>
          <Button
            size="sm"
            onClick={() => {
              onChange(options.filter((o) => draft.includes(o)));
              setOpen(false);
            }}
          >
            Apply
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

export interface TableCellComboboxProps {
  value: string;
  options: string[];
  placeholder?: string;
  disabled?: boolean;
  /** Allow a value that is not in `options`, offered as its own item. */
  creatable?: boolean;
  /**
   * The words on the right of the typed-value row — "Add as fee". The typed
   * text sits on the left (Pavan, 2026-09-25). Default "Add".
   */
  createLabel?: string;
  /**
   * AN OPTIONAL CELL CAN BE EMPTIED AGAIN (DS ux §Forms, 2026-09-25) — the
   * empty choice, e.g. "No asset", shown first; picking it sets "".
   */
  clearLabel?: string;
  /**
   * Values already used by OTHER rows of the same table. Shown ticked and
   * unselectable rather than hidden: removing them would make the list change
   * length as you fill the table, and someone looking for an asset they already
   * added would conclude it does not exist. Ticked says "here, and already on
   * the order".
   */
  taken?: readonly string[];
  onChange: (v: string) => void;
  /**
   * Take focus when the cell MOUNTS — pass it to the first editable cell of a
   * row the reader has just added, so the add is followed by the answer and
   * not by a hunt for the row (DS ui §10f, "Rows"). Mount-only: rows already
   * on the table are never re-focused.
   */
  autoFocus?: boolean;
  "aria-label"?: string;
  /**
   * PICK SEVERAL, ONE ROW EACH — `TableCellSelect`'s `multiple`, for a cell
   * you can also type into. Checkboxes, a footer with Apply; a typed name is
   * ticked like any other. The caller fills this row with the first and adds a
   * row per extra (DS ui §10f "Picking several makes rows"). Pass it only on a
   * BLANK row: on a filled one the question is "which one instead".
   */
  multiple?: {
    onApply: (picked: string[]) => void;
  };
}

/**
 * A cell you can TYPE INTO or PICK FROM — same borderless idiom as the others.
 *
 * A plain select cannot reach a value the list has not caught up with; a plain
 * input cannot attach to a real record. `creatable` keeps whatever was typed
 * available as its own option, so a new name is one Enter away rather than a
 * second-class path.
 */
export function TableCellCombobox({
  value,
  options,
  placeholder = "Select",
  disabled,
  creatable,
  createLabel = "Add",
  clearLabel,
  taken,
  onChange,
  "aria-label": ariaLabel,
  autoFocus,
  multiple,
}: TableCellComboboxProps) {
  const [open, setOpen] = React.useState(false);
  const [query, setQuery] = React.useState("");
  /* NOTHING IS WRITTEN UNTIL APPLY — as in TableCellSelect. */
  const [picked, setPicked] = React.useState<string[]>([]);
  React.useEffect(() => {
    if (!open) setPicked([]);
  }, [open]);
  const toggle = (v: string) =>
    setPicked((prev) => (prev.includes(v) ? prev.filter((x) => x !== v) : [...prev, v]));

  const matches = options.filter((o) =>
    o.toLowerCase().includes(query.trim().toLowerCase())
  );
  const typedIsNew =
    Boolean(creatable) &&
    query.trim().length > 0 &&
    !options.some((o) => o.toLowerCase() === query.trim().toLowerCase());

  const choose = (v: string) => {
    if (multiple && v) {
      toggle(v);
      setQuery("");
      return;
    }
    onChange(v);
    setQuery("");
    setOpen(false);
  };
  /* Typed names the reader ticked — not in `options`, so listed on their own. */
  const pickedNew = picked.filter((p) => !options.includes(p));

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild disabled={disabled}>
        <button
          type="button"
          aria-label={ariaLabel}
          autoFocus={autoFocus}
          className={cn(
            "absolute inset-0 flex items-center justify-between gap-2 px-3 text-left transition-colors outline-none",
            "hover:bg-accent focus-visible:bg-fp-surface-1a focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50",
            disabled && "cursor-not-allowed opacity-50 hover:bg-transparent"
          )}
        >
          <span
            className={cn(
              "truncate text-sm",
              value ? "text-foreground" : "text-muted-foreground"
            )}
          >
            {value || placeholder}
          </span>
          <ChevronDown className="size-4 shrink-0 text-muted-foreground" />
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-64 p-0">
        <Command shouldFilter={false}>
          <CommandInput
            value={query}
            onValueChange={setQuery}
            placeholder={creatable ? "Type or pick…" : "Search…"}
          />
          <CommandList>
            {typedIsNew && (
              <CommandGroup>
                {/* WHAT WAS TYPED ON THE LEFT, THE ACT ON THE RIGHT (Pavan,
                    2026-09-25) — it read "Use “…”". */}
                <CommandItem value={query} onSelect={() => choose(query.trim())}>
                  <span className="min-w-0 flex-1 truncate">{query.trim()}</span>
                  <span className="shrink-0 text-xs text-muted-foreground">{createLabel}</span>
                </CommandItem>
              </CommandGroup>
            )}
            {multiple && pickedNew.length > 0 && !query.trim() && (
              <CommandGroup>
                {pickedNew.map((o) => (
                  <CommandItem key={o} value={o} onSelect={() => toggle(o)}>
                    <Checkbox checked tabIndex={-1} aria-hidden className="pointer-events-none" />
                    <span className="flex-1 truncate">{o}</span>
                  </CommandItem>
                ))}
              </CommandGroup>
            )}
            {clearLabel && !multiple && !query.trim() && (
              <CommandGroup>
                <CommandItem value="__clear__" onSelect={() => choose("")}>
                  <span className="flex-1 truncate text-muted-foreground">{clearLabel}</span>
                  {!value && <Check className="size-4 shrink-0" />}
                </CommandItem>
              </CommandGroup>
            )}
            {matches.length > 0 && (
              <CommandGroup>
                {matches.map((o) => {
                  const used = o !== value && Boolean(taken?.includes(o));
                  return (
                    <CommandItem
                      key={o}
                      value={o}
                      disabled={used}
                      onSelect={() => !used && choose(o)}
                    >
                      {multiple && (
                        /* Already on another row: ticked and locked. */
                        <Checkbox
                          checked={used || picked.includes(o)}
                          tabIndex={-1}
                          aria-hidden
                          className="pointer-events-none"
                        />
                      )}
                      <span className="flex-1 truncate">{o}</span>
                      {!multiple && (used || o === value) && (
                        <Check className="size-4 shrink-0" />
                      )}
                    </CommandItem>
                  );
                })}
              </CommandGroup>
            )}
            <CommandEmpty>
              {creatable ? "Type a name to add it." : "No matches."}
            </CommandEmpty>
          </CommandList>
          {multiple && (
            <div className="flex items-center justify-between gap-2 border-t border-border p-1 pl-2.5">
              <span className="text-xs tabular-nums text-muted-foreground">
                {picked.length} selected
              </span>
              <Button
                size="sm"
                variant="ghost"
                disabled={picked.length === 0}
                onClick={() => {
                  multiple.onApply(picked);
                  setOpen(false);
                }}
              >
                Apply
              </Button>
            </div>
          )}
        </Command>
      </PopoverContent>
    </Popover>
  );
}

export interface TableRowRemoveProps {
  /** Runs only after the tick. */
  onRemove: () => void;
  /** The SUBJECT — "Remove Gas Pr 1", or "Remove fee 2" while the row is blank. */
  "aria-label": string;
  disabled?: boolean;
  /**
   * `cell` (default): the pair FILLS its `relative p-0` td, ✕ over ✓ — the DS
   * Figma 28133:1526. `inline`: the pair sits side by side, for a bin that
   * lives inside another cell's padding (a charge's type cell).
   */
  layout?: "cell" | "inline";
}

/**
 * A ROW'S DELETE ASKS FIRST (Pavan, 2026-09-23). The bin, quiet until the row
 * is reached for, swaps on press for ✕ cancel and ✓ confirm — the tick is the
 * "are you sure?". Nothing goes on one careless click, and there is no dialog:
 * the question is asked where the finger already is. DS ui §10f "Rows".
 *
 * Escape, ✕, or focus leaving the pair takes it back. The row needs
 * `group/row` for the bin's hover reveal; the armed pair ignores hover and
 * stays until answered.
 */
export function TableRowRemove({
  onRemove,
  "aria-label": ariaLabel,
  disabled,
  layout = "cell",
}: TableRowRemoveProps) {
  const [armed, setArmed] = React.useState(false);
  const cancelRef = React.useRef<HTMLButtonElement>(null);
  React.useEffect(() => {
    if (armed) cancelRef.current?.focus();
  }, [armed]);

  if (!armed) {
    return (
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        aria-label={ariaLabel}
        disabled={disabled}
        className="text-muted-foreground opacity-0 transition-opacity group-hover/row:opacity-100 hover:bg-destructive/15 hover:text-destructive focus-visible:opacity-100 disabled:opacity-0"
        onClick={(e) => {
          e.stopPropagation();
          setArmed(true);
        }}
      >
        <Trash2 />
      </Button>
    );
  }

  const inline = layout === "inline";
  const btn =
    "flex items-center justify-center outline-none transition-colors focus-visible:relative focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50";
  return (
    <div
      role="group"
      aria-label={`${ariaLabel}?`}
      className={cn(
        "flex overflow-hidden",
        inline ? "h-7 gap-1" : "absolute inset-0 flex-col"
      )}
      onKeyDown={(e) => {
        if (e.key === "Escape") {
          e.stopPropagation();
          setArmed(false);
        }
      }}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setArmed(false);
      }}
    >
      <button
        ref={cancelRef}
        type="button"
        aria-label="Keep it"
        onClick={(e) => {
          e.stopPropagation();
          setArmed(false);
        }}
        className={cn(
          btn,
          "bg-fp-card-1 text-foreground hover:bg-accent",
          inline ? "size-7 rounded-sm" : "flex-1"
        )}
      >
        <X className="size-4" />
      </button>
      <button
        type="button"
        aria-label={`Yes, ${ariaLabel.charAt(0).toLowerCase()}${ariaLabel.slice(1)}`}
        onClick={(e) => {
          e.stopPropagation();
          setArmed(false);
          onRemove();
        }}
        className={cn(
          btn,
          "bg-destructive text-white hover:bg-destructive/90",
          inline ? "size-7 rounded-sm" : "flex-1"
        )}
      >
        <Check className="size-4" />
      </button>
    </div>
  );
}

