export type SideSheetVariant = "narrow" | "wide" | "dense" | "shortcuts";

/*
  Side Sheet — Figma "Side Sheet" (27610:58293). One right-anchored sheet shell
  with three width/content variants: narrow (form), wide (embedded table), dense
  (asset picker). Slides in over a scrim; content scrolls between a fixed header
  and footer.
*/
const WIDTH: Record<SideSheetVariant, string> = {
  narrow: "w-[560px] sm:max-w-[560px]",
  wide: "w-[1200px] max-w-[96vw] sm:max-w-[1200px]",
  dense: "w-[1000px] max-w-[96vw] sm:max-w-[1000px]",
  shortcuts: "w-[480px] sm:max-w-[480px]",
};

export interface SideSheetProps {
  variant: SideSheetVariant;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title?: string;
}

export function SideSheet({ variant, open, onOpenChange, title }: SideSheetProps) {
  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        showCloseButton={false}
        className={cn("gap-0 p-0", WIDTH[variant])}
      >
        {variant === "narrow" && <SheetNarrow title={title} />}
        {variant === "wide" && <SheetWide title={title} />}
        {variant === "dense" && <SheetDense title={title} />}
        {variant === "shortcuts" && <SheetShortcuts title={title} />}
      </SheetContent>
    </Sheet>
  );
}

import * as React from "react";

/* The shared state behind `form-steps.tsx`, kept apart so that file exports only components. */

/** True inside a stepped sheet's form. */
export const FormStepsContext = React.createContext(false);
/** True inside a step, so the sections in it do not become steps too. */
export const InsideFormStepContext = React.createContext(false);

/** The attributes that make an element a step the list can find. */
export function formStepAttrs(label: string) {
  return { "data-form-step": label };
}

/**
 * The classes a step's own element takes: room for the landing blink's fill,
 * pulled back out so the fields stay where they were.
 */
export const FORM_STEP_CLASS = "-m-3 rounded-lg p-3";

import * as React from "react";
import { CircleAlert, Info, Minus } from "lucide-react";
import { cn } from "@/lib/utils";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Steps, type StepItem } from "@/components/ui/steps";
import {
  FORM_STEP_CLASS,
  FormStepsContext,
  InsideFormStepContext,
  formStepAttrs,
} from "./form-steps-context";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

/* Shared building blocks for the Side Sheet variants (Figma 27610:58293). */

/** Section = muted group heading + fields. */
export function SheetSection({
  title,
  action,
  note,
  variant: variantProp = "card",
  flush = false,
  hanging,
  bodyClassName,
  headingClassName,
  children,
  className,
  id,
}: {
  title: string;
  /**
   * `card` — the default — draws the section as a bordered block with its
   * title in a tinted header band. A sheet is a stack of questions about
   * different things, and gaps alone were carrying the whole job of saying
   * where one subject ended and the next began; at 40px they did it only for
   * as long as nothing in a section grew. The border says it at any length.
   *
   * `plain` is the old heading-over-fields form, for the handful of places
   * that are a single continuous list rather than a set of groups.
   */
  variant?: "plain" | "card" | "outline";
  /**
   * Classes for the heading text — for a form that sets its group headings at
   * a different step of the type scale.
   */
  headingClassName?: string;
  /**
   * Card variant only: drop the body's padding so a single child can run edge
   * to edge under the header band.
   *
   * FOR A SECTION THAT IS ONE TABLE. A table already draws a border, a header
   * band and a rule between every row; set inside a padded card it became a
   * box in a box, with 16px of nothing between two lines doing the same job
   * and the table's own header band sitting a hair inside the card's. Flush,
   * the card's border IS the table's border and there is one edge instead of
   * two. The child owns its own insets — anything that is not the table (an
   * Add row, a footnote) has to bring its own padding and its own top rule.
   */
  flush?: boolean;
  /**
   * A control that HANGS OFF THE CARD'S BOTTOM-LEFT, outside it.
   *
   * FOR THE ADD ON A TABLE. The card's bottom-left corner squares so the two
   * join, and the control continues the table's last row rather than sitting
   * on a full-width band inside the card — a band draws a rule across the
   * whole card to carry one small act, and reads as an empty extra row of the
   * table. (Pavan, 2026-09-22.)
   */
  hanging?: React.ReactNode;
  /**
   * Classes for the BODY, not the card — for a section that has to fill the
   * height it is given rather than wrap its content. A composer's message box
   * is the case: it should run to the bottom of the sheet, and only the body
   * can be told to grow.
   */
  bodyClassName?: string;
  /**
   * Controls that act on the SECTION rather than on one field — "Add asset",
   * "Refresh". They sit on the heading row, right-aligned, because a control
   * that owns a whole section has no field to belong to.
   */
  action?: React.ReactNode;
  /** An explainer beside the heading — typically `SheetSectionNote`. */
  note?: React.ReactNode;
  children: React.ReactNode;
  className?: string;
  /**
   * An anchor on the section, for a caller that has to bring one section into
   * view — a list's footer action that opens a record AT the part it is about.
   */
  id?: string;
}) {
  /* SECTION RHYTHM — 40 / 16. The gap between sections is 40px (owned by the
     sheet body); the gap between a section's title and its content is 16px. The
     outer gap being 2.5x the inner is what makes a heading read as belonging to
     the block beneath it rather than floating between two blocks. At 20 the
     title sat almost equidistant from both; below 16 it welds to the first
     field and the whole boundary rests on the 40.

     THE 16 IS MEASURED FROM THE TITLE, and that is the whole reason the heading
     row has no height of its own. It used to be `min-h-7` (28px) around a 20px
     line, and `items-center` split the spare 8px evenly — so what anyone could
     actually see between the words and the content was 20px, and 22px in a
     section whose heading also carried a 32px action button. The rule said 16
     and the screen said 20: the row was padding itself and calling it rhythm.

     An ACTION taller than the title now hangs off the line instead of pushing
     the content down: its wrapper is fixed at the title's own 20px and centres
     a taller child, which overflows the box without growing it. That holds for
     any control put there — a 32px button, a switch, a picker — so the 16
     cannot drift again the next time a section gains an action. */
  /* IN A STEPPED FORM (see `form-steps`) the card's band goes: a section
     that is fields becomes `plain`, a section that is a table keeps its rim as
     `outline`. A top-level section is also a step, named by its title. */
  const stepped = React.useContext(FormStepsContext);
  const insideStep = React.useContext(InsideFormStepContext);
  const isStep = stepped && !insideStep;
  const variant =
    stepped && variantProp === "card"
      ? flush || hanging
        ? "outline"
        : "plain"
      : variantProp;
  const stepAttrs = isStep ? formStepAttrs(title) : {};
  if (isStep) {
    children = (
      <InsideFormStepContext.Provider value>{children}</InsideFormStepContext.Provider>
    );
  }

  const heading = (
    <div className="flex items-center justify-between gap-4">
      <div className="flex items-center gap-1.5">
        <h3
          className={cn(
            "text-sm font-semibold text-muted-foreground",
            /* Sub-heading size, dimmed so the fields lead. */
            stepped && "text-base font-medium",
            headingClassName
          )}
        >
          {title}
        </h3>
        {/* Sits WITH the heading, not after the content: an explanation of
            how a section works belongs where the section is named, and on
            demand rather than as a paragraph everyone reads once. */}
        {note}
      </div>
      {action && (
        <div className="flex h-5 shrink-0 items-center justify-end">{action}</div>
      )}
    </div>
  );

  if (variant === "outline") {
    /* `outline` — the plain heading OVER an outlined box, no band. For a form
       whose group headings carry no fill but whose tables keep their rim.
       The box takes `flush` and `hanging` exactly as the card does. The rim
       is the data table's `--border`, per the DS table stroke. */
    const box = (
      <div
        className={cn(
          "flex shrink-0 flex-col overflow-hidden rounded-lg border border-border",
          !flush && "gap-4 p-4",
          hanging && "rounded-bl-none",
          bodyClassName
        )}
      >
        {children}
      </div>
    );
    return (
      <section
        id={id}
        {...stepAttrs}
        className={cn("flex shrink-0 flex-col gap-4", isStep && FORM_STEP_CLASS, className)}
      >
        {heading}
        {hanging ? (
          <div className="flex flex-col">
            {box}
            <div className="flex w-full items-center justify-between gap-4">
              {hanging}
            </div>
          </div>
        ) : (
          box
        )}
      </section>
    );
  }

  if (variant === "card") {
    /* THE HEADING MOVES INTO A BAND, because a title inside a bordered block
       that shares the block's fill reads as the first row of content rather
       than as the name of what follows.

       The 16px title→content rhythm the plain variant measures so carefully is
       not needed here: the band's own edge is the separation, and it holds at
       any section length — which is the thing a 40px gap could not do. */
    const card = (
      <section
        id={hanging ? undefined : id}
        /* `shrink-0` IS LOAD-BEARING, not tidiness. The sheet body is a flex
           column, and `overflow-hidden` switches a flex item's automatic
           minimum size from its content to zero — so without this the whole
           card collapses to its own 2px of border. */
        className={cn(
          /* THE RIM IS `--fp-outline-1`, NOT `--border` (Pavan, 2026-09-22).
             The DS's stroke table has said so all along — outline-1 is "a
             card's own rim" and `--border` is "a structural divider" — and
             this card was drawing the divider weight round its outside, which
             is why a card sat heavier on the page than the lines inside it.
             In DARK the two tokens carry the same value, so this is a
             light-mode correction only. */
          "shrink-0 overflow-hidden rounded-lg border border-fp-outline-1",
          /* SQUARED WHERE THE HANGING CONTROL JOINS, so the two read as one
             shape rather than a rounded box with a tab floating under it. */
          hanging && "rounded-bl-none",
          /* THE CALLER'S CLASSES GO ON WHICHEVER ELEMENT IS THE OUTER ONE.
             With something hanging, that is the wrapper below, not this —
             `lg:col-span-3` landing here put the SECTION inside a grid item
             that was still one column wide, so a section could be told to take
             three columns and silently take one. (Found 2026-09-22, on the
             Documents table.) */
          !hanging && className
        )}
      >
        <div className="border-b border-border bg-fp-surface-1a px-4 py-2.5">
          {heading}
        </div>
        <div
          className={cn(
            "flex flex-col",
            !flush && "gap-4 p-4",
            bodyClassName
          )}
        >
          {children}
        </div>
      </section>
    );

    /* THE WRAPPER OWNS THE `shrink-0` AND THE ID once there is something
       hanging: the card and its tab are one block in the sheet's stack, and
       the body's 40px gap has to fall after the tab rather than between the
       two. */
    return hanging ? (
      <div id={id} className={cn("flex shrink-0 flex-col", className)}>
        {card}
        {/* THE HANGING ROW runs the card's width so a second thing can sit at
            its right end — the add on the left, a flag about the whole unit on
            the right. With one child `justify-between` leaves it on the left,
            which is where a lone add belongs. */}
        <div className="flex w-full items-center justify-between gap-4">
          {hanging}
        </div>
      </div>
    ) : (
      card
    );
  }

  return (
    <section
      id={id}
      {...stepAttrs}
      className={cn("flex flex-col gap-4", isStep && FORM_STEP_CLASS, className)}
    >
      {heading}
      {children}
    </section>
  );
}

/**
 * The card's own insets, given back to one child of a `flush` section.
 *
 * A flush section is for a table, and a section is rarely ONLY a table — a
 * banner above it, a switch below. Those still need the 16px the body gave up,
 * and they need it individually rather than as a blanket, because the table
 * between them must keep running to the card's edge. Add `border-t`/`border-b`
 * at the call site where the inset meets the table: the rule belongs to the
 * boundary, and only the call site knows which side it is on.
 */
export function SheetSectionInset({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("flex flex-col gap-4 p-4", className)}>{children}</div>
  );
}

/**
 * The remove control for an OPTIONAL section — the one that takes a section
 * that has been turned on back to its "Add …" box.
 *
 * A MINUS, NOT A BIN. A bin says a record is about to be destroyed, and this
 * destroys nothing: the section collapses to the CTA it came from and can be
 * added again in one click. The two icons look alike at 16px and mean opposite
 * things about whether the click can be taken back, so the optional-section
 * control never wears the bin — that stays on the ROW delete inside a table,
 * where a row really does go.
 *
 * QUIET UNTIL REACHED FOR. Emptying a section that was optional in the first
 * place should not compete with the table for attention, so it is a muted icon
 * that comes to full contrast and slides its label out on hover or focus. The
 * label is what makes it safe — a bare glyph beside a table of rows reads as
 * though it might remove a row.
 *
 * IT ASKS ONLY WHEN THERE IS SOMETHING TO LOSE. `hasContent` is the caller's
 * answer to "has anyone typed anything in here yet" — with rows filled the
 * click opens a confirm, and on an untouched section it just closes it. A
 * dialog over an empty table teaches people to dismiss dialogs without reading
 * them, which is exactly the habit that makes the one that matters useless.
 */
export function SheetSectionRemove({
  label,
  hasContent,
  onClick,
}: {
  /** Names what goes, e.g. "Remove peripherals". Shown on hover and to AT. */
  label: string;
  /**
   * True when the section holds something a person put there. Only then is
   * removal worth confirming — the caller knows what "filled in" means for its
   * own rows, so it decides rather than this component guessing.
   */
  hasContent?: boolean;
  onClick: () => void;
}) {
  const trigger = (
    <button
      type="button"
      onClick={hasContent ? undefined : onClick}
      aria-label={label}
      className="group/rm flex h-8 items-center gap-1.5 rounded-md px-2 text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
    >
      <Minus className="size-4 shrink-0" />
      <span className="max-w-0 overflow-hidden text-sm whitespace-nowrap opacity-0 transition-[max-width,opacity] duration-200 group-hover/rm:max-w-40 group-hover/rm:opacity-100 group-focus-visible/rm:max-w-40 group-focus-visible/rm:opacity-100">
        {label}
      </span>
    </button>
  );

  if (!hasContent) return trigger;

  return (
    <AlertDialog>
      <AlertDialogTrigger asChild>{trigger}</AlertDialogTrigger>
      <AlertDialogContent>
        <AlertDialogHeader>
          {/* The button's own label, as a question — the dialog answers the
              click that opened it rather than restating the section's name. */}
          <AlertDialogTitle>{label}?</AlertDialogTitle>
          <AlertDialogDescription>
            Everything added here will be erased. This cannot be undone.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction variant="destructive" onClick={onClick}>
            Remove
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

/** Field = label + control + helper text. */
export function SheetField({
  label,
  description,
  required,
  children,
  className,
}: {
  /**
   * A node, not just a string: a field's label row sometimes carries a control
   * that acts on the whole field — an "Invite" beside a picker — and that
   * control belongs on the label row rather than trailing the field's body.
   */
  label?: React.ReactNode;
  description?: string;
  /** Marks the label with the destructive asterisk the DS forms already use. */
  required?: boolean;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      {label && (
        <label className="block text-sm font-medium text-foreground">
          {label}
          {required && <span className="text-destructive"> *</span>}
        </label>
      )}
      {/* HELPER TEXT IS PART OF THE CONTROL, 4px under it — not the next thing
          down the form. At the field gap it floats between two controls and gets
          read as a label for the one below. Label→control keeps the field's own
          rhythm; control→helper is always 4px. */}
      <div className="flex flex-col gap-1">
        {children}
        {description && (
          <p className="text-xs text-muted-foreground">{description}</p>
        )}
      </div>
    </div>
  );
}

/** The top-of-body alert banner shared by every variant. */
export function InfoAlert() {
  return (
    <Alert>
      <CircleAlert />
      <AlertTitle>Alert Title</AlertTitle>
      <AlertDescription>This is an alert description.</AlertDescription>
    </Alert>
  );
}

/**
 * The "why does this section behave this way" explainer, on demand.
 *
 * A paragraph under a section is read once and then permanently in the way; the
 * rule it states is needed at the moment someone WONDERS, which is rarely the
 * moment they first arrive. On CLICK rather than hover, because hover cannot be
 * reached by touch and a tooltip that appears while you are aiming at something
 * else is worse than no tooltip.
 *
 * Deliberately NARROW. Explanations set to the full width of a sheet become one
 * long line that has to be tracked back across; a few short lines are read at a
 * glance.
 */
export function SheetSectionNote({
  label = "About this section",
  children,
}: {
  /** Names the button for assistive tech. */
  label?: string;
  children: React.ReactNode;
}) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={label}
          className="flex size-5 items-center justify-center rounded-full text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 data-[state=open]:text-foreground"
        >
          <Info className="size-4" />
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-64 text-xs leading-relaxed">
        {children}
      </PopoverContent>
    </Popover>
  );
}

/**
 * The sheet's step strip — the DS `Steps` control, sized and spaced for a
 * sheet header.
 *
 * A THIN WRAPPER ON PURPOSE. It exists so a sheet does not have to remember the
 * height and the border the header strip needs, not to be a second stepper: the
 * states, the numbering, the connector and the disabled-with-a-reason behaviour
 * are all `Steps`.
 */
export function SheetSteps({
  steps,
  value,
  onValueChange,
  tone,
  variant,
}: {
  steps: StepItem[];
  value: string;
  onValueChange: (next: string) => void;
  tone?: "brand" | "accent" | "neutral";
  variant?: "track" | "rings";
}) {
  return (
    <Steps
      tone={tone}
      variant={variant}
      steps={steps}
      value={value}
      onValueChange={onValueChange}
      className="my-2.5"
    />
  );
}

import { Search, SlidersHorizontal, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import { FilterPanel } from "./FilterPanel";
import { GroupByMenu, type GroupByDimension } from "./GroupByMenu";
import { SavedViewsMenu } from "./SavedViewsMenu";

/** Per-component visibility (Settings → Action bar). Undefined ⇒ shown. */
export interface ActionBarVisible {
  search?: boolean;
  columnFilters?: boolean;
  filters?: boolean;
  groupBy?: boolean;
  savedViews?: boolean;
  cta?: boolean;
}

export interface ActionBarProps {
  searchValue?: string;
  onSearchChange?: (value: string) => void;
  onCreateTask?: () => void;
  /** Toggleable columns for the search's column-filters menu. */
  columns?: { key: string; label: string }[];
  /** Currently hidden column keys. */
  hiddenColumns?: Set<string>;
  /** Toggle a column's visibility. */
  onToggleColumn?: (key: string) => void;
  /** Groupable dimensions for this list. Omit for the menu's own demo list. */
  groupDimensions?: GroupByDimension[];
  /** Active grouping, outermost first. Supply with `onGroupByChange` to
   *  control the menu; without it the menu keeps its own single-select state. */
  groupBy?: string[];
  onGroupByChange?: (next: string[]) => void;
  /** Which action-bar components to render (Settings → Action bar). */
  visible?: ActionBarVisible;
}

/** Figma "Action bar" (id 27614:56583). Controls are 32px (size="sm"). */
export function ActionBar({
  searchValue = "",
  onSearchChange,
  onCreateTask,
  columns = [],
  hiddenColumns,
  onToggleColumn,
  groupDimensions,
  groupBy,
  onGroupByChange,
  visible = {},
}: ActionBarProps) {
  const show = (k: keyof ActionBarVisible) => visible[k] !== false;
  const search = show("search");
  const columnFilters = show("columnFilters");
  const savedViews = show("savedViews");
  const cta = show("cta");

  return (
    <div className="flex h-8 items-center justify-between gap-2">
      {/* Left cluster */}
      <div className="flex items-center gap-3">
        {/* Search field with attached column-filters button. */}
        {(search || columnFilters) && (
          <div className={cn("flex items-center", search && "w-[348px]")}>
            {search && (
              <div className="relative flex-1">
                <Search className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  type="search"
                  placeholder="Search..."
                  aria-label="Search"
                  value={searchValue}
                  onChange={(e) => onSearchChange?.(e.target.value)}
                  className={cn("h-8 pl-8", columnFilters && "rounded-r-none")}
                />
              </div>
            )}
            {/* Column filters — show/hide table columns. */}
            {columnFilters && (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button
                    variant="outline"
                    size="icon-sm"
                    aria-label="Column filters"
                    className={cn(search && "-ml-px rounded-l-none")}
                  >
                    <SlidersHorizontal />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="start" className="w-52">
                  <DropdownMenuLabel>Columns</DropdownMenuLabel>
                  <DropdownMenuSeparator />
                  {columns.map((c) => (
                    <DropdownMenuCheckboxItem
                      key={c.key}
                      checked={!hiddenColumns?.has(c.key)}
                      onCheckedChange={() => onToggleColumn?.(c.key)}
                      onSelect={(e) => e.preventDefault()}
                    >
                      {c.label}
                    </DropdownMenuCheckboxItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>
            )}
          </div>
        )}

        {show("filters") && <FilterPanel />}
        {show("groupBy") && (
          <GroupByMenu
            dimensions={groupDimensions}
            value={groupBy}
            onChange={onGroupByChange}
          />
        )}
      </div>

      {/* Right cluster */}
      <div className="flex items-center gap-3">
        {savedViews && <SavedViewsMenu />}
        {savedViews && cta && <div className="h-8 w-px bg-border" aria-hidden />}
        {cta && (
          <Button size="sm" onClick={onCreateTask}>
            <Plus />
            Create Form
          </Button>
        )}
      </div>
    </div>
  );
}

import * as React from "react";
import {
  X,
  UserPlus,
  UserMinus,
  LockOpen,
  CircleCheck,
  CircleSlash,
  Copy,
  Trash2,
  MoreHorizontal,
  User,
  Truck,
  Tag,
  Building2,
  Calendar,
  Clock,
  Timer,
  CalendarCheck,
  Package,
  FileText,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "@/components/ui/command";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

/** One verb in the bar. Supplied when a list's actions are its own. */
export interface BulkAction {
  key: string;
  label: string;
  icon: React.ReactNode;
  /** Greyed with `title` as the reason. */
  disabled?: boolean;
  /** Why it is unavailable — a dead control with no explanation is worse. */
  title?: string;
  /** Destructive verbs CONFIRM, the same way Delete does. */
  destructive?: boolean;
  onSelect: () => void;
}

export interface BulkActionBarProps {
  count: number;
  onClear?: () => void;
  /**
   * This list's own verbs, replacing the demo set. Supplied because what can be
   * done to a selection is a property of the RECORDS, not of the bar — the same
   * split the Group By menu makes for dimensions. The chrome (count chip,
   * spacing, hairlines, confirm-on-destructive) stays identical, which is the
   * whole point of not forking a second bar.
   */
  actions?: BulkAction[];
  /** The trailing Copy / Delete / ··· More zone. Off for a fixed action set. */
  tools?: boolean;
  /** What one selected thing is called, for the confirm copy. */
  noun?: string;
  onAssign?: () => void;
  onUnassign?: () => void;
  onUnblock?: () => void;
  onVerify?: () => void;
  onUnverify?: () => void;
  onCopy?: () => void;
  onDelete?: () => void;
  /** A field was picked from the ··· More menu (deep sub-panels deferred). */
  onField?: (key: string) => void;
}

/* Grouped field-edit menu — Figma "Bulk Action FAB_More" (27722:1251). */
const FIELD_GROUPS: {
  heading: string;
  items: { key: string; label: string; icon: React.ReactNode }[];
}[] = [
  {
    heading: "Assignments",
    items: [
      { key: "driver", label: "Driver", icon: <User /> },
      { key: "truck", label: "Truck", icon: <Truck /> },
