/** Side-sheet variants a row action can open (typed inline to avoid a cycle). */
export type RowSheetVariant = "narrow" | "wide" | "dense";

export interface DataTableProps {
  rows: TableRowData[];
  selectedIds: Set<string>;
  onToggleRow: (id: string) => void;
  onToggleAll: (checked: boolean) => void;
  /** Select or clear a whole group at once. Required once `nodes` is passed. */
  onToggleGroup?: (ids: string[], checked: boolean) => void;
  /** Current sort (owned by the parent so it can sort the full dataset). */
  sort: SortState | null;
  /** Toggle sort for a column (parent cycles asc → desc → unsorted). */
  onSort: (key: ColumnKey) => void;
  /** Open a side sheet from a row action. Omit to hide those menu items. */
  onRowAction?: (variant: RowSheetVariant, row: TableRowData) => void;
  /** Hidden column keys (driven by the action bar's column-filters menu). */
  hidden?: Set<ColumnKey>;
  /** Optional control rendered in the header's rightmost cell, revealed on
   *  header hover (e.g. the column tools popover). */
  headerAction?: React.ReactNode;
  /* GROUPING. The table renders what the engine already computed and owns none
     of it — pass `nodes` and it draws headers between the rows, omit them and
     it is the flat table it has always been. A table that decided its own
     grouping would be a second implementation of `groupRows` to keep in step
     with the first. */
  nodes?: GroupNode<TableRowData>[];
  collapsedGroups?: ReadonlySet<string>;
  onToggleGroupCollapse?: (id: string) => void;
  /** Unit for the summed measure on each header, e.g. `gal`. */
  groupUnit?: string;
  /** What one record is called here — "order", "asset", "record". */
  groupNoun?: string;
}

export function DataTable({
  rows,
  selectedIds,
  onToggleRow,
  onToggleAll,
  onToggleGroup,
  sort,
  onSort,
  onRowAction,
  hidden,
  headerAction,
  nodes,
  collapsedGroups,
  onToggleGroupCollapse,
  groupUnit = "",
  groupNoun = "record",
}: DataTableProps) {
  // Cell edits live here (keyed by row id) rather than inside Row: rows unmount
  // when the page changes, and an edit must outlive that.
  const [edits, setEdits] = React.useState<Record<string, string>>({});
  const { editableIcons } = usePreferences();

  const allSelected = rows.length > 0 && rows.every((r) => selectedIds.has(r.id));
  const someSelected = rows.some((r) => selectedIds.has(r.id));
  const headerState = allSelected ? true : someSelected ? "indeterminate" : false;
  /* THE DEFAULT, NOT A FEATURE. Every table's columns move and resize; the DS
     header carries both, so this is the whole of the wiring — which of these
     columns are structure rather than content. */
  const cols = useTableColumns({
    keys: React.useMemo(() => COLUMNS.map((c) => c.key), []),
    fixed: FIXED_COLUMNS,
  });
  const visibleColumns = cols.arrange(COLUMNS.filter((c) => !hidden?.has(c.key)));

  // Measure the scroll viewport so an expanded row's detail can fill the VISIBLE
  // width (not the table's much wider scroll width) — its columns then sit
  // comfortably like the reference and stay pinned as the grid scrolls sideways.
  const scrollRef = React.useRef<HTMLDivElement>(null);
  const [viewportWidth, setViewportWidth] = React.useState<number>();
  React.useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    const measure = () => setViewportWidth(el.clientWidth);
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  return (
    // Outer stroke around the whole table (Figma 28165:3758) — bound to the
    // `border` token (follows the FP variable; updated to FP/Outline 1), rounded.
    // This element owns BOTH scroll axes so the sticky header pins to its top; the
    // shadcn <Table> wraps the table in its own `overflow-x-auto` div — neutralize
    // it (`table-container` → overflow-visible) so THIS element is the sticky
    // header's scroll anchor, not that inner wrapper.
    <div
      ref={scrollRef}
      className="h-full overflow-auto rounded-md border border-border [&_[data-slot=table-container]]:overflow-visible"
    >
      <Table style={{ tableLayout: "fixed" }}>
        <colgroup>
          {visibleColumns.map((c) => (
            <col key={c.key} style={{ width: `${cols.widthOf(c)}px` }} />
          ))}
        </colgroup>
        <TableHeader className="sticky top-0 z-20">
          <TableRow className="group/hdr h-10">
            {visibleColumns.map((col) => {
              const active = sort?.key === col.key;
              const SortIcon = !active
                ? ChevronsUpDown
                : sort.dir === "asc"
                  ? ArrowUp
                  : ArrowDown;
              return (
                <TableColumnHeader
                  key={col.key}
                  cols={cols}
                  col={col}
                  aria-sort={
                    active ? (sort.dir === "asc" ? "ascending" : "descending") : undefined
                  }
                  className={cn(
                    // Solid fill (Surface 1a) + bottom hairline so body rows
                    // scroll UNDER the header, not through the titles. Stickiness
                    // is on the <thead> (th-level sticky is unreliable with
                    // collapsed table borders).
                    "border-b border-fp-outline-1 bg-fp-table-header px-3 text-xs font-medium text-muted-foreground",
                    col.align === "right" && "text-right"
                  )}
                >
                  {col.key === "select" ? (
                    <Checkbox
                      checked={headerState}
                      onCheckedChange={(c) => onToggleAll(c === true)}
                      aria-label="Select all rows"
                    />
                  ) : col.label && col.sortable ? (
                    <button
                      type="button"
                      onClick={() => onSort(col.key)}
                      aria-label={`Sort by ${col.label}`}
                      className={cn(
                        "inline-flex items-center gap-1 outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50",
                        active && "text-foreground",
                        col.align === "right" && "flex-row-reverse"
                      )}
                    >
                      {col.label}
                      <SortIcon
                        className={cn("size-3.5", active ? "opacity-100" : "opacity-70")}
                      />
                    </button>
                  ) : col.label ? (
                    <span>{col.label}</span>
                  ) : col.key === "actions" ? (
                    <div className="flex justify-end">{headerAction}</div>
                  ) : null}
                </TableColumnHeader>
              );
            })}
          </TableRow>
        </TableHeader>
        <TableBody>
          {(
            nodes ??
            rows.map((row) => ({
              kind: "row" as const,
              id: row.id,
              depth: 0,
              row,
            }))
          ).map((node, idx) =>
            node.kind === "group" ? (
              <GroupHeaderRow
                key={node.id}
                /* +1 for the selection column, which is not in `COLUMNS`. */
                colSpan={visibleColumns.length + 1}
                depth={node.depth}
                label={node.label}
                dimLabel={node.dimLabel}
                count={node.count}
                measure={node.measure}
                unit={groupUnit}
                noun={groupNoun}
                collapsed={Boolean(collapsedGroups?.has(node.id))}
                onToggle={() => onToggleGroupCollapse?.(node.id)}
                /* Reads the group's WHOLE membership, so a collapsed group
                   still reports honestly rather than describing the rows that
                   happen to be drawn. */
                selection={{
                  state: groupSelectionState(node.rowIds, selectedIds),
                  onChange: (checked) => onToggleGroup?.(node.rowIds, checked),
                }}
              />
            ) : (
              <Row
                key={node.id}
                row={node.row}
                columns={visibleColumns}
                selected={selectedIds.has(node.row.id)}
                onToggle={() => onToggleRow(node.row.id)}
                onRowAction={onRowAction}
                // First row demonstrates an expandable nested sub-table.
                expandable={!nodes && idx === 0}
                detailWidth={viewportWidth}
                editableValue={edits[node.row.id] ?? node.row.editable}
                onEditableChange={(next) =>
                  setEdits((prev) => ({ ...prev, [node.row.id]: next }))
                }
                editableIcons={editableIcons}
              />
            )
          )}
        </TableBody>
      </Table>
    </div>
  );
}

function Row({
  row,
  columns,
  selected,
  onToggle,
  onRowAction,
  expandable = false,
  detailWidth,
  editableValue,
  onEditableChange,
  editableIcons,
}: {
  row: TableRowData;
  columns: ColumnDef[];
  selected: boolean;
  onToggle: () => void;
  editableValue: string;
  onEditableChange: (next: string) => void;
  editableIcons: Record<"leading" | "trailing", boolean>;
  onRowAction?: (variant: RowSheetVariant, row: TableRowData) => void;
  /** When true, the row shows a disclosure chevron that reveals a nested table. */
  expandable?: boolean;
  /** Visible viewport width, so the expanded detail fills the screen, not the
   *  table's wider scroll width. */
  detailWidth?: number;
}) {
  const [switchOn, setSwitchOn] = React.useState(row.switchOn);
  const [toggle, setToggle] = React.useState(row.toggle);
  const [expanded, setExpanded] = React.useState(false);

  // One renderer per column key — header and body share the same visible set,
  // so hiding a column (column-filters menu) drops both in lockstep.
  const cells: Record<ColumnKey, React.ReactNode> = {
    select: (
      <Checkbox
        checked={selected}
        onCheckedChange={onToggle}
        aria-label={`Select ${row.id}`}
      />
    ),
    status: <StatusChip tone={statusTone(row.status)}>{row.status}</StatusChip>,
    editable: (
      <CellEditable
        value={editableValue}
        onChange={onEditableChange}
        leading={editableIcons.leading}
        trailing={editableIcons.trailing}
      />
    ),
    dropdown: (
      <CellDropdown
        title={row.dropdown.title}
        description={row.dropdown.description}
      />
    ),
    descriptive: (
      <TwoLine
        title={row.descriptive.title}
        description={row.descriptive.description}
      />
    ),
    badge: <Badge variant={statusBadgeVariant(row.status)}>{row.status}</Badge>,
    statusBadge: (
      <span className="inline-flex items-center gap-2">
        <Avatar className="size-5">
          <AvatarFallback className="text-[10px]">U</AvatarFallback>
        </Avatar>
        <StatusChip tone={statusTone(row.statusBadge)}>{row.statusBadge}</StatusChip>
      </span>
    ),
    switch: (
      <Switch
        checked={switchOn}
        onCheckedChange={setSwitchOn}
        aria-label="Toggle row"
      />
    ),
    button: (
      <Button variant="outline" size="xs">
        Button
      </Button>
    ),
    iconDropdown: (
      <Button variant="outline" size="icon-sm" aria-label="Open">
        <CirclePlay />
      </Button>
    ),
    progress: <Progress value={row.progress} className="h-1.5 w-24" />,
    image: (
      <div className="size-8 rounded-md border border-border bg-foreground/90" />
    ),
    toggle: (
      <ToggleGroup
        type="single"
        variant="outline"
        size="sm"
        value={toggle}
        onValueChange={(v) => v && setToggle(v)}
      >
        <ToggleGroupItem value="bold" aria-label="Bold" className="px-2">
          <Bold className="size-4" />
        </ToggleGroupItem>
        <ToggleGroupItem value="italic" aria-label="Italic" className="px-2">
          <Italic className="size-4" />
        </ToggleGroupItem>
        <ToggleGroupItem value="underline" aria-label="Underline" className="px-2">
          <Underline className="size-4" />
        </ToggleGroupItem>
      </ToggleGroup>
    ),
    amount: (
      <HoverCard openDelay={120} closeDelay={80}>
        <HoverCardTrigger variant="link" className="ml-auto tabular-nums">
          {currency.format(row.amount)}
        </HoverCardTrigger>
        <HoverCardContent align="end" side="left" className="w-[380px]">
          <InvoiceCard />
        </HoverCardContent>
      </HoverCard>
    ),
    actions: (
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button variant="ghost" size="icon-sm" aria-label="Row actions">
            <MoreHorizontal />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          {onRowAction && (
            <>
              <DropdownMenuItem onSelect={() => onRowAction("narrow", row)}>
                <PanelRightOpen />
                View details
              </DropdownMenuItem>
              <DropdownMenuItem onSelect={() => onRowAction("wide", row)}>
                <Table2 />
                Tank list
              </DropdownMenuItem>
              <DropdownMenuItem onSelect={() => onRowAction("dense", row)}>
                <PackagePlus />
                Assign asset
              </DropdownMenuItem>
              <DropdownMenuSeparator />
            </>
          )}
          <DropdownMenuItem>
            <Pencil />
            Edit
          </DropdownMenuItem>
          <DropdownMenuItem>
            <Share2 />
            Share
          </DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem variant="destructive">
            <Trash2 />
            Delete
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    ),
  };

  return (
    <>
      <TableRow
        data-state={selected ? "selected" : undefined}
        data-expanded={expanded ? "true" : undefined}
        // A subtle tint anchors the parent while its children are open, so the
        // parent row stays at least as prominent as the nested sub-table.
        // Drop the bottom divider when expanded so the green accent rail runs
        // seamlessly from this row into the nested block (no grey notch).
        className={cn(
          "h-14",
          expanded && "border-b-0 bg-fp-row-hover hover:bg-fp-row-hover"
        )}
      >
        {columns.map((col, ci) => (
          <TableCell
            key={col.key}
            className={cn(
              // Dropdown cells zero their padding so the trigger fills the whole
              // cell (full-cell hover, like the form table); others keep px-3.
              col.key === "dropdown" || col.key === "editable" ? "p-0" : "px-3",
              col.align === "right" && "text-right text-sm tabular-nums",
              // When expanded, carry the green accent up the parent row's left
              // edge so the line runs from the top of this row into the nested
              // detail below as one continuous rail.
              ci === 0 && expanded && "relative before:pointer-events-none before:absolute before:inset-y-0 before:left-0 before:w-0.5 before:bg-status-success/70"
            )}
          >
            {col.key === "status" && expandable ? (
              <div className="flex items-center gap-1.5">
                <button
                  type="button"
                  onClick={() => setExpanded((v) => !v)}
                  aria-expanded={expanded}
                  aria-label={expanded ? "Collapse row" : "Expand row"}
                  className="-ml-1 rounded p-0.5 text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                >
                  <ChevronRight
                    className={cn("size-4 transition-transform", expanded && "rotate-90")}
                  />
                </button>
                {cells[col.key]}
              </div>
            ) : (
              cells[col.key]
            )}
          </TableCell>
        ))}
      </TableRow>
      {expandable && expanded && (
        <TableRow className="hover:bg-transparent data-[state=selected]:bg-transparent">
          {/* Recessed surface spans the full row (end-to-end); the inner detail
              is pinned to the visible width so its columns stay comfortable. */}
          <TableCell colSpan={columns.length} className="bg-fp-surface-1b p-0">
            <NestedTable width={detailWidth} />
          </TableCell>
        </TableRow>
      )}
    </>
  );
}

import * as React from "react";
import { ListFilter, ChevronDown, ChevronUp, Search } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

/*
  Faceted Filter panel — Figma "Action Bar Unit · Filter interactions"
  (27665:14074). Opens from the Filters button: a side menu (facets) + an
  options pane (checkbox list, some options expand into sub-selections) + a
  Clear All / Apply Filters footer.
*/

export interface FilterOption {
  key: string;
  label: string;
  sub?: { title: string; items: { key: string; label: string }[] };
}

export interface Facet {
  key: string;
  label: string;
  options: FilterOption[];
  /**
   * Whether this facet's options pane gets a search field.
   *
   * A facet gets one when its list **cannot be taken in at once**; it does not
   * when the list is short enough to scan. On a two-option facet a search field
   * is a control that can only ever filter to one of the two — noise, and it
   * pushes the options down for nothing.
   *
   * This is deliberately an explicit per-facet flag rather than a length
   * threshold. A threshold silently changes a facet's affordance as its options
   * grow or shrink, so the same facet gains and loses a control without anyone
   * deciding.
   */
  searchable?: boolean;
}

const DEFAULT_FACETS: Facet[] = [
  {
    key: "menu-1",
    label: "Menu 1",
    // Long enough that scanning is work — this one earns a search field.
    searchable: true,
    options: [
      { key: "o1", label: "Option Label 1" },
      {
        key: "o4",
        label: "Option Label 4",
        sub: {
          title: "Title 1",
          items: [
            { key: "o4-s1", label: "Sub Selection 1" },
            { key: "o4-s2", label: "Sub Selection 2" },
          ],
        },
      },
      { key: "o2", label: "Option Label 2" },
      { key: "o3", label: "Option Label 3" },
      { key: "o5", label: "Option Label 5" },
      { key: "o6", label: "Option Label 6" },
    ],
  },
  {
    key: "menu-2",
    // Two options: a search field here could only ever filter to one of them.
    label: "Menu 2",
    options: [
      { key: "m2-a", label: "Option Label A" },
      { key: "m2-b", label: "Option Label B" },
    ],
  },
  {
    key: "menu-3",
    label: "Menu 3",
    options: [
      { key: "m3-a", label: "Option Label A" },
      { key: "m3-b", label: "Option Label B" },
      { key: "m3-c", label: "Option Label C" },
      { key: "m3-d", label: "Option Label D" },
    ],
  },
];

export function FilterPanel({
  compact = false,
  facets = DEFAULT_FACETS,
}: {
  compact?: boolean;
  facets?: Facet[];
}) {
  const [open, setOpen] = React.useState(false);
  const [facetKey, setFacetKey] = React.useState(facets[0]?.key ?? "");
  const [checked, setChecked] = React.useState<Set<string>>(new Set());
  const [expanded, setExpanded] = React.useState<string | null>(null);
  const [query, setQuery] = React.useState("");

  const active = facets.find((f) => f.key === facetKey) ?? facets[0];

  // Switching facets clears the query. Carrying it over would let a term typed
  // on a searchable facet silently filter a facet with no field to clear it in.
  const selectFacet = (key: string) => {
    setFacetKey(key);
    setQuery("");
    setExpanded(null);
  };

  const toggle = (key: string) =>
    setChecked((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });

  const subCount = (opt: FilterOption) =>
    opt.sub ? opt.sub.items.filter((s) => checked.has(s.key)).length : 0;

  const options = active.searchable
    ? active.options.filter((o) =>
        o.label.toLowerCase().includes(query.toLowerCase())
      )
    : active.options;

  return (
    <Popover open={open} onOpenChange={setOpen}>
      {compact ? (
        <Tooltip>
          <TooltipTrigger asChild>
            <PopoverTrigger asChild>
              <Button variant="ghost" size="icon-sm" aria-label="Filters">
                <ListFilter />
              </Button>
            </PopoverTrigger>
          </TooltipTrigger>
          <TooltipContent>Filters</TooltipContent>
        </Tooltip>
      ) : (
        <PopoverTrigger asChild>
          <Button variant="outline" size="sm">
            <ListFilter />
            Filters
          </Button>
        </PopoverTrigger>
      )}
      <PopoverContent align="start" className="w-[600px] overflow-hidden p-0">
        <div className="flex h-[264px]">
          {/* Facet side menu */}
          <div className="flex w-[200px] shrink-0 flex-col gap-1 border-r border-border p-2">
            {facets.map((f) => (
              <button
                key={f.key}
                type="button"
                onClick={() => selectFacet(f.key)}
                className={cn(
                  "flex h-8 items-center rounded-md px-2 text-left text-sm outline-none transition-colors hover:bg-accent/60 focus-visible:ring-2 focus-visible:ring-ring/50",
                  active.key === f.key
                    ? "bg-accent text-accent-foreground"
                    : "text-muted-foreground hover:text-foreground"
                )}
              >
                {f.label}
              </button>
            ))}
          </div>

          {/* Options pane */}
          <div className="flex min-w-0 flex-1 flex-col">
            {active.searchable && (
              <div className="p-2">
                <div className="relative">
                  <Search className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    placeholder={`Search ${active.label}…`}
                    aria-label={`Search ${active.label}`}
                    className="h-8 pl-8"
                  />
                </div>
              </div>
            )}

            <div
              className={cn(
                "min-h-0 flex-1 overflow-auto px-2 pb-2",
                // Without the search field above it, the list would start flush
                // against the panel edge.
                !active.searchable && "pt-2"
              )}
            >
              {options.map((opt) => {
                const n = subCount(opt);
                const isOpen = expanded === opt.key;
                return (
                  <div key={opt.key}>
                    <div className="flex h-8 items-center gap-2">
                      <Checkbox
                        checked={checked.has(opt.key)}
                        onCheckedChange={() => toggle(opt.key)}
                        aria-label={opt.label}
                      />
                      <span className="flex-1 truncate text-sm">{opt.label}</span>
                      {opt.sub && (
                        <button
                          type="button"
                          onClick={() => setExpanded(isOpen ? null : opt.key)}
                          aria-expanded={isOpen}
                          className="flex items-center gap-1 rounded-sm text-xs text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                        >
                          {n > 0 && <span>{n} selections</span>}
                          {isOpen ? (
                            <ChevronUp className="size-4" />
                          ) : (
                            <ChevronDown className="size-4" />
                          )}
                        </button>
                      )}
                    </div>

                    {opt.sub && isOpen && (
                      <div className="pl-6">
                        <p className="px-2 py-1 text-xs text-muted-foreground">
                          {opt.sub.title}
                        </p>
                        {opt.sub.items.map((s) => (
                          <div key={s.key} className="flex h-8 items-center gap-2">
                            <Checkbox
                              checked={checked.has(s.key)}
                              onCheckedChange={() => toggle(s.key)}
                              aria-label={s.label}
                            />
                            <span className="truncate text-sm">{s.label}</span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="flex h-16 items-center justify-between border-t border-border px-4">
          <Button variant="ghost" size="sm" onClick={() => setChecked(new Set())}>
            Clear All
          </Button>
          <Button size="sm" onClick={() => setOpen(false)}>
            Apply Filters
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

import * as React from "react";
import { Group, Rows3, Check, Layers, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

/*
  Group By menu — Figma "Action Bar Unit · Group by" (28025:1274).

  Two modes, so one component serves both the showcase and a real list:

  • UNCONTROLLED (no `value`) — the original demo behaviour, single-select,
    state kept privately. Every existing caller lands here unchanged.
  • CONTROLLED (`value` + `onChange`) — an ORDERED, multi-select stack. The
    order is the design: the first dimension is the outer grouping, and picking
    Status before Customer splits every customer in two, which destroys the
    per-customer total that was the reason to group at all.

  `max` caps the depth (2 by default). Past two levels the indent eats the
  first column and the headers outnumber what they organise.

  Dimensions are supplied by the caller because they are a property of the
  DATA, not of the control. The default list below is illustrative only — a
  real list passes its own, since a dimension with no backing field can never
  group anything.
*/

export interface GroupByDimension {
  key: string;
  label: string;
  /**
   * A record belongs to every value it carries — three products, three groups —
   * so group counts deliberately sum past the list total. Marked in the menu.
   */
  multi?: boolean;
}

/** Illustrative default. Real lists pass `dimensions`. */
const DEMO_DIMENSIONS: GroupByDimension[] = [
  { key: "Status", label: "Status" },
  { key: "Customer", label: "Customer" },
  { key: "ShipTo", label: "Ship To" },
  { key: "Created At", label: "Created At" },
  { key: "Type", label: "Type" },
  { key: "Planned At", label: "Planned At" },
  { key: "Driver", label: "Driver" },
  { key: "Truck", label: "Truck" },
];

export interface GroupByMenuProps {
  compact?: boolean;
  /** Groupable dimensions for THIS list. */
  dimensions?: GroupByDimension[];
  /** Active dimension keys, outermost first. Supply to control the menu. */
  value?: string[];
  onChange?: (next: string[]) => void;
  /** Maximum nesting depth. */
  max?: number;
}

export function GroupByMenu({
  compact = false,
  dimensions = DEMO_DIMENSIONS,
  value,
  onChange,
  max = 2,
}: GroupByMenuProps) {
  const controlled = value !== undefined;
  const [own, setOwn] = React.useState<string[]>([]);
  const active = controlled ? value : own;
  const setActive = (next: string[]) => {
    if (!controlled) setOwn(next);
    onChange?.(next);
  };

  const toggle = (key: string) => {
    if (active.includes(key)) {
      setActive(active.filter((k) => k !== key));
      return;
    }
    // Uncontrolled keeps the original single-select behaviour.
    if (!controlled) {
      setActive([key]);
      return;
    }
    // At the cap the newest choice replaces the innermost, so the menu always
    // responds — a dead click with no explanation is worse than a swap.
    setActive(
      active.length >= max ? [...active.slice(0, max - 1), key] : [...active, key]
    );
  };

  const activeDims = active
    .map((k) => dimensions.find((d) => d.key === k))
    .filter((d): d is GroupByDimension => Boolean(d));
  const summary = activeDims.map((d) => d.label).join(" › ");
  const label = summary ? `Group by: ${summary}` : "Group By";

  return (
    <DropdownMenu>
      {compact ? (
        <Tooltip>
          <TooltipTrigger asChild>
            <DropdownMenuTrigger asChild>
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label={label}
                className={active.length > 0 ? "bg-accent text-foreground" : undefined}
              >
                <Group />
              </Button>
            </DropdownMenuTrigger>
          </TooltipTrigger>
          <TooltipContent>{label}</TooltipContent>
        </Tooltip>
      ) : (
        /* A plain JS comment, not `{/* … *\/}`: this is a ternary branch, an
           EXPRESSION slot, so a JSX comment plus an element would be two things
           where one is allowed. `bg-transparent` makes the button outline-only —
           the `outline` variant fills with `bg-background`, the APP background,
           which is right when the control sits on it and wrong on the white
           content layer where every toolbar puts this menu. The stroke moves to
           `--input` to match the search field beside it — the variant already
           uses `--input` in dark, so light was the odd one out. */
        <DropdownMenuTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            className={active.length > 0 ? "text-foreground" : undefined}
          >
            <Group />
            {label}
          </Button>
        </DropdownMenuTrigger>
      )}
      <DropdownMenuContent align="start" className="max-h-[360px] w-56 overflow-y-auto">
        <DropdownMenuLabel className="flex items-center justify-between gap-2 text-xs font-normal text-muted-foreground">
          <span>Group rows by</span>
          {controlled && max > 1 && (
            <span className="tabular-nums">
              {active.length}/{max}
            </span>
          )}
        </DropdownMenuLabel>
        <DropdownMenuSeparator />
        {dimensions.map((d) => {
          const rank = active.indexOf(d.key);
          return (
            <DropdownMenuItem
              key={d.key}
              /* Keeps the menu open so a two-level stack is one visit. */
              onSelect={(e) => {
                e.preventDefault();
                toggle(d.key);
              }}
            >
              <Rows3 />
              <span className="truncate">{d.label}</span>
              {d.multi && (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Layers className="size-3.5 shrink-0 text-muted-foreground" />
                  </TooltipTrigger>
                  <TooltipContent>
                    A record appears in every group it matches, so the counts add
                    up to more than the list total.
                  </TooltipContent>
                </Tooltip>
              )}
              {rank !== -1 &&
                (controlled && max > 1 ? (
                  <span
                    className={cn(
                      "ml-auto flex size-4 shrink-0 items-center justify-center rounded-full",
                      "bg-brand text-[10px] font-medium text-brand-foreground tabular-nums"
                    )}
                    aria-label={`Level ${rank + 1}`}
                  >
                    {rank + 1}
                  </span>
                ) : (
                  <Check className="ml-auto size-4 shrink-0" />
                ))}
            </DropdownMenuItem>
          );
        })}
        {controlled && active.length > 0 && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuItem onSelect={() => setActive([])}>
              <X />
              Clear grouping
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { ChevronDown, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { Checkbox } from "@/components/ui/checkbox";
import { TableCell, TableRow } from "@/components/ui/table";
import { formatMeasure } from "./grouping";

/*
  One group header row, shared by every table shell so grouping looks identical
  wherever it is turned on.

  It spans every column rather than sitting in one, because a group header is
  not a record — it belongs to the table, not to the columns. What it carries is
  fixed by the rule the engine encodes: label · count · the one summed measure
  for this list. A list picks that measure; nothing else on it adds up to
  something true.

  The depth-0 header sticks under the column header while its rows scroll, so
  you never lose track of which group you are reading. Nested headers do not
  stick: two stacked sticky bands eat the top of a short group.

  HEADERS INDENT, ROWS DO NOT. Indenting the rows too would push the checkbox
  column out from under its own header and break column alignment across groups
  — and column alignment is the thing a data grid is for. The header bands carry
  the nesting on their own.

  THE BAND FILL IS `--fp-lane`, MEASURED. The obvious pick, `--fp-surface-1a`,
  is #ffffff in light — identical to the table's own ground — so the band simply
  vanished there while looking correct in dark. `--muted` fails the same test the
  other way round (#1b2028 in dark, the content layer exactly). `--fp-lane` is
  #f4f5f8 / #2a2f37: distinct from the body in BOTH themes, and it already means
  "the band a group of rows lives in" in the DS's board view. `--fp-row-hover`
  would also have worked but is spoken for.
*/

export interface GroupHeaderRowProps {
  colSpan: number;
  depth: number;
  label: string;
  /** The dimension that produced the group — shown when nested, for context. */
  dimLabel: string;
  count: number;
  /** Summed measure, already totalled. Omit on a list with nothing to sum. */
  measure?: number;
  /** Unit for that measure, e.g. `gal`. Empty renders the bare number. */
  unit?: string;
  /** What one record is called here — "order", "asset", "account". */
  noun: string;
  collapsed: boolean;
  onToggle: () => void;
  /** Omitted on lists without row selection. */
  selection?: {
    state: boolean | "indeterminate";
    onChange: (checked: boolean) => void;
  };
}

/** 20px per level — enough to read as nesting, cheap enough to afford twice. */
const INDENT = 20;

export function GroupHeaderRow({
  colSpan,
  depth,
  label,
  dimLabel,
  count,
  measure,
  unit,
  noun,
  collapsed,
  onToggle,
  selection,
}: GroupHeaderRowProps) {
  return (
    <TableRow
      className={cn(
        "h-10 border-b border-fp-outline-1 hover:bg-transparent",
        // z-10 keeps it under the column header (z-20) and over the body rows.
        depth === 0 && "sticky top-10 z-10"
      )}
    >
      <TableCell colSpan={colSpan} className="bg-fp-lane p-0">
        {/* The header spans every column, so on a wide table it is far wider
            than the content layer on screen. Pinning the content block
            to the left edge of the horizontal scroll keeps the label, the count
            and the total on screen at any scroll position — right-aligning the
            total instead parked it off the right edge, visible only to someone
            who scrolled looking for it. */}
        <div
          className="sticky left-0 flex h-10 w-fit max-w-full items-center gap-2.5 pr-4"
          style={{ paddingLeft: 12 + depth * INDENT }}
        >
          {selection && (
            <Checkbox
              checked={selection.state}
              onCheckedChange={(c) => selection.onChange(c === true)}
              aria-label={`Select all ${count} ${noun}${count === 1 ? "" : "s"} in ${label}`}
            />
          )}
          <button
            type="button"
            onClick={onToggle}
            aria-expanded={!collapsed}
            className="flex min-w-0 items-center gap-2 rounded-sm text-left outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
          >
            <span className="flex size-4 shrink-0 items-center justify-center text-muted-foreground">
              {collapsed ? (
                <ChevronRight className="size-4" />
              ) : (
                <ChevronDown className="size-4" />
              )}
            </span>
            {depth > 0 && (
              <span className="shrink-0 text-xs text-muted-foreground">
                {dimLabel}
              </span>
            )}
            <span className="truncate text-sm font-medium text-foreground">
              {label}
            </span>
            <span className="shrink-0 rounded-full bg-muted px-1.5 py-0.5 text-[11px] font-medium tabular-nums text-muted-foreground">
              {count}
            </span>
          </button>
          {/* Sits beside the count, not at the far right — see above. Absent
              entirely on a list with nothing to sum, rather than showing a
              zero that means "no measure" and reads as "none". */}
          {measure !== undefined && (
            <span className="shrink-0 text-xs tabular-nums text-muted-foreground">
              {formatMeasure(measure, unit ?? "")}
            </span>
          )}
        </div>
      </TableCell>
    </TableRow>
  );
}

import { ChevronsDownUp, ChevronsUpDown, Layers } from "lucide-react";
import { Button } from "@/components/ui/button";
import { formatMeasure } from "./grouping";

/*
  Footer for a grouped list — what stands in for pagination.

  Row pagination and grouping contradict each other: at 25 rows a page, a group
  straddles the boundary and its header claims a count and a total for orders
  that are not on screen. So while grouped the list scrolls whole and this
  footer reports the shape of it instead of a page position.

  It keeps the same left/centre/right skeleton as `TablePagination` — count on
  the left, controls in the middle, nothing claimed on the right — so the
  bottom of the screen does not jump when grouping turns on.
*/

export interface GroupedListFooterProps {
  groupCount: number;
  rowCount: number;
  /** What one record is called — "order", "asset", "account". */
  noun: string;
  /** Total across the list, in the same measure the headers carry. Omit when
   *  the list has nothing that sums. */
  total?: number;
  unit?: string;
  /**
   * A multi-value dimension is active, so the group counts add up to more than
   * `rowCount`. Said out loud rather than left for someone to discover.
   */
  overCounts: boolean;
  allCollapsed: boolean;
  onExpandAll: () => void;
  onCollapseAll: () => void;
}

export function GroupedListFooter({
  groupCount,
  rowCount,
  noun,
  total,
  unit,
  overCounts,
  allCollapsed,
  onExpandAll,
  onCollapseAll,
}: GroupedListFooterProps) {
  const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? "" : "s"}`;

  return (
    <div className="flex flex-wrap items-center justify-between gap-3 text-sm text-muted-foreground">
      <div className="flex items-center gap-2">
        <span className="tabular-nums">
          {plural(groupCount, "group")} · {plural(rowCount, noun)}
          {total !== undefined && ` · ${formatMeasure(total, unit ?? "")}`}
        </span>
        {overCounts && (
          <span className="flex items-center gap-1.5 text-xs">
            <Layers className="size-3.5" />
            {noun}s appear in every group they match, so the group counts add up
            to more than {rowCount}
          </span>
        )}
      </div>

      <Button
        variant="ghost"
        size="sm"
        onClick={allCollapsed ? onExpandAll : onCollapseAll}
      >
        {allCollapsed ? <ChevronsUpDown /> : <ChevronsDownUp />}
        {allCollapsed ? "Expand all" : "Collapse all"}
      </Button>
    </div>
  );
}

