import * as React from "react";
import { cn } from "@/lib/utils";
import { TableHead } from "@/components/ui/table";
import { ColumnMoveGrip, ColumnResizeHandle } from "./ColumnHandles";
import type { UseTableColumnsResult } from "./useTableColumns";

/**
 * A table's column header. Render this instead of `<TableHead>` and the column
 * moves and resizes — there is nothing else to wire.
 *
 * WHAT IT CARRIES, so that no table has to remember it:
 *
 *  • the drag props that make the header the move target, and the keyboard
 *    ⌘/Ctrl + ← → that moves it without a pointer;
 *  • the drop indicator — the dragged header fades, the one it will land
 *    against draws a rule on the side it will land on;
 *  • `ColumnResizeHandle` on the right edge and `ColumnMoveGrip` at the label,
 *    both lit by this header's own hover and by nothing else;
 *  • `group/th`, `relative` and the focus ring the two of them depend on.
 *
 * A FIXED column gets none of it: the leading select box and the trailing
 * row-open cell are the frame a row is read inside rather than content, and the
 * trailing one is pinned to the right edge so it survives a sideways scroll.
 */
export function TableColumnHeader({
  cols,
  col,
  className,
  children,
  ...props
}: {
  /** The `useTableColumns` result. */
  cols: UseTableColumnsResult;
  col: { key: string; width: number };
} & React.ComponentProps<typeof TableHead>) {
  const fixed = cols.isFixed(col.key);
  const resize = cols.resizeProps(col);

  return (
    <TableHead
      {...cols.headerProps(col.key)}
      {...props}
      className={cn(
        "group/th relative",
        !fixed && "cursor-grab",
        // The column being dragged fades out of the way.
        "data-[dragging]:opacity-40",
        // The one it will land against draws a rule on the side it lands on.
        "before:pointer-events-none before:absolute before:inset-y-0 before:w-0.5 before:bg-transparent",
        "data-[drop=before]:before:left-0 data-[drop=before]:before:bg-ring",
        "data-[drop=after]:before:right-0 data-[drop=after]:before:bg-ring",
        "outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50",
        className
      )}
    >
      {/* The resize handle is FIRST so the move grip can be its peer and step
          aside once the pointer actually reaches the divider. */}
      {resize && <ColumnResizeHandle {...resize} />}
      {!fixed && <ColumnMoveGrip />}
      {children}
    </TableHead>
  );
}

import * as React from "react";
import { MoreHorizontal } from "lucide-react";
import {
  Pagination,
  PaginationContent,
  PaginationItem,
  PaginationLink,
  PaginationNext,
  PaginationPrevious,
} from "@/components/ui/pagination";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { paginationRange } from "./data";

/**
 * Jump-to-page — Figma 27728:13260. The `…` ellipsis is a popover trigger;
 * the user types a page number and presses Enter to jump. Progressive
 * disclosure: no separate go-to field on the bar.
 */
function JumpToPage({
  totalPages,
  onJump,
}: {
  totalPages: number;
  onJump: (page: number) => void;
}) {
  const [open, setOpen] = React.useState(false);
  const [value, setValue] = React.useState("");

  const submit = () => {
    const n = Number.parseInt(value, 10);
    if (!Number.isNaN(n) && n >= 1 && n <= totalPages) {
      onJump(n);
      setOpen(false);
      setValue("");
    }
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label="Jump to page"
          className="flex size-9 items-center justify-center rounded-md text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
        >
          <MoreHorizontal className="size-4" />
        </button>
      </PopoverTrigger>
      <PopoverContent
        align="center"
        className="flex w-auto flex-col gap-1 rounded-lg bg-fp-surface-1b p-1"
      >
        <span className="px-1 text-xs font-medium text-primary">Jump to page</span>
        <Input
          autoFocus
          value={value}
          inputMode="numeric"
          placeholder="Page #"
          aria-label="Page number"
          onChange={(e) => setValue(e.target.value.replace(/[^0-9]/g, ""))}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              submit();
            }
          }}
          className="h-8 w-20 rounded-md border-fp-outline-2 bg-fp-surface-1a"
        />
      </PopoverContent>
    </Popover>
  );
}

export interface TablePaginationProps {
  /** 1-based current page. */
  page: number;
  /** Rows per page. */
  pageSize: number;
  /** Total row count across all pages. */
  total: number;
  pageSizeOptions?: number[];
  onPageChange: (page: number) => void;
  onPageSizeChange: (size: number) => void;
  /**
   * Override the footer band. The default is `h-9` — exactly the 36px controls,
   * so the PAGE owns the rhythm: the gap above the footer and the gap below it
   * are set by the page's own padding, not baked into the band.
   *
   * Pass `h-[72px]` for the original Figma band, which centres the controls with
   * 18px of its own air each side. Nothing in the DS wants that any more — see
   * the note on the root element.
   */
  className?: string;
}

const DEFAULT_PAGE_SIZES = [10, 25, 50, 100];

/**
 * Footer — Figma "FP Pagination" (27631:11152). Three zones: range info (left),
 * windowed page controls (center, per `paginationRange`), rows-per-page Select
 * (right). Active page uses the FP/Outline-2 outline treatment.
 */
export function TablePagination({
  page,
  pageSize,
  total,
  pageSizeOptions = DEFAULT_PAGE_SIZES,
  onPageChange,
  onPageSizeChange,
  className,
}: TablePaginationProps) {
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  const from = total === 0 ? 0 : (page - 1) * pageSize + 1;
  const to = Math.min(page * pageSize, total);
  const items = paginationRange(page, totalPages);

  const go = (p: number) => (e: React.MouseEvent) => {
    e.preventDefault();
    if (p >= 1 && p <= totalPages && p !== page) onPageChange(p);
  };

  /*
    `h-9`, not the Figma frame's `h-[72px]`.

    The controls inside are 36px, so a 72px band adds 18px of its own air above
    and below them. On a screen whose vertical rhythm is set by the page, that
    fights the page: measured, the footer sat 34px off the panel bottom (18 from
    the band + 16 from the content layer's padding) while pressed FLUSH against
    the table — a 0px gap above and a doubled one below.

    The band is now exactly its content and the page does the spacing: callers
    wrap it in `mt-4`, and the content layer's own padding gives the 16px below.
    Measured across the DS screens and the four prototype list screens, before ->
    after: band 72 -> 36, table 589 -> 609, table->footer 0 -> 16, footer->panel
    16 -> 16.

    The 72px frame almost certainly had the page padding baked into it, which is
    why the default was backwards. `className="h-[72px]"` restores it if a screen
    genuinely wants the band to own the rhythm.
  */
  return (
    <div
      className={cn(
        "flex h-9 items-center justify-between text-sm text-muted-foreground",
        className
      )}
    >
      {/* `whitespace-nowrap`: one short phrase that must never break mid-sentence.
          The old 72px band hid this — at a narrow viewport the label wrapped to
          three lines (60px) and simply had room. In a band that is exactly its
          content it overflowed by 24px instead. `shrink-0` keeps flex from
          squeezing it into a wrap in the first place. */}
      <span className="shrink-0 whitespace-nowrap">
        Showing {from.toLocaleString()}-{to.toLocaleString()} of{" "}
        {total.toLocaleString()}
      </span>

      <Pagination className="mx-0 w-auto">
        <PaginationContent>
          <PaginationItem>
            <PaginationPrevious
              href="#"
              aria-disabled={page <= 1}
              className={page <= 1 ? "pointer-events-none opacity-50" : undefined}
              onClick={go(page - 1)}
            />
          </PaginationItem>

          {items.map((item, i) =>
            item === "ellipsis" ? (
              <PaginationItem key={`e${i}`}>
                <JumpToPage totalPages={totalPages} onJump={onPageChange} />
              </PaginationItem>
            ) : (
              <PaginationItem key={item}>
                <PaginationLink
                  href="#"
                  isActive={item === page}
                  onClick={go(item)}
                  className={
                    /* THE TABLE HEADER'S COLOUR (Pavan, 2026-10-14) — the
                       selected page wears the same quiet fill as the header. */
                    item === page
                      ? "border-fp-outline-2 bg-fp-table-header"
                      : undefined
                  }
                >
                  {item}
                </PaginationLink>
              </PaginationItem>
            )
          )}

          <PaginationItem>
            <PaginationNext
              href="#"
              aria-disabled={page >= totalPages}
              className={
                page >= totalPages ? "pointer-events-none opacity-50" : undefined
              }
              onClick={go(page + 1)}
            />
          </PaginationItem>
        </PaginationContent>
      </Pagination>

      {/* Rows-per-page */}
      <Select
        value={String(pageSize)}
        onValueChange={(v) => onPageSizeChange(Number(v))}
      >
        <SelectTrigger
          size="sm"
          aria-label="Rows per page"
          /* A QUIET ROWS-PER-PAGE (Pavan, 2026-10-14 — tried on the portal's
             Orders, then everywhere): white, 12px type, 58px wide, 28px tall,
             6px corners. */
          className="h-7 w-[58px] gap-1 rounded-sm border-fp-outline-2 bg-fp-surface-1b px-2 text-xs data-[size=sm]:h-7 [&_svg]:size-3.5"
        >
          <SelectValue />
        </SelectTrigger>
        <SelectContent className="min-w-[58px]">
          {pageSizeOptions.map((opt) => (
            <SelectItem key={opt} value={String(opt)} className="text-xs">
              {opt}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

import * as React from "react";
import { SearchX } from "lucide-react";
import { PageHeader } from "./PageHeader";
import { ActionBar } from "./ActionBar";
import { DataTable } from "./DataTable";
import { BulkActionBar } from "./BulkActionBar";
import { TablePagination } from "./TablePagination";
import { GroupedListFooter } from "./GroupedListFooter";
import { useGrouping } from "./useGrouping";
import { FormLayout } from "@/components/form-layout";
import { SideSheet, type SideSheetVariant } from "@/components/side-sheet";
import { Button } from "@/components/ui/button";
import { usePreferences } from "@/components/preferences";
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty";
import { COLUMNS, SAMPLE_GROUP_DIMS, SAMPLE_ROWS, sortRows } from "./data";
import type { ColumnKey, SortState, TableRow } from "./types";

/** Columns the column-filters menu can toggle (everything with a header label). */
const TOGGLE_COLUMNS = COLUMNS.filter((c) => c.label).map((c) => ({
  key: c.key as string,
  label: c.label,
}));

/** Free-text match across a row's visible text columns. */
function matchesSearch(row: TableRow, q: string): boolean {
  const haystack = [
    row.status,
    row.dropdown.title,
    row.dropdown.description,
    row.descriptive.title,
    row.descriptive.description,
    row.badge,
  ]
    .join(" ")
    .toLowerCase();
  return haystack.includes(q);
}

export interface TablesLayoutProps {
  /** Defaults to the sample dataset that mirrors the Figma frame. */
  rows?: TableRow[];
}

/**
 * "Tables Layout" content — Figma frame 27614:56562. Renders inside the
 * AppShell content layer (rail, contextual sidebar, page title, 16px inset).
 * Owns the data view: sort + pagination + row selection + tab state.
 */
export function TablesLayout({ rows = SAMPLE_ROWS }: TablesLayoutProps) {
  const [selectedIds, setSelectedIds] = React.useState<Set<string>>(new Set());
  const [search, setSearch] = React.useState("");
  const [activeTab, setActiveTab] = React.useState("Tab 1");
  const [sort, setSort] = React.useState<SortState | null>(null);
  const [page, setPage] = React.useState(1);
  const [pageSize, setPageSize] = React.useState(25);
  const [formOpen, setFormOpen] = React.useState(false);
  const [sheet, setSheet] = React.useState<SideSheetVariant | null>(null);
  const [hiddenColumns, setHiddenColumns] = React.useState<Set<ColumnKey>>(
    new Set()
  );
  const { actionBar } = usePreferences();

  const toggleColumn = (key: string) =>
    setHiddenColumns((prev) => {
      const next = new Set(prev);
      if (next.has(key as ColumnKey)) next.delete(key as ColumnKey);
      else next.add(key as ColumnKey);
      return next;
    });

  // Filter by search, then sort the full dataset, then slice the current page.
  const query = search.trim().toLowerCase();
  const filtered = React.useMemo(
    () => (query ? rows.filter((r) => matchesSearch(r, query)) : rows),
    [rows, query]
  );
  const sorted = React.useMemo(() => sortRows(filtered, sort), [filtered, sort]);

  /* GROUPING. One hook owns the dimension stack, the collapse set, and the two
     behaviours that are easy to get subtly wrong per screen: pagination is
     suspended while grouped (a group straddling a page boundary would have its
     header claim a total for rows that are not on screen), and the grouped
     column is hidden (a column repeating its own group header on every row is
     dead width). It hands back `visibleRows` already sliced or whole. */
  const grouping = useGrouping<TableRow, ColumnKey>({
    dimensions: SAMPLE_GROUP_DIMS,
    rows: sorted,
    rowId: (r) => r.id,
    measureOf: (r) => r.amount,
    hiddenColumns,
    page,
    pageSize,
  });
  const pageRows = grouping.visibleRows;
  const isEmpty = sorted.length === 0;

  // Sort cycles asc → desc → unsorted; changing sort/size returns to page 1.
  const onSort = (key: ColumnKey) => {
    setSort((prev) => {
      if (prev?.key !== key) return { key, dir: "asc" };
      if (prev.dir === "asc") return { key, dir: "desc" };
      return null;
    });
    setPage(1);
  };

  const onPageSizeChange = (size: number) => {
    setPageSize(size);
    setPage(1);
  };

  const toggleRow = (id: string) =>
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  /* A group header selects its WHOLE group, including rows inside a collapsed
     child — selecting only what happens to be drawn would be a different set
     from the one the header's count describes. */
  const toggleGroup = (ids: string[], checked: boolean) =>
    setSelectedIds((prev) => {
      const next = new Set(prev);
      for (const id of ids) {
        if (checked) next.add(id);
        else next.delete(id);
      }
      return next;
    });

  // Select-all toggles the current page's rows.
  const toggleAll = (checked: boolean) =>
    setSelectedIds((prev) => {
      const next = new Set(prev);
      for (const r of pageRows) {
        if (checked) next.add(r.id);
        else next.delete(r.id);
      }
      return next;
    });

  // The "Create Form" CTA swaps the table view for the Form Layout screen.
  if (formOpen) {
    return <FormLayout onClose={() => setFormOpen(false)} />;
  }

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <PageHeader activeTab={activeTab} onTabChange={setActiveTab} />

      <div className="mt-4 shrink-0">
        <ActionBar
          searchValue={search}
          onSearchChange={(v) => {
            setSearch(v);
            setPage(1);
          }}
          onCreateTask={() => setFormOpen(true)}
          columns={TOGGLE_COLUMNS}
          hiddenColumns={hiddenColumns}
          onToggleColumn={toggleColumn}
          groupDimensions={grouping.menuDimensions}
          groupBy={grouping.groupBy}
          onGroupByChange={(next) => {
            grouping.setGrouping(next);
            setPage(1);
          }}
          visible={actionBar}
        />
      </div>

      {/* Table region — `relative` anchors the floating bulk-action bar so it
          sits 20px above the pagination unit, centred to the content. */}
      <div className="relative mt-4 min-h-0 flex-1">
        {/* Height provider only — the DataTable owns the scroll so its header
            stays sticky (a second scroll container here would hide the header). */}
        <div className="h-full min-h-0">
          {isEmpty ? (
            // Zero-results state — Figma "Empty" (18672:2962), icon media variant.
            <Empty className="h-full">
              <EmptyHeader>
                <EmptyMedia variant="icon">
                  <SearchX />
                </EmptyMedia>
                <EmptyTitle>No matching records</EmptyTitle>
                <EmptyDescription>
                  {query
                    ? `No records match “${search.trim()}”. Try a different term or clear the search.`
                    : "There's nothing here yet."}
                </EmptyDescription>
              </EmptyHeader>
              {query && (
                <EmptyContent>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => {
                      setSearch("");
                      setPage(1);
                    }}
                  >
                    Clear search
                  </Button>
                </EmptyContent>
              )}
            </Empty>
          ) : (
            <DataTable
              rows={pageRows}
              selectedIds={selectedIds}
              onToggleRow={toggleRow}
              onToggleAll={toggleAll}
              sort={sort}
              onSort={onSort}
              onToggleGroup={toggleGroup}
              onRowAction={(variant) => setSheet(variant)}
              hidden={grouping.effectiveHidden}
              nodes={grouping.grouped ? grouping.groups.nodes : undefined}
              collapsedGroups={grouping.collapsed}
              onToggleGroupCollapse={grouping.toggleGroupCollapse}
              /* Amount is currency, so the header says so — a bare number
                 beside a column of dollars is a lie of omission. */
              groupUnit="USD"
              groupNoun="record"
            />
          )}
        </div>

        {selectedIds.size > 0 && (
          <div className="pointer-events-none absolute inset-x-0 bottom-5 flex justify-center">
            <div className="pointer-events-auto">
              <BulkActionBar
                count={selectedIds.size}
                onClear={() => setSelectedIds(new Set())}
                onDelete={() => setSelectedIds(new Set())}
              />
            </div>
          </div>
        )}
      </div>

      {/* `mt-4`, no `border-t`: the table's own row rules already close the list,
          so a full-strength divider on top of them reads as a stray line. The
          16px below comes from the content layer's own padding. */}
      {/* Grouped, the list scrolls whole, so a page position would be a lie.
          The footer keeps the same left/controls skeleton as the pagination
          unit, so the bottom of the screen does not jump when grouping is
          turned on. */}
      <div className="mt-4 shrink-0">
        {grouping.grouped ? (
          <GroupedListFooter
            groupCount={grouping.groups.groupCount}
            rowCount={grouping.groups.rowCount}
            noun="record"
            total={grouping.total}
            unit="USD"
            overCounts={grouping.groups.overCounts}
            allCollapsed={grouping.allCollapsed}
            onExpandAll={grouping.expandAll}
            onCollapseAll={grouping.collapseAll}
          />
        ) : (
          <TablePagination
            page={page}
            pageSize={pageSize}
            total={sorted.length}
            onPageChange={setPage}
            onPageSizeChange={onPageSizeChange}
          />
        )}
      </div>

      {sheet && (
        <SideSheet
          variant={sheet}
          open
          onOpenChange={(open) => !open && setSheet(null)}
        />
      )}
    </div>
  );
}

import type { StatusTone } from "@/components/ui/status-chip";
import type {
  ColumnDef,
  ColumnKey,
  RowStatus,
  SortState,
  TableRow,
} from "./types";
import type { GroupDim } from "./grouping";

/*
  Column order + widths taken verbatim from the Figma column frames:
  select=40, status(Static)=145.9, dropdown=172, descriptive=145.9, badge=85,
  statusBadge=145.9, switch..amount=145.9 each, actions=44.
  `sortable` flags reflect the ↕ glyphs read from the screenshot (ASSUMPTION —
  the exact set is a component variant prop not exposed by the Figma metadata).
*/
export const COLUMNS: ColumnDef[] = [
  { key: "select", label: "", width: 40 },
  { key: "status", label: "Static", width: 145.9, sortable: true },
  { key: "editable", label: "Editable", width: 175, sortable: true },
  { key: "dropdown", label: "Dropdown", width: 172 },
  { key: "descriptive", label: "Descriptive Text", width: 145.9 },
  { key: "badge", label: "Badge", width: 85 },
  { key: "statusBadge", label: "Badge", width: 145.9 },
  { key: "switch", label: "Switch", width: 145.9, sortable: true },
  { key: "button", label: "Button", width: 145.9 },
  { key: "iconDropdown", label: "Dropdown", width: 145.9 },
  { key: "progress", label: "Progress", width: 145.9, sortable: true },
  { key: "image", label: "Image", width: 145.9 },
  { key: "toggle", label: "Toggle Group", width: 145.9 },
  { key: "amount", label: "Amount", width: 145.9, sortable: true, align: "right" },
  { key: "actions", label: "", width: 44 },
];

const STATUS_CYCLE: RowStatus[] = [
  "Success",
  "Success",
  "Processing",
  "Success",
  "Failed",
  "Failed",
  "Failed",
  "Failed",
  "Failed",
  "Failed",
  "Failed",
  "Failed",
  "Failed",
];

const AMOUNTS = [630.44, 812.1, 199.99, 475.22, 275.43, 1040.0, 56.75, 920.18];

/** 1,000 sample rows so pagination is exercised against a realistic dataset. */
export const SAMPLE_ROWS: TableRow[] = Array.from({ length: 1000 }, (_, i) => {
  const status = STATUS_CYCLE[i % STATUS_CYCLE.length];
  return {
    id: `row-${i + 1}`,
    status,
    editable: "Editable Text",
    dropdown: { title: "Table Cell Text", description: "Description Text" },
    descriptive: { title: "Table Cell Text", description: "Description Text" },
    badge: "Badge",
    statusBadge: status,
    switchOn: i % 3 === 0,
    progress: 5 + ((i * 7) % 95),
    toggle: "bold",
    amount: AMOUNTS[i % AMOUNTS.length] + (i % 13),
  };
});

/**
 * THE status mapping for this dataset. Per the DS's colour governance a status
 * carries no colour until a usage rule binds it — the DS ships `StatusTone`
 * channels, and this application-side function is that binding. Everything
 * else that needs a status colour derives from here, so there is one
 * vocabulary rather than two.
 */
export function statusTone(status: RowStatus): StatusTone {
  switch (status) {
    case "Success":
      return "success";
    case "Processing":
      return "processing";
    case "Failed":
      return "failed";
  }
}

/**
 * Badge variant for a row status, DERIVED from `statusTone` so the filled-badge
 * treatment cannot drift from the chip treatment.
 * DS gap: the badge palette has no green "success" variant, so success maps to
 * `verified`; processing → neutral `secondary`; failed → `destructive`.
 */
export function statusBadgeVariant(
  status: RowStatus
): "verified" | "secondary" | "destructive" {
  switch (statusTone(status)) {
    case "success":
      return "verified";
    case "processing":
      return "secondary";
    default:
      return "destructive";
  }
}

/** Value a column sorts on. Columns without per-row data sort as a no-op. */
function sortValue(row: TableRow, key: ColumnKey): string | number {
  switch (key) {
    case "status":
      return row.status;
    case "switch":
      return row.switchOn ? 1 : 0;
    case "progress":
      return row.progress;
    case "amount":
      return row.amount;
    default:
      return 0;
  }
}

/** Pure sort — returns a new array; `null` leaves the order untouched. */
export function sortRows(rows: TableRow[], sort: SortState | null): TableRow[] {
  if (!sort) return rows;
  const factor = sort.dir === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    const av = sortValue(a, sort.key);
    const bv = sortValue(b, sort.key);
    if (av < bv) return -1 * factor;
    if (av > bv) return 1 * factor;
    return 0;
  });
}

/**
 * Page-number windowing — Figma "FP Pagination" rules (27631:11152):
 * anchor first + last, show `siblings` either side of the current page, and
 * collapse the gaps into "ellipsis". Fixed slot count keeps the bar from
 * reflowing as you navigate.
 */
export function paginationRange(
  current: number,
  total: number,
  siblings = 1
): (number | "ellipsis")[] {
  const range = (start: number, end: number) =>
    Array.from({ length: end - start + 1 }, (_, i) => start + i);

  // first + last + current + 2 siblings + 2 ellipsis slots
  const totalSlots = siblings * 2 + 5;
  if (totalSlots >= total) return range(1, total);

  const left = Math.max(current - siblings, 1);
  const right = Math.min(current + siblings, total);
  const showLeftDots = left > 2;
  const showRightDots = right < total - 1;
  const edgeCount = 3 + 2 * siblings;

  if (!showLeftDots && showRightDots) {
    return [...range(1, edgeCount), "ellipsis", total];
  }
  if (showLeftDots && !showRightDots) {
    return [1, "ellipsis", ...range(total - edgeCount + 1, total)];
  }
  return [1, "ellipsis", ...range(left, right), "ellipsis", total];
}

/*
  What the sample list can be grouped BY.

  A property of the DATA, not of the Group By control — which is why the menu
  and the engine both take these as a prop. Three dimensions, not thirteen: on
  this dataset `badge`, `toggle`, `dropdown`, `descriptive` and `editable` are
  the same string on all 1,000 rows, so offering them would hand you a control
  that produces one group containing everything. A dimension with no VARIANCE
  organises exactly as little as one with no backing field.

  PROGRESS SHOWS THE OTHER SHAPE: `valuesOf` returns a DERIVED label, not a
  stored one. Grouping by a raw 0–100 number would make a thousand groups of
  one; the bands are what anyone actually wants to ask about, and `order` keeps
  them in numeric sequence rather than alphabetical.

  MEASURE: Amount. It is the one column on this list that sums to something
  true, so it is what every group header totals.
*/
export const SAMPLE_GROUP_DIMS: GroupDim<TableRow>[] = [
  {
    key: "status",
    label: "Static",
    hides: "status",
    // A real lifecycle, so the groups follow it rather than the alphabet.
    order: ["Processing", "Success", "Failed"],
    valuesOf: (r) => [r.status],
  },
  {
    key: "switch",
    label: "Switch",
    hides: "switch",
    // Two groups answering "what is off", which is the question worth asking.
    order: ["Off", "On"],
    valuesOf: (r) => [r.switchOn ? "On" : "Off"],
  },
  {
    key: "progress",
    label: "Progress",
    hides: "progress",
    order: ["0–24%", "25–49%", "50–74%", "75–100%"],
    valuesOf: (r) => [
      r.progress < 25
        ? "0–24%"
        : r.progress < 50
          ? "25–49%"
          : r.progress < 75
            ? "50–74%"
            : "75–100%",
    ],
  },
];

/*
  Grouping engine — screen-agnostic, and the single source of grouping
  behaviour for every list that offers it.

  It produces DATA, not markup: `groupRows` returns a flat render list of
  group-header and row nodes with a depth on each, so any table shell can render
  grouping without owning the logic. Two shells that each implemented this would
  drift within a release, and the drift would be in the totals.

  Three rules are enforced here rather than left to each screen:

  1. GROUP BY WHAT YOU WANT TOTALS FOR. Every group header carries a count and
     one summed measure — the only column on each list that adds up to something
     true (gallons, units, ship-tos, capacity). `measureOf` supplies it.

  2. DEGENERATE LEVELS ARE SKIPPED. A second dimension that yields exactly one
     child covering its whole parent tells the reader nothing and costs a row
     plus an indent — Customer › Ship To, wherever an account happens to have a
     single site. The header is dropped and the rows rise to the parent.

  3. MULTI-VALUE DIMENSIONS DUPLICATE. A record with three products belongs to
     three product groups. `multi` marks those dimensions so the menu can flag
     them and the footer can say the counts deliberately over-sum.

  Two levels is the cap. It is enforced by the menu, not here.
*/

/** The label a row gets when it has no value for the dimension. Sorts last. */
export const NO_VALUE = "—";

export interface GroupDim<Row> {
  key: string;
  label: string;
  /**
   * A row can land in several groups, so group counts sum past the list total.
   * Marked in the menu and stated in the footer.
   */
  multi?: boolean;
  /** Every group this row belongs to. Empty ⇒ the `NO_VALUE` group. */
  valuesOf: (row: Row) => string[];
  /**
   * The column this dimension is rendered in. While grouped by it, that column
   * repeats its own header on every row, so the table hides it and gives the
   * width back.
   */
  hides?: string;
  /**
   * Group order, for dimensions with a meaningful sequence (a status
   * lifecycle). Anything not listed falls after, alphabetically.
   */
  order?: string[];
}

export type GroupNode<Row> =
  | {
      kind: "group";
      /** Path-unique — `status:Assigned/customer:Morris Group`. */
      id: string;
      depth: number;
      label: string;
      /** The dimension that produced it, for the header's eyebrow. */
      dimLabel: string;
      /** Rows beneath, including those inside a collapsed child. */
      count: number;
      /** Summed measure, or `undefined` on a list with nothing to sum. */
      measure?: number;
      /**
       * The rows this header owns, collapsed or not — so the header checkbox
       * selects the whole group rather than the part that happens to be drawn.
       */
      rowIds: string[];
    }
  | { kind: "row"; id: string; depth: number; row: Row };

interface Bucket<Row> {
  id: string;
  label: string;
  dimLabel: string;
  rows: Row[];
  children: Bucket<Row>[] | null;
}

function compareLabels(a: string, b: string, order?: string[]): number {
  // The empty group is always last: it is the exception, not the first case.
  if (a === NO_VALUE) return b === NO_VALUE ? 0 : 1;
  if (b === NO_VALUE) return -1;
  if (order) {
    const ia = order.indexOf(a);
    const ib = order.indexOf(b);
    if (ia !== -1 || ib !== -1) {
      if (ia === -1) return 1;
      if (ib === -1) return -1;
      return ia - ib;
    }
  }
  return a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" });
}

function bucketize<Row>(
  rows: Row[],
  dim: GroupDim<Row>,
  parentId: string
): Bucket<Row>[] {
  const byLabel = new Map<string, Row[]>();
  for (const row of rows) {
    const values = dim.valuesOf(row);
    const labels = values.length > 0 ? values : [NO_VALUE];
    for (const label of labels) {
      const bucket = byLabel.get(label);
      if (bucket) bucket.push(row);
      else byLabel.set(label, [row]);
    }
  }
  return [...byLabel.entries()]
    .sort((a, b) => compareLabels(a[0], b[0], dim.order))
    .map(([label, bucketRows]) => ({
      id: `${parentId}${parentId ? "/" : ""}${dim.key}:${label}`,
      label,
      dimLabel: dim.label,
      rows: bucketRows,
      children: null,
    }));
}

export interface GroupResult<Row> {
  nodes: GroupNode<Row>[];
  /** Every group id in the tree, so "collapse all" needs no second walk. */
  groupIds: string[];
  /** Headers actually rendered — the footer's "N groups". */
  groupCount: number;
  /** Distinct rows, which is NOT the sum of group counts on a multi dimension. */
  rowCount: number;
  /** True when any active dimension duplicates rows across groups. */
  overCounts: boolean;
}

/**
 * Build the render list.
 *
 * `collapsed` holds the ids of collapsed groups; their descendants are omitted
 * from `nodes` but still counted in every ancestor header, which is the whole
 * point of collapsing — the totals stay true while the rows go away.
 */
export function groupRows<Row>(
  rows: Row[],
  dims: GroupDim<Row>[],
  options: {
    rowId: (row: Row) => string;
    /** The one column that sums to something true. Defaults to a plain count. */
    measureOf?: (row: Row) => number;
    collapsed?: ReadonlySet<string>;
  }
): GroupResult<Row> {
  const { rowId, measureOf, collapsed } = options;
  /* NOT EVERY LIST HAS A MEASURE. Vendors, products, users — nothing on the row
     sums to something true, and a header reading "0" next to a real count is
     worse than a header that simply does not claim one. `undefined` is the
     honest answer, and the header and footer both omit it. */
  const measure = (bucketRows: Row[]) =>
    measureOf ? bucketRows.reduce((n, r) => n + measureOf(r), 0) : undefined;

  if (dims.length === 0) {
    return {
      nodes: rows.map((row) => ({
        kind: "row" as const,
        id: rowId(row),
        depth: 0,
        row,
      })),
      groupIds: [],
      groupCount: 0,
      rowCount: rows.length,
      overCounts: false,
    };
  }

  const nodes: GroupNode<Row>[] = [];
  const groupIds: string[] = [];
  let groupCount = 0;

  const walk = (bucketRows: Row[], depth: number, parentId: string) => {
    const dim = dims[depth];
    if (!dim) {
      for (const row of bucketRows) {
        nodes.push({
          kind: "row",
          // Path-scoped: on a multi dimension the same row appears under
          // several groups, and a bare row id would collide as a React key.
          id: `${parentId}#${rowId(row)}`,
          depth,
          row,
        });
      }
      return;
    }

    const buckets = bucketize(bucketRows, dim, parentId);

    // Rule 2 — a level with one child covering the whole parent adds an indent
    // and no information. Drop the header, keep descending.
    if (depth > 0 && buckets.length === 1 && buckets[0].rows.length === bucketRows.length) {
      walk(bucketRows, depth + 1, parentId);
      return;
    }

    for (const bucket of buckets) {
      groupIds.push(bucket.id);
      groupCount += 1;
      nodes.push({
        kind: "group",
        id: bucket.id,
        depth,
        label: bucket.label,
        dimLabel: bucket.dimLabel,
        count: bucket.rows.length,
        measure: measure(bucket.rows),
        rowIds: bucket.rows.map(rowId),
      });
      if (!collapsed?.has(bucket.id)) {
        walk(bucket.rows, depth + 1, bucket.id);
      }
    }
  };

  walk(rows, 0, "");

  return {
    nodes,
    groupIds,
    groupCount,
    rowCount: rows.length,
    overCounts: dims.some((d) => d.multi),
  };
}

/** The columns to hide while these dimensions are active (rule: no column repeats its own group header). */
export function columnsHiddenByGrouping<Row>(dims: GroupDim<Row>[]): string[] {
  return dims.map((d) => d.hides).filter((k): k is string => Boolean(k));
}

/** `24,132 gal` — group headers, and the footer, read the same formatting. */
export function formatMeasure(value: number, unit: string): string {
  return `${value.toLocaleString("en-US")}${unit ? ` ${unit}` : ""}`;
}

/**
 * Tri-state for a group's header checkbox. Reads the group's WHOLE membership,
 * so a collapsed group still reports honestly instead of describing the rows
 * that happen to be drawn.
 */
export function groupSelectionState(
  rowIds: string[],
  selected: ReadonlySet<string>
): boolean | "indeterminate" {
  if (rowIds.length === 0) return false;
  let hit = 0;
  for (const id of rowIds) if (selected.has(id)) hit += 1;
  if (hit === 0) return false;
  return hit === rowIds.length ? true : "indeterminate";
}

