import * as React from "react";

/*
  COLUMN ORDER, AS A REORDERABLE THING.

  A table's column order is the reader's, not the schema's. Which two columns
  sit side by side is what makes a comparison possible at a glance, and the
  right pair differs by who is looking — dispatch wants Driver next to Planned
  Date, accounting wants Qty next to Status. Hiding the columns in between is
  the workaround people reach for when they cannot move them, and it costs them
  the columns.

  WHAT STAYS PUT. Some columns are structure rather than content: the leading
  select box and the trailing row-open control are the frame the row is read
  inside, and the trailing one is pinned to the right edge so it survives a
  sideways scroll. Those are `fixed` — not draggable, and not droppable either,
  so a column cannot be dropped outside the frame.

  DUAL MODE, like the rest of this folder: pass `value` + `onChange` to keep the
  order in a saved view; leave them off and the hook owns it.
*/

export interface UseColumnOrderOptions {
  /** Every column key, in the order the table declares them. */
  keys: string[];
  /** Keys that cannot move and cannot be moved past — e.g. select, actions. */
  fixed?: string[];
  /** Supply with `onChange` to control the order from outside. */
  value?: string[];
  onChange?: (next: string[]) => void;
  /**
   * Asked at the moment a drag would start. Return false to refuse it — the
   * table uses this to stand down while a pointer is resizing a divider, since
   * both gestures begin on a header and only one of them can be meant.
   */
  canDrag?: () => boolean;
}

export interface ColumnHeaderDragProps {
  draggable: boolean;
  onDragStart?: (e: React.DragEvent) => void;
  onDragOver?: (e: React.DragEvent) => void;
  onDragLeave?: () => void;
  onDrop?: (e: React.DragEvent) => void;
  onDragEnd?: () => void;
  onKeyDown?: (e: React.KeyboardEvent) => void;
  tabIndex?: number;
  title?: string;
  /** Set while this header is the one being dragged. */
  "data-dragging"?: "" | undefined;
  /** "before" | "after" — which edge the drop indicator sits on. */
  "data-drop"?: "before" | "after" | undefined;
}

export interface UseColumnOrderResult {
  order: string[];
  /** Sorts a column list into the current order. Unknown keys keep their place. */
  arrange: <T extends { key: string }>(cols: T[]) => T[];
  /** Everything a `<th>` needs. Spread it. */
  headerProps: (key: string) => ColumnHeaderDragProps;
  /** The key currently being dragged, or null. */
  dragging: string | null;
}

export function useColumnOrder({
  keys,
  fixed = [],
  value,
  onChange,
  canDrag,
}: UseColumnOrderOptions): UseColumnOrderResult {
  const [own, setOwn] = React.useState<string[]>(keys);
  const controlled = value !== undefined;
  const order = controlled ? value : own;

  /* NEW COLUMNS ARE NOT LOST. A saved order predates any column added since,
     so anything the order does not mention is appended in its declared
     position rather than dropped — a stale view should cost you the ordering,
     never the column. */
  const effective = React.useMemo(() => {
    const known = order.filter((k) => keys.includes(k));
    const missing = keys.filter((k) => !known.includes(k));
    if (missing.length === 0) return known;
    const out = [...known];
    for (const k of missing) {
      const at = keys.indexOf(k);
      const before = keys.slice(0, at).reverse().find((p) => out.includes(p));
      out.splice(before ? out.indexOf(before) + 1 : 0, 0, k);
    }
    return out;
  }, [order, keys]);

  const commit = (next: string[]) => {
    if (!controlled) setOwn(next);
    onChange?.(next);
  };

  /* THE KEY LIVES IN A REF AS WELL AS IN STATE. `dragover` can arrive in the
     same tick as `dragstart` — a synthetic drag, or a fast pointer — and a
     handler closed over state that has not re-rendered yet would read null and
     ignore the whole drag. State drives the styling; the ref answers the
     handlers. */
  type Over = { key: string; side: "before" | "after" } | null;
  const dragRef = React.useRef<string | null>(null);
  const overRef = React.useRef<Over>(null);
  const [dragging, setDragging] = React.useState<string | null>(null);
  const [over, setOverState] = React.useState<Over>(null);
  const setOver = (next: Over) => {
    overRef.current = next;
    setOverState(next);
  };

  const isFixed = (k: string) => fixed.includes(k);

  /** Puts `key` where `target` is, on the given side. */
  const move = (key: string, target: string, side: "before" | "after") => {
    if (key === target || isFixed(key) || isFixed(target)) return;
    const next = effective.filter((k) => k !== key);
    const at = next.indexOf(target);
    if (at === -1) return;
    next.splice(side === "before" ? at : at + 1, 0, key);
    commit(next);
  };

  /** One step left or right, skipping nothing — the keyboard equivalent. */
  const nudge = (key: string, delta: -1 | 1) => {
    const movable = effective.filter((k) => !isFixed(k));
    const at = movable.indexOf(key);
    const to = at + delta;
    if (at === -1 || to < 0 || to >= movable.length) return;
    const next = effective.filter((k) => k !== key);
    next.splice(next.indexOf(movable[to]) + (delta === 1 ? 1 : 0), 0, key);
    commit(next);
  };

  const headerProps = (key: string): ColumnHeaderDragProps => {
    if (isFixed(key)) return { draggable: false };
    return {
      draggable: true,
      tabIndex: 0,
      /* The only discoverable place to say so — a header that can be dragged
         looks exactly like one that cannot. */
      title: "Drag to reorder. ⌘/Ctrl + ← → moves it one column.",
      onDragStart: (e) => {
        if (canDrag && !canDrag()) {
          e.preventDefault();
          return;
        }
        dragRef.current = key;
        setDragging(key);
        e.dataTransfer.effectAllowed = "move";
        // Firefox refuses to start a drag without payload.
        e.dataTransfer.setData("text/plain", key);
      },
      onDragOver: (e) => {
        const from = dragRef.current;
        if (!from || from === key) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = "move";
        /* WHICH SIDE depends on where in the header the pointer is, so the
           column lands where the indicator says it will rather than always
           on one side of the target. */
        const r = e.currentTarget.getBoundingClientRect();
        setOver({ key, side: e.clientX < r.left + r.width / 2 ? "before" : "after" });
      },
      onDragLeave: () => {
        if (overRef.current?.key === key) setOver(null);
      },
      onDrop: (e) => {
        e.preventDefault();
        const from = dragRef.current;
        const to = overRef.current;
        if (from && to?.key === key) move(from, key, to.side);
        dragRef.current = null;
        setDragging(null);
        setOver(null);
      },
      onDragEnd: () => {
        dragRef.current = null;
        setDragging(null);
        setOver(null);
      },
      onKeyDown: (e) => {
        /* WITH A MODIFIER, because a bare arrow on a focused header is how you
           get to the next one. */
        if (!e.metaKey && !e.ctrlKey) return;
        if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
        e.preventDefault();
        nudge(key, e.key === "ArrowLeft" ? -1 : 1);
      },
      "data-dragging": dragging === key ? "" : undefined,
      "data-drop": over?.key === key ? over.side : undefined,
    };
  };

  return {
    order: effective,
    arrange: <T extends { key: string }>(cols: T[]) =>
      [...cols].sort((a, b) => effective.indexOf(a.key) - effective.indexOf(b.key)),
    headerProps,
    dragging,
  };
}

import * as React from "react";

/*
  COLUMN WIDTH, AS A DRAGGABLE THING.

  Widths ship as a guess about content nobody has seen. A customer list where
  every name is thirty characters and a list where every name is eight want
  different columns, and the reader is the only one who knows which they have.
  Truncation is not a fit — it is the table telling you the value is there and
  you may not read it.

  THE DIVIDER RESIZES; THE HEADER MOVES. Both gestures start on a header and
  they must not compete, so they are given different targets and different
  cursors: the boundary between two columns is where every spreadsheet puts
  resize, so that is what it does here, and the header's body is what drags the
  column somewhere else. `canDrag` exists so the reorder hook can be told to
  stand down while a resize is in flight — a pointer held on the divider must
  not also start a column drag.

  DUAL MODE, like the rest of this folder: pass `value` + `onChange` to keep the
  widths in a saved view; leave them off and the hook owns them.
*/

export interface UseColumnWidthsOptions {
  /** Keys that cannot be resized — the select box and the pinned row-open cell. */
  fixed?: string[];
  /** Floor, in px. A column narrower than this holds nothing. Default 64. */
  min?: number;
  /** Supply with `onChange` to control the widths from outside. */
  value?: Record<string, number>;
  onChange?: (next: Record<string, number>) => void;
}

export interface ColumnResizeProps {
  onPointerDown: (e: React.PointerEvent) => void;
  onPointerMove: (e: React.PointerEvent) => void;
  onPointerUp: (e: React.PointerEvent) => void;
  onLostPointerCapture: () => void;
  onDoubleClick: () => void;
  onKeyDown: (e: React.KeyboardEvent) => void;
  tabIndex: number;
  role: "separator";
  "aria-orientation": "vertical";
  "aria-label": string;
  draggable: false;
  "data-resizing"?: "" | undefined;
}

export interface UseColumnWidthsResult {
  /** The width to render — the reader's if they set one, else the declared one. */
  widthOf: (col: { key: string; width: number }) => number;
  /** Everything the divider handle needs. Spread it. Null for a fixed column. */
  resizeProps: (col: { key: string; width: number }) => ColumnResizeProps | null;
  /** True while a pointer is dragging a divider — read it, do not render on it. */
  isResizing: () => boolean;
  /** The key being resized, for styling. */
  resizing: string | null;
}

export function useColumnWidths({
  fixed = [],
  min = 64,
  value,
  onChange,
}: UseColumnWidthsOptions = {}): UseColumnWidthsResult {
  const [own, setOwn] = React.useState<Record<string, number>>({});
  const controlled = value !== undefined;
  const widths = controlled ? value : own;

  const commit = (next: Record<string, number>) => {
    if (!controlled) setOwn(next);
    onChange?.(next);
  };

  /* A REF, NOT STATE, for the live drag: `pointermove` fires far faster than
     React re-renders, and a handler reading a stale start point would make the
     column jump back and forth as the two disagreed. */
  const drag = React.useRef<{ key: string; x: number; from: number } | null>(null);
  const [resizing, setResizing] = React.useState<string | null>(null);

  /* A MISSED POINTERUP MUST NOT STRAND THE FLAG. The pointer can be released
     outside the window, or the handle can unmount under it, and either way the
     element's own handler never runs — leaving `drag.current` set, which tells
     the reorder hook to refuse every column drag from then on. One control
     quietly disabling another until reload is the worst kind of bug to find, so
     the release is watched on the window too, for as long as a resize is live. */
  React.useEffect(() => {
    if (!resizing) return;
    const end = () => {
      drag.current = null;
      setResizing(null);
    };
    window.addEventListener("pointerup", end);
    window.addEventListener("pointercancel", end);
    return () => {
      window.removeEventListener("pointerup", end);
      window.removeEventListener("pointercancel", end);
    };
  }, [resizing]);

  const setWidth = (key: string, px: number) =>
    commit({ ...widths, [key]: Math.max(min, Math.round(px)) });

  const resizeProps = (col: { key: string; width: number }) => {
    if (fixed.includes(col.key)) return null;
    const current = widths[col.key] ?? col.width;
    return {
      role: "separator" as const,
      "aria-orientation": "vertical" as const,
      "aria-label": "Resize column",
      tabIndex: 0,
      /* The handle sits inside a draggable `<th>`; without this the browser
         starts a column drag the moment the pointer moves. */
      draggable: false as const,
      onPointerDown: (e: React.PointerEvent) => {
        e.preventDefault();
        e.stopPropagation();
        (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
        drag.current = { key: col.key, x: e.clientX, from: current };
        setResizing(col.key);
      },
      onPointerMove: (e: React.PointerEvent) => {
        const d = drag.current;
        if (!d || d.key !== col.key) return;
        setWidth(col.key, d.from + (e.clientX - d.x));
      },
      onPointerUp: (e: React.PointerEvent) => {
        (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);
        drag.current = null;
        setResizing(null);
      },
      onLostPointerCapture: () => {
        drag.current = null;
        setResizing(null);
      },
      /* BACK TO THE DECLARED WIDTH — the same double-click a spreadsheet gives
         you, and the only way back once a column has been dragged to nothing. */
      onDoubleClick: () => {
        const next = { ...widths };
        delete next[col.key];
        commit(next);
      },
      onKeyDown: (e: React.KeyboardEvent) => {
        if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
        e.preventDefault();
        setWidth(col.key, current + (e.key === "ArrowLeft" ? -16 : 16));
      },
      "data-resizing": resizing === col.key ? ("" as const) : undefined,
    };
  };

  return {
    widthOf: (col) => widths[col.key] ?? col.width,
    resizeProps,
    isResizing: () => drag.current !== null,
    resizing,
  };
}

import * as React from "react";
import {
  columnsHiddenByGrouping,
  groupRows,
  type GroupDim,
} from "./grouping";

/*
  Everything a list screen needs to be groupable, in one hook — so every list
  groups identically instead of near-copies drifting apart.

  It owns the two pieces of state (the ordered dimension stack and which groups
  are collapsed) and derives the rest, including the two behaviours that are
  easy to get subtly wrong per screen:

  • PAGINATION IS SUSPENDED WHILE GROUPED. At a page of rows a group straddles
    the boundary and its header claims a count and a total for records that are
    not on screen. Grouped, the hook hands back every row and the screen swaps
    its pagination footer for `GroupedListFooter`.

  • THE GROUPED COLUMN IS HIDDEN. A column that repeats its own group header on
    every row is dead width. `effectiveHidden` merges those into whatever the
    user hid by hand, without touching that set — so clearing the grouping
    restores exactly the columns they chose.
*/

export interface UseGroupingOptions<Row, K extends string> {
  /** Every dimension this list offers. */
  dimensions: GroupDim<Row>[];
  /** Filtered and sorted rows — the whole list, not a page. */
  rows: Row[];
  rowId: (row: Row) => string;
  /**
   * The one column that sums to something true. OMIT when none does — vendors,
   * products and users have nothing that adds up, and a header claiming "0" is
   * worse than one that claims nothing.
   */
  measureOf?: (row: Row) => number;
  /** Columns the user hid by hand. */
  hiddenColumns: Set<K>;
  page: number;
  pageSize: number;
}

export function useGrouping<Row, K extends string>({
  dimensions,
  rows,
  rowId,
  measureOf,
  hiddenColumns,
  page,
  pageSize,
}: UseGroupingOptions<Row, K>) {
  const [groupBy, setGroupBy] = React.useState<string[]>([]);
  const [collapsed, setCollapsed] = React.useState<Set<string>>(new Set());

  const dims = React.useMemo(
    () =>
      groupBy
        .map((k) => dimensions.find((d) => d.key === k))
        .filter((d): d is GroupDim<Row> => Boolean(d)),
    [groupBy, dimensions]
  );
  const grouped = dims.length > 0;

  /* A key with no dimension behind it holds a slot in the stack and shows in
     the menu's count while producing no groups — which is what happens when a
     list's dimensions change under a saved or restored grouping. `dims` already
     drops it; this makes the value handed back agree. */
  const activeKeys = React.useMemo(() => dims.map((d) => d.key), [dims]);

  const visibleRows = React.useMemo(
    () => (grouped ? rows : rows.slice((page - 1) * pageSize, page * pageSize)),
    [rows, page, pageSize, grouped]
  );

  const groups = React.useMemo(
    () => groupRows(visibleRows, dims, { rowId, measureOf, collapsed }),
    [visibleRows, dims, collapsed, rowId, measureOf]
  );

  const effectiveHidden = React.useMemo(() => {
    if (!grouped) return hiddenColumns;
    const next = new Set(hiddenColumns);
    for (const key of columnsHiddenByGrouping(dims)) next.add(key as K);
    return next;
  }, [hiddenColumns, dims, grouped]);

  /** Menu shape — the engine's dimensions minus the parts it doesn't need. */
  const menuDimensions = React.useMemo(
    () => dimensions.map((d) => ({ key: d.key, label: d.label, multi: d.multi })),
    [dimensions]
  );

  const setGrouping = (next: string[]) => {
    setGroupBy(next);
    // Collapse state is keyed by group path, and every path changes when the
    // dimensions do. Keeping it would collapse arbitrary new groups.
    setCollapsed(new Set());
  };

  const toggleGroupCollapse = (id: string) =>
    setCollapsed((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  const allCollapsed =
    groups.groupIds.length > 0 &&
    groups.groupIds.every((id) => collapsed.has(id));

  return {
    groupBy: activeKeys,
    setGrouping,
    grouped,
    groups,
    collapsed,
    toggleGroupCollapse,
    expandAll: () => setCollapsed(new Set()),
    collapseAll: () => setCollapsed(new Set(groups.groupIds)),
    allCollapsed,
    visibleRows,
    effectiveHidden,
    menuDimensions,
    total: React.useMemo(
      () => (measureOf ? rows.reduce((n, r) => n + measureOf(r), 0) : undefined),
      [rows, measureOf]
    ),
  };
}

import * as React from "react";
import { useColumnOrder, type ColumnHeaderDragProps } from "./useColumnOrder";
import { useColumnWidths, type ColumnResizeProps } from "./useColumnWidths";

/*
  THE TABLE'S COLUMN BEHAVIOUR, IN ONE CALL.

  Reordering and resizing are not features a table opts into — they are what a
  column IS for anyone reading one. Split across two hooks and five header
  classes they were something each table had to remember to wire, and the one
  that forgot looked identical to the one that could not. This composes them,
  wires the guard between them, and hands the result to `TableColumnHeader`,
  which is the only thing a table has to render.

  A new table gets both by using that header. There is no "enable" flag, because
  a table that does not want them is a table whose columns the reader may not
  arrange, and that is not a default anyone should be able to reach for by
  omission.
*/

export interface UseTableColumnsOptions {
  /** Every column key, in the order the table declares them. */
  keys: string[];
  /**
   * Structure, not content — the leading select box and the trailing row-open
   * cell. These neither move nor resize, and nothing can be dropped past them.
   */
  fixed?: string[];
  /** Supply with `onOrderChange` to keep the order in a saved view. */
  order?: string[];
  onOrderChange?: (next: string[]) => void;
  /** Supply with `onWidthsChange` to keep the widths in a saved view. */
  widths?: Record<string, number>;
  onWidthsChange?: (next: Record<string, number>) => void;
}

export interface UseTableColumnsResult {
  /** Sorts a column list into the reader's order. */
  arrange: <T extends { key: string }>(cols: T[]) => T[];
  /** The width to render — the reader's if they set one, else the declared one. */
  widthOf: (col: { key: string; width: number }) => number;
  /** True for a column that is structure rather than content. */
  isFixed: (key: string) => boolean;
  /** Internals `TableColumnHeader` spreads. Callers should not need these. */
  headerProps: (key: string) => ColumnHeaderDragProps;
  resizeProps: (col: { key: string; width: number }) => ColumnResizeProps | null;
}

export function useTableColumns({
  keys,
  fixed = [],
  order,
  onOrderChange,
  widths,
  onWidthsChange,
}: UseTableColumnsOptions): UseTableColumnsResult {
  const width = useColumnWidths({
    fixed,
    value: widths,
    onChange: onWidthsChange,
  });
  /* THE GUARD LIVES HERE so no table can forget it: both gestures start on a
     header, and without this the browser starts a column drag out of a resize
     press. */
  const orderState = useColumnOrder({
    keys,
    fixed,
    value: order,
    onChange: onOrderChange,
    canDrag: () => !width.isResizing(),
  });

  const fixedSet = React.useMemo(() => new Set(fixed), [fixed]);

  return {
    arrange: orderState.arrange,
    widthOf: width.widthOf,
    isFixed: (key) => fixedSet.has(key),
    headerProps: orderState.headerProps,
    resizeProps: width.resizeProps,
  };
}

import * as React from "react";

/*
  THEME + ACCESSIBILITY SETTINGS (Pavan, 2026-10-21; DS ui §10n) — one store
  for the theme (light / dark) and the Accessibility panel's three sliders:

    text     0–100 → type 100%–130% in six steps, a little heavier as it
             grows — `--fp-text-scale`. ONLY THE TEXT GROWS (Pavan,
             2026-10-23): no box widens; the text wraps and cards grow taller
    stroke   0–100 → every rim, divider, field border, lane and chart colour:
             the theme's own value at 0, its WCAG value (3:1+) at 50, the
             MAXIMUM (5:1+) at 100
    background 0–100 → the page, panels, cards and their steps, hover and
             selected fills — theme · WCAG · maximum
    ink      0–100 → secondary and coloured text (muted, status, brand,
             violet, trend, pills) — theme · WCAG (text AAA 7:1) · maximum
             (Pavan, 2026-10-21: Layers split into Background and Text)
    TEXT ON A COLOUR FILL is automatic while either is on: white or dark,
             whichever reads better on the fill as it now is
    display  DISPLAY SIZE — 50% to 150% in five steps, 100% in the middle
             (Pavan, 2026-10-23: not tied to monitors, it scales down too,
             no Auto). It scales EVERYTHING — every component and view — by
             one zoom

  THE WCAG AND MAXIMUM POINTS ARE THE CSS's `.wcag` and `.a11y-max` blocks —
  the values `npm run eval` checks. To mix, all three are read off the page
  in one synchronous pass (the classes are on only while reading, so nothing
  paints), then each token is set inline as a color-mix between the two
  points either side of the slider.
*/

export type Theme = "light" | "dark";
export interface A11y {
  text: number;
  stroke: number;
  background: number;
  ink: number;
  /** Display size — the page zoom, one of DISPLAY_STEPS. */
  display: number;
}
export const A11Y_DEFAULT: A11y = { text: 0, stroke: 0, background: 0, ink: 0, display: 1 };

/** THE TEXT SIZE STEPS — 100% to 130%, 5% apart (stored as 0–100). */
export const TEXT_STEPS = 6;
export const textStepOf = (text: number) => Math.round((text / 100) * TEXT_STEPS);
export const textOfStep = (step: number) => Math.round((step / TEXT_STEPS) * 100);

/** THE DISPLAY SIZE STEPS — the page zoom; 100% is the middle one. */
export const DISPLAY_STEPS = [0.5, 0.75, 1, 1.25, 1.5];
const nearestDisplay = (z: number) => DISPLAY_STEPS.reduce((a, b) => (Math.abs(b - z) < Math.abs(a - z) ? b : a));

const THEME_KEY = "fp-theme-choice";
const A11Y_KEY = "fp-a11y";

/** Rims, dividers, field borders, lanes, chart series — the Stroke slider. */
const STROKE = [
  "--fp-stroke-field",
  "--fp-outline-1",
  "--fp-outline-2",
  "--fp-stroke-hairline",
  "--fp-shell-rim",
  "--fp-shell-guide",
  "--fp-selected-border",
  "--fp-shell-marker",
  "--sidebar-border",
  "--ring",
  ...["grey", "blue", "yellow", "green", "cyan", "purple", "pink", "orange", "red"].map((l) => `--fp-lane-${l}`),
  ...[1, 2, 3, 4, 5, 6, 7, 8].map((n) => `--fp-viz-${n}`),
];
/** Secondary and coloured text — the Text slider. */
const INK = [
  "--fp-ink-3",
  "--fp-danger",
  "--destructive",
  "--status-success",
  "--status-processing",
  "--status-pink",
  "--verified",
  "--fp-selected-strong",
  "--fp-trend-up",
  "--fp-trend-down",
  "--fp-banner-accent-info",
  "--fp-banner-accent-caution",
  "--fp-banner-accent-warning",
  "--fp-banner-accent-success",
  "--accent-violet",
  /* ORANGE TEXT — not --brand, which is the logo's and the brand buttons' fill. */
  "--fp-brand-ink",
  /* MAIN TEXT — pure black (white in dark) at the far end. */
  "--fp-ink-1",
  "--fp-ink-2",
];
/** The page, panels, cards, their steps, hover and selected fills — the Background slider. */
const BACKGROUND = [
  "--fp-surface-base",
  "--fp-surface-1a",
  "--fp-card-1",
  "--fp-card-2",
  "--fp-card-3",
  "--fp-shell-ground",
  "--fp-shell-selected",
  "--fp-emphasis",
  "--fp-emphasis-hover",
  "--fp-emphasis-quiet",
  "--fp-table-header",
  "--fp-board-lane",
  "--fp-row-hover",
  "--fp-banner-caution",
];
/** TEXT ON A FILL — chosen, never blended: white or dark, whichever reads
    better on the fill as the sliders left it. [text token, its fill]. */
const ON_FILL: [string, string][] = [
  ["--primary-foreground", "--primary"],
  ["--brand-foreground", "--brand"],
  ["--accent-violet-foreground", "--accent-violet"],
  ["--verified-foreground", "--verified"],
  ["--status-success-foreground", "--status-success"],
  ["--status-foreground", "--status-success"],
  ["--destructive-foreground", "--destructive"],
];
const LIGHT_INK = "white";
const DARK_INK = "black";

function read<T>(key: string, fallback: T, parse: (v: string) => T | null): T {
  try {
    const v = localStorage.getItem(key);
    return (v ? parse(v) : null) ?? fallback;
  } catch {
    return fallback;
  }
}

/* THE OLD WCAG MODES BECOME THE PANEL AT FULL (2026-10-21). */
const legacy = read<string | null>(THEME_KEY, null, (v) => v);
let theme: Theme = legacy === "dark" || legacy === "wcag-dark" ? "dark" : "light";
let a11y: A11y =
  legacy === "wcag-light" || legacy === "wcag-dark"
    ? { ...A11Y_DEFAULT, text: 30, stroke: 50, background: 50, ink: 50 }
    : read<A11y>(A11Y_KEY, A11Y_DEFAULT, (v) => {
        const o = JSON.parse(v) as Partial<A11y>;
        const n = (x: unknown, d: number) => (Number.isFinite(Number(x)) && x !== null && x !== undefined ? Number(x) : d);
        return {
          text: n(o.text, 0),
          stroke: n(o.stroke, 0),
          /* THE OLD Layers SLIDER BECOMES BOTH. */
          background: n(o.background, n((o as { layers?: number }).layers, 0)),
          /* NO TEXT COLOR SLIDER (2026-10-24) — text follows Contrast. */
          ink: 0,
          /* THE OLD SCREEN SIZES land on the nearest step; Auto on 100%. */
          display: nearestDisplay(
            n(o.display, ({ monitor: 1.1, large: 1.25, tv: 1.5 } as Record<string, number>)[(o as { screen?: string }).screen ?? ""] ?? 1)
          ),
        };
      });

const listeners = new Set<() => void>();
const emit = () => listeners.forEach((l) => l());
const save = () => {
  try {
    localStorage.setItem(THEME_KEY, theme);
    localStorage.setItem(A11Y_KEY, JSON.stringify(a11y));
  } catch {
    // Storage blocked — the settings still hold for this visit.
  }
};

/** Puts the settings on <html>. */
export function applySettings() {
  if (typeof document === "undefined") return;
  const root = document.documentElement;
  const style = root.style;
  root.classList.toggle("dark", theme === "dark");
  root.classList.remove("wcag", "a11y-max");
  root.classList.remove("a11y-ink", "a11y-frame");

  /* TYPE — 100%–130%; the units around it are fitted after. */
  const scale = 1 + (a11y.text / 100) * 0.3;
  style.setProperty("--fp-text-scale", String(scale));
  root.classList.toggle("a11y-text", a11y.text > 0);
  fitUnits();

  /* DISPLAY SIZE — one zoom for the whole page. */
  const zoom = a11y.display;
  if (zoom === 1) style.removeProperty("zoom");
  else style.setProperty("zoom", String(zoom));
  root.classList.toggle("a11y-zoom", zoom !== 1);
  style.setProperty("--fp-zoom", String(zoom));

  style.removeProperty("filter");

  /* COLOURS — read both ends in one pass, then mix. */
  const all = [...STROKE, ...INK, ...BACKGROUND, ...ON_FILL.map(([t]) => t)];
  all.forEach((t) => style.removeProperty(t));
  if (a11y.stroke !== 0 || a11y.background !== 0 || a11y.ink !== 0) mixContrast(root, all);
  if (a11y.background !== 0 || a11y.ink !== 0) textOnFills(root);
  /* THE DARK FRAME — Contrast 80%+ in the light theme: the shell
     ground and the selected nav item jump to near black, white text on them
     (Pavan, 2026-10-21 — no grey between ~#5a and #95 reads at 7:1 either
     way, so it jumps rather than fades). */
  const frame = theme === "light" && a11y.background >= 80;
  root.classList.toggle("a11y-frame", frame);
  if (frame) {
    style.setProperty("--fp-shell-ground", "var(--fp-frame-ground)");
    style.setProperty("--fp-shell-selected", "var(--fp-frame-selected)");
  }
}

function mixContrast(root: HTMLElement, all: string[]) {
  const style = root.style;
  const cs = getComputedStyle(root);
  const from = Object.fromEntries(all.map((t) => [t, cs.getPropertyValue(t).trim()]));
  root.classList.add("wcag");
  const cs2 = getComputedStyle(root);
  const to = Object.fromEntries(all.map((t) => [t, cs2.getPropertyValue(t).trim()]));
  root.classList.add("a11y-max");
  const cs3 = getComputedStyle(root);
  const max = Object.fromEntries(all.map((t) => [t, cs3.getPropertyValue(t).trim()]));
  root.classList.remove("wcag", "a11y-max");
  /* 0 → the theme · 50 → WCAG · 100 → maximum. */
  const blend = (a: string, b: string, pct: number) =>
    pct <= 0 || a === b ? a : pct >= 100 ? b : `color-mix(in oklab, ${b} ${pct}%, ${a})`;
  const mix = (t: string, v: number) => {
    if (!from[t] || !to[t] || v === 0) return;
    const value = v <= 50 ? blend(from[t], to[t], v * 2) : blend(to[t], max[t] || to[t], (v - 50) * 2);
    if (value !== from[t]) style.setProperty(t, value);
  };
  STROKE.forEach((t) => mix(t, a11y.stroke));
  /* TEXT NEVER SITS BELOW ITS GROUND — past the middle, Contrast
     darkens the greys, so Text colour rises with it (it can go further, not
     less). */
  const ink = Math.max(a11y.ink, a11y.background);
  INK.forEach((t) => mix(t, ink));
  /* Faded labels come up to full past the middle (CSS `.a11y-ink`). */
  root.classList.toggle("a11y-ink", ink >= 50);
  BACKGROUND.forEach((t) => mix(t, a11y.background));
}

/* A COLOUR AS IT NOW RENDERS — a probe swatch read back as rgb(). */
function rgbOf(value: string): [number, number, number] | null {
  const el = document.createElement("span");
  el.style.color = value;
  el.style.display = "none";
  document.body.appendChild(el);
  const c = getComputedStyle(el).color;
  el.remove();
  /* A color-mix comes back in the space it was mixed in — oklab here. */
  const ok = /oklab\((-?[\d.]+) (-?[\d.]+) (-?[\d.]+)/.exec(c);
  if (ok) {
    const [L, A, B] = [Number(ok[1]), Number(ok[2]), Number(ok[3])];
    const l = (L + 0.3963377774 * A + 0.2158037573 * B) ** 3;
    const m = (L - 0.1055613458 * A - 0.0638541728 * B) ** 3;
    const s = (L - 0.0894841775 * A - 1.291485548 * B) ** 3;
    const lin = [
      4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
      -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
      -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s,
    ];
    const enc = (x: number) => {
      const v = Math.min(1, Math.max(0, x));
      return v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055;
    };
    return [enc(lin[0]), enc(lin[1]), enc(lin[2])];
  }
  /* …or as color(srgb r g b) in 0–1; plain colours as rgb(). */
  const srgb = /color\(srgb ([\d.]+) ([\d.]+) ([\d.]+)/.exec(c);
  if (srgb) return [Number(srgb[1]), Number(srgb[2]), Number(srgb[3])];
  const m = /rgba?\(([\d.]+),\s*([\d.]+),\s*([\d.]+)/.exec(c);
  return m ? [Number(m[1]) / 255, Number(m[2]) / 255, Number(m[3]) / 255] : null;
}
const luminance = ([r, g, b]: [number, number, number]) => {
  const l = (c: number) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
  return 0.2126 * l(r) + 0.7152 * l(g) + 0.0722 * l(b);
};
const contrast = (a: number, b: number) => (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);

/** WHITE OR DARK on each fill, whichever reads better (Pavan, 2026-10-21). */
function textOnFills(root: HTMLElement) {
  const cs = getComputedStyle(root);
  const white = 1;
  const dark = luminance(rgbOf(DARK_INK)!);
  for (const [fg, fill] of ON_FILL) {
    const v = cs.getPropertyValue(fill).trim();
    const c = v && rgbOf(v);
    if (!c) continue;
    const l = luminance(c);
    root.style.setProperty(fg, contrast(white, l) >= contrast(dark, l) ? LIGHT_INK : DARK_INK);
  }
}

export function setTheme(t: Theme) {
  theme = t;
  save();
  applySettings();
  emit();
}
/** BACK TO DEFAULT — every accessibility setting; the theme stays. */
export function resetA11y() {
  a11y = { ...A11Y_DEFAULT };
  save();
  applySettings();
  emit();
}
export const isDefaultA11y = (a: A11y) =>
  (Object.keys(A11Y_DEFAULT) as (keyof A11y)[]).every((k) => a[k] === A11Y_DEFAULT[k]);
/** The way back when the panel can't be reached: ⌘⌥0 (Ctrl+Alt+0). */
export const RESET_SHORTCUT = typeof navigator !== "undefined" && /Mac/.test(navigator.platform) ? "⌘⌥0" : "Ctrl+Alt+0";

export function setA11y(patch: Partial<A11y>) {
  a11y = { ...a11y, ...patch };
  save();
  applySettings();
  emit();
}

const subscribe = (l: () => void) => {
  listeners.add(l);
  return () => listeners.delete(l);
};
export const useTheme = () => React.useSyncExternalStore(subscribe, () => theme, () => theme);
export const useA11y = () => React.useSyncExternalStore(subscribe, () => a11y, () => a11y);

/*
  TEXT GROWS, BOXES DON'T (Pavan, 2026-10-23) — no unit widens for bigger
  text any more: the nav, a board lane, a sheet keep their width, the text
  wraps onto the next line inside them and the card grows taller (CSS
  `.a11y-text`). Making the boxes bigger is the Display size slider's job.
  The width multipliers stay at 1 so anything still reading them holds.
*/
function fitUnits() {
  if (typeof document === "undefined") return;
  ["--fp-nav-k", "--fp-lane-k", "--fp-scale"].forEach((k) => document.documentElement.style.setProperty(k, "1"));
}

/* ON LOAD — once the stylesheet is in, so both ends can be read. */
if (typeof window !== "undefined") {
  if (document.readyState === "complete") applySettings();
  else window.addEventListener("load", applySettings, { once: true });
  applySettings();
  /* THE ESCAPE HATCHES (Pavan, 2026-10-21) — a shortcut, and `?a11y=reset`
     in the address, put every accessibility setting back to default. */
  window.addEventListener("keydown", (e) => {
    if ((e.metaKey || e.ctrlKey) && e.altKey && e.code === "Digit0") {
      e.preventDefault();
      resetA11y();
    }
  });
  if (new URLSearchParams(window.location.search).get("a11y") === "reset") resetA11y();
}

